package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/** The one way this plugin paints a bar: background, fill, border. */
final class Bars
{
	private static final Color BORDER = new Color(0, 0, 0, 200);

	private Bars()
	{
	}

	/** Filled from the left, {@code fraction} of the width, for the overhead readout and badge rows. */
	static void across(Graphics2D graphics, Rectangle box, double fraction, Color colour, Color background)
	{
		graphics.setColor(background);
		graphics.fillRect(box.x, box.y, box.width, box.height);

		final int filled = (int) Math.round(box.width * clamp(fraction));
		if (filled > 0)
		{
			graphics.setColor(colour);
			graphics.fillRect(box.x, box.y, filled, box.height);
		}

		graphics.setColor(BORDER);
		graphics.drawRect(box.x, box.y, box.width, box.height);
	}

	/** Filled from the bottom, {@code fraction} of the height, for the side pillars. */
	static void up(Graphics2D graphics, Rectangle box, double fraction, Color colour, Color background)
	{
		graphics.setColor(background);
		graphics.fillRect(box.x, box.y, box.width, box.height);

		final int filled = (int) Math.round(box.height * clamp(fraction));
		if (filled > 0)
		{
			graphics.setColor(colour);
			graphics.fillRect(box.x, box.y + box.height - filled, box.width, filled);
		}

		graphics.setColor(BORDER);
		graphics.drawRect(box.x, box.y, box.width, box.height);
	}

	private static double clamp(double fraction)
	{
		return Math.max(0, Math.min(1, fraction));
	}
}

package com.vinnyvangogh.combatvitals;

import lombok.AllArgsConstructor;
import lombok.Getter;

/** What makes an NPC a big target. */
@AllArgsConstructor
public enum BigTargetRule
{
	BOSSES("Bosses only"),
	BOSSES_AND_HP("Bosses + max HP"),
	HP_ONLY("Max HP only");

	@Getter
	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Decides whether an NPC target is a big target (a boss, or an NPC with a
 * high max HP), and so which display it gets.
 *
 * Pure: the plugin passes in whether the game's boss health HUD is showing
 * this NPC, its name and its max HP, so the rules are unit testable.
 */
final class BigTargets
{
	/**
	 * Fallback for when the game's boss HUD is not showing (off in the game's
	 * settings, or not yet set for this NPC). Combat bosses from the OSRS wiki's
	 * Boss page (https://oldschool.runescape.wiki/w/Boss, read 2026-11-04):
	 * the main list, plus minigame and raid bosses. Skilling bosses (Tempoross,
	 * Wintertodt, Zalcano) have no opponent health to show, and quest bosses
	 * are left out because many share names with ordinary monsters ("Black
	 * demon"); Bosses + max HP still catches the big ones. Royal Titans and
	 * Grotesque Guardians are the wiki's names for pairs, so their NPC names
	 * (Branda, Eldric, Dusk, Dawn) are listed too.
	 */
	private static final Set<String> BOSSES = new HashSet<>(Arrays.asList(
		"ahrim the blighted", "karil the tainted", "dharok the wretched", "guthan the infested",
		"torag the corrupted", "verac the defiled", "gemstone crab", "scurrius", "giant mole",
		"deranged archaeologist", "dagannoth supreme", "dagannoth rex", "dagannoth prime", "sarachnis",
		"blood moon", "blue moon", "eclipse moon", "kalphite queen", "kree'arra", "commander zilyana",
		"general graardor", "k'ril tsutsaroth", "the hueycoatl", "corporeal beast", "nex", "chaos fanatic",
		"crazy archaeologist", "scorpia", "king black dragon", "chaos elemental", "revenant maledictus",
		"calvar'ion", "vet'ion", "spindel", "venenatis", "artio", "callisto", "brutus", "demonic brutus",
		"obor", "bryophyta", "amoxliatl", "branda the fire queen", "eldric the ice king",
		"doom of mokhaiotl", "mad angel", "zulrah", "vorkath", "phantom muspah", "maggot king",
		"the nightmare", "phosani's nightmare", "yama", "duke sucellus", "the leviathan", "the scar",
		"the whisperer", "vardorvis", "the mimic", "hespori", "skotizo", "shellbane gryphon",
		"grotesque guardians", "dusk", "dawn", "abyssal sire", "kraken", "cerberus", "araxxor",
		"thermonuclear smoke devil", "alchemical hydra", "crystalline hunllef", "corrupted hunllef",
		"tztok-jad", "tzkal-zuk", "sol heredit", "tekton", "vanguard", "vespula", "vasa nistirio",
		"muttadile", "great olm", "the maiden of sugadinti", "pestilent bloat", "nylocas vasilias",
		"sotetseg", "xarpus", "verzik vitur", "akkha", "ba-ba", "kephri", "zebak", "tumeken's warden",
		"elidinis' warden"));

	private BigTargets()
	{
	}

	/**
	 * @param onHud true when the game's boss health HUD is showing this NPC
	 * @param name  the NPC's name, tags removed, or null
	 */
	static boolean isBoss(boolean onHud, String name)
	{
		return onHud || (name != null && BOSSES.contains(name.toLowerCase(Locale.ROOT)));
	}

	/**
	 * @param maxHealth the NPC's max HP, or -1 when unknown. Unknown is never
	 *                  over the threshold, so it falls to everything else.
	 */
	static boolean isBig(BigTargetRule rule, boolean boss, int maxHealth, int threshold)
	{
		final boolean high = maxHealth > 0 && maxHealth >= threshold;
		switch (rule)
		{
			case BOSSES:
				return boss;
			case HP_ONLY:
				return high;
			case BOSSES_AND_HP:
			default:
				return boss || high;
		}
	}

	static DisplayMode mode(boolean big, TargetDisplay bigDisplay, TargetDisplay otherDisplay, DisplayMode display)
	{
		return (big ? bigDisplay : otherDisplay).resolve(display);
	}
}

package com.vinnyvangogh.combatvitals;

import net.runelite.api.Skill;

/**
 * Tracks the game's stat-drain cycle so the badge can say how long a boost
 * has left before it drops by one.
 *
 * The cycle runs in the background whether or not anything is boosted: every
 * 100 ticks (60 s) a boosted stat drops by one, or every 150 ticks (90 s)
 * once Preserve has been on for the tail of the cycle. The client is never
 * told where in the cycle it is, so the phase has to be inferred. Two things
 * anchor it: logging in, which the OSRS wiki says restarts the segment, and
 * an observed drop, which is the only hard evidence. The badge marks the
 * login anchor as an estimate until a drop confirms it.
 *
 * The preserve arithmetic is ported from RuneLite's Boosts plugin
 * ({@code BoostsPlugin#getChangeDownTicks}, BSD-2), which carries the only
 * tested model of how Preserve stretches the cycle.
 *
 * Pure: ticks in, ticks out, no client. Not thread safe; the plugin touches
 * it from the client thread only.
 */
final class BoostTimer
{
	/** Ticks per drain cycle, and with Preserve. */
	static final int CYCLE = 100;
	static final int PRESERVE_CYCLE = 150;

	/** Tick the cycle last (re)started, or -1 while unknown. */
	private int lastChangeDown = -1;

	/** Whether an observed drop, rather than login, set the phase. */
	private boolean confirmed;

	private boolean preserveBeenActive;

	/** The non-combat stats share one drain timer; combat stats run another. */
	static boolean onSkillingTimer(Skill skill)
	{
		switch (skill)
		{
			case ATTACK:
			case STRENGTH:
			case DEFENCE:
			case RANGED:
			case MAGIC:
			case HITPOINTS:
			case PRAYER:
				return false;
			default:
				return true;
		}
	}

	/** Logging in restarts the segment. An estimate until a drop confirms it. */
	void anchorLogin(int tick)
	{
		lastChangeDown = tick;
		confirmed = false;
		preserveBeenActive = false;
	}

	/** A boosted stat was seen dropping by one: the cycle restarted now. */
	void anchorDrop(int tick)
	{
		lastChangeDown = tick;
		confirmed = true;
	}

	boolean isKnown()
	{
		return lastChangeDown != -1;
	}

	boolean isConfirmed()
	{
		return confirmed;
	}

	/**
	 * Ticks until the next drop, or -1 while the phase is unknown.
	 *
	 * Call once per tick: the preserve bookkeeping is stateful, exactly as in
	 * the Boosts plugin it is ported from.
	 */
	int ticksUntilDrop(int tick, boolean preserveActive)
	{
		if (lastChangeDown == -1)
		{
			return -1;
		}

		final int since = tick - lastChangeDown;

		// Preserve only extends the cycle if it was on for the final quarter,
		// seconds 45 to 75, after which the cycle is 150 ticks long.
		if ((preserveActive && (since < 75 || preserveBeenActive)) || since > 125)
		{
			preserveBeenActive = true;
			return PRESERVE_CYCLE - since;
		}

		preserveBeenActive = false;
		return since > CYCLE ? 125 - since : CYCLE - since;
	}

	/** Length of the cycle currently in force, for drawing a bar that drains. */
	int cycleLength()
	{
		return preserveBeenActive ? PRESERVE_CYCLE : CYCLE;
	}

	/**
	 * The cycle ran out without a drop being seen, because nothing was
	 * boosted. It restarts now, keeping whatever confidence it had.
	 */
	void roll(int tick)
	{
		if (lastChangeDown != -1)
		{
			lastChangeDown = tick;
		}
	}

	void clear()
	{
		lastChangeDown = -1;
		confirmed = false;
		preserveBeenActive = false;
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Arrays;
import net.runelite.api.Skill;

/**
 * Turns the stream of stat updates into boost events.
 *
 * The client reports a skill's boosted level, not what happened to it. The
 * change is only meaningful against the previous value, so this remembers
 * one level per skill and classifies each update: the boost rose, dropped by
 * one, or dropped back to base.
 *
 * Pure: levels in, events out, no client.
 */
final class BoostTracker
{
	enum Change
	{
		/** No change, or a change this plugin does not describe. */
		NONE,
		/** The boosted level rose above base. */
		RISE,
		/** A boost dropped by one and is still above base. */
		DROP,
		/** A boost dropped by one and reached base. */
		EXPIRED
	}

	private final int[] lastBoosted = new int[Skill.values().length];

	BoostTracker()
	{
		Arrays.fill(lastBoosted, -1);
	}

	/** Whether the skill has been seen at all; the first update only seeds. */
	boolean isSeeded(Skill skill)
	{
		return lastBoosted[skill.ordinal()] != -1;
	}

	/** Seeds without reporting, for a plugin enabled mid-session. */
	void seed(Skill skill, int boosted)
	{
		lastBoosted[skill.ordinal()] = boosted;
	}

	/**
	 * @param skill   the skill that changed
	 * @param real    its base level
	 * @param boosted its boosted level now
	 * @return what happened to its boost
	 */
	Change observe(Skill skill, int real, int boosted)
	{
		final int last = lastBoosted[skill.ordinal()];
		lastBoosted[skill.ordinal()] = boosted;

		if (last == -1 || boosted == last)
		{
			return Change.NONE;
		}

		if (boosted > last && boosted > real)
		{
			return Change.RISE;
		}

		// Only a one-level fall from above base is the drain timer. A larger
		// fall is damage or a world hop, and a fall below base is a drain.
		if (boosted == last - 1 && last > real)
		{
			return boosted > real ? Change.DROP : Change.EXPIRED;
		}

		return Change.NONE;
	}

	void clear()
	{
		Arrays.fill(lastBoosted, -1);
	}
}

package com.vinnyvangogh.combatvitals;

import java.time.Duration;
import java.time.Instant;
import net.runelite.api.Hitsplat;

/**
 * Decides whether the player is actually fighting.
 *
 * Interacting with something is not proof of combat. Fishing spots, rocks,
 * bankers, shopkeepers and pets are all NPCs, and clicking any of them fires
 * the same {@code InteractingChanged} as attacking a goblin. Two things are
 * proof: the target can be attacked, or a hitsplat has landed on the player or
 * been dealt by them recently.
 *
 * The opponent readout needs the first. Your own bar needs either, so that
 * being attacked while fishing still shows it without promoting the fishing
 * spot to an opponent.
 *
 * Pure: instants in, booleans out, so it is testable without a client. Not
 * thread safe; the plugin touches it from the client thread only.
 */
final class CombatState
{
	private static final String ATTACK = "Attack";

	/** A target is held, live or lingering after the interaction ended. */
	private boolean engaged;

	private boolean targetAttackable;

	/** When the interaction ended, or null while it is live. */
	private Instant interactionEnded;

	/** The last hitsplat on the player or dealt by them. */
	private Instant lastHit;

	/**
	 * @param actions     the NPC's menu options, {@code NPCComposition#getActions()}
	 * @param combatLevel the NPC's combat level, -1 when it has none
	 * @return whether the NPC can be fought
	 */
	static boolean attackable(String[] actions, int combatLevel)
	{
		if (combatLevel > 0)
		{
			return true;
		}

		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if (ATTACK.equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether a hitsplat says the player is fighting.
	 *
	 * The player's own hits land as the "me" types wherever they land. Hits on
	 * the player count whichever way the client typed them, but status
	 * hitsplats on the player (poison, venom, disease, healing, prayer drain)
	 * are not combat and must not pop the bar while skilling.
	 *
	 * @param onMe     the hitsplat landed on the local player
	 * @param hitsplat the hitsplat
	 */
	static boolean evidence(boolean onMe, Hitsplat hitsplat)
	{
		return hitsplat.isMine() || (onMe && hitsplat.isOthers());
	}

	/** The player started interacting with something. */
	void engage(boolean attackable)
	{
		engaged = true;
		targetAttackable = attackable;
		interactionEnded = null;
	}

	/** The player stopped interacting. The target lingers until {@link #expire}. */
	void disengage(Instant now)
	{
		if (engaged && interactionEnded == null)
		{
			interactionEnded = now;
		}
	}

	/**
	 * A hitsplat that {@link #evidence} accepted.
	 *
	 * @param onTarget the player's own hit landed on the held target, which
	 *                 proves it attackable whatever its composition said
	 */
	void hit(boolean onTarget, Instant now)
	{
		lastHit = now;
		if (onTarget && engaged)
		{
			targetAttackable = true;
		}
	}

	/**
	 * Retires the target once the interaction has been over for the timeout.
	 *
	 * @param stillInteractingWithTarget the game still has the player on this
	 *                                   target. Any other interaction, a
	 *                                   fishing spot included, does not count.
	 * @return true when the caller should drop its reference to the target
	 */
	boolean expire(Instant now, Duration timeout, boolean stillInteractingWithTarget)
	{
		if (!engaged || interactionEnded == null || stillInteractingWithTarget)
		{
			return false;
		}

		if (Duration.between(interactionEnded, now).compareTo(timeout) > 0)
		{
			engaged = false;
			targetAttackable = false;
			interactionEnded = null;
			return true;
		}
		return false;
	}

	/** The held target is something that can be fought, so show its readout. */
	boolean showTarget()
	{
		return engaged && targetAttackable;
	}

	/** Fighting an attackable target, or hit within the timeout. Gates your own bar. */
	boolean inCombat(Instant now, Duration timeout)
	{
		if (showTarget())
		{
			return true;
		}
		return lastHit != null && Duration.between(lastHit, now).compareTo(timeout) <= 0;
	}

	void clear()
	{
		engaged = false;
		targetAttackable = false;
		interactionEnded = null;
		lastHit = null;
	}
}

