package com.vinnyvangogh.combatvitals;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * While "Hide game health bar" is on, draws a bar in the game's place for
 * every player and NPC that shows one ({@link GameHealthBars}), so hiding
 * the game's sprites takes no bar away. Your target and you keep the
 * plugin's readout instead, which is what the option is for.
 */
class GameHealthBarOverlay extends Overlay
{
	private final Client client;
	private final CombatVitalsPlugin plugin;
	private final CombatVitalsConfig config;

	@Inject
	GameHealthBarOverlay(Client client, CombatVitalsPlugin plugin, CombatVitalsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final WorldView view = client.getTopLevelWorldView();
		if (!config.hideGameHealthBar() || view == null)
		{
			return null;
		}

		// As the overhead overlay decides what it draws over: a player target
		// only with "Show over players" on.
		final CombatVitalsPlugin.Readout target = plugin.getReadout();
		final Actor opponent = target != null && (target.isNpc() || config.overheadForPlayers())
			? readoutActor(target) : null;
		final Actor self = readoutActor(plugin.getSelfReadout());
		final GameHealthBars.Access<Actor> access = new ClientAccess(view.getPlane());
		draw(graphics, GameHealthBars.plan(view.npcs(), a -> a == opponent, access));
		draw(graphics, GameHealthBars.plan(view.players(), a -> a == opponent || a == self, access));
		return null;
	}

	/** The actor a readout is drawn over, when the overhead readout is on; else null. */
	private Actor readoutActor(CombatVitalsPlugin.Readout readout)
	{
		return readout == null || !config.showOverhead() ? null : readout.getActor();
	}

	private static void draw(Graphics2D graphics, Iterable<GameHealthBars.Bar> bars)
	{
		for (GameHealthBars.Bar bar : bars)
		{
			final Rectangle box = bar.getBox();
			graphics.setColor(GameHealthBars.EMPTY);
			graphics.fillRect(box.x, box.y, box.width, box.height);
			if (bar.getFilled() > 0)
			{
				graphics.setColor(GameHealthBars.FILL);
				graphics.fillRect(box.x, box.y, bar.getFilled(), box.height);
			}
		}
	}

	/** The client's view of an actor's bar, read during the frame. */
	private final class ClientAccess implements GameHealthBars.Access<Actor>
	{
		private final int plane;

		ClientAccess(int plane)
		{
			this.plane = plane;
		}

		@Override
		public int ratio(Actor actor)
		{
			return actor.getHealthRatio();
		}

		@Override
		public int scale(Actor actor)
		{
			return actor.getHealthScale();
		}

		@Override
		public boolean talking(Actor actor)
		{
			final String text = actor.getOverheadText();
			return text != null && !text.isEmpty() && actor.getOverheadCycle() > 0;
		}

		@Override
		public int[] anchor(Actor actor)
		{
			// An actor being removed (a kill) can throw from its scene lookups
			// mid-frame; that frame skips it.
			final Point at = CombatVitalsOverheadOverlay.onScreen(() ->
			{
				final LocalPoint local = actor.getLocalLocation();
				return local == null ? null : Perspective.localToCanvas(client, local, plane,
					Math.max(0, actor.getLogicalHeight()) + GameHealthBars.ABOVE_HEIGHT);
			});
			return at == null ? null : new int[]{at.getX(), at.getY()};
		}
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import lombok.Value;

/**
 * Redraws the game's own overhead health bar for every player and NPC that
 * shows one, while "Hide game health bar" has blanked the game's sprites.
 * Those sprites are global (docs/native-hp-bar.md): blanking them hides every
 * standard bar on screen, so every bar hidden has to be drawn back, not only
 * the target's (Board's in-game test, 2026-11-06).
 *
 * Geometry, from the client's {@code drawActor2d} as deobfuscated in
 * jbx5/devious-client {@code UserComparator10.java} (commit 36c5a58,
 * L107-L229):
 * <ul>
 * <li>The actor is projected at its height plus 15 (L145). RuneLite's
 * {@code Actor#getLogicalHeight} is that height; an NPC whose definition
 * sets its own bar height (cache opcode 124) is drawn a little off.</li>
 * <li>A running offset starts at -2 (L123) and grows by 12 when the actor is
 * talking (L137), then by the bar's 5 px height (L198/L216): the bar's top
 * is 3 px above the projected point, 15 px while chat is up.</li>
 * <li>Centred: {@code x - (width >> 1)} (L199/L217).</li>
 * <li>Width: the bar definition's width, which is what
 * {@code Actor#getHealthScale} returns (RuneLite's mixin reads the same
 * {@code width} field), 30 px for most actors. Fill: {@code ratio * width / scale}
 * of it in green, the rest red, as the client's no-sprite fallback draws
 * (L215-L223).</li>
 * </ul>
 *
 * Not reproduced: a second bar stacked on the first (the API reports one),
 * Interface Styles' HD look, and the special head bars (shields, blood,
 * heat, ice), which the hider leaves alone in the first place.
 *
 * Pure: numbers in, boxes out.
 */
final class GameHealthBars
{
	static final int HEIGHT = 5;

	/** Above the actor's logical height, where the client projects its bars. */
	static final int ABOVE_HEIGHT = 15;

	/** How far the bar moves up while the actor's overhead chat is up. */
	static final int CHAT_LIFT = 12;

	/** The client's own fallback colours, 0x00FF00 and 0xFF0000. */
	static final Color FILL = new Color(0x00FF00);
	static final Color EMPTY = new Color(0xFF0000);

	/** Widest bar the game draws (StandardHealth160); a larger scale is clamped to it. */
	private static final int MAX_WIDTH = 160;

	/** One actor's reading, as the overlay takes it from the client. */
	interface Access<A>
	{
		int ratio(A actor);

		int scale(A actor);

		/** Overhead chat is up, which lifts the bar. */
		boolean talking(A actor);

		/** The actor projected at its logical height plus {@link #ABOVE_HEIGHT}: {x, y}, or null off screen. */
		int[] anchor(A actor);
	}

	/** One bar to draw: its box, and how many pixels of it are green. */
	@Value
	static class Bar
	{
		Rectangle box;
		int filled;
	}

	private GameHealthBars()
	{
	}

	/** Whether the client is showing a bar: it has a ratio and a scale. */
	static boolean shown(int ratio, int scale)
	{
		return ratio >= 0 && scale > 0;
	}

	/** The bar's width in pixels for a scale: the scale itself, up to the widest standard bar. */
	static int width(int scale)
	{
		return Math.max(1, Math.min(MAX_WIDTH, scale));
	}

	/** Green pixels: the ratio's share of the width, never 0 while there is any health left. */
	static int filled(int ratio, int scale, int width)
	{
		if (ratio <= 0 || scale <= 0)
		{
			return 0;
		}
		return Math.max(1, Math.min(width, ratio * width / scale));
	}

	/** The bar's box, centred on the projected point. */
	static Rectangle box(int x, int y, int width, boolean talking)
	{
		final int top = y + 2 - HEIGHT - (talking ? CHAT_LIFT : 0);
		return new Rectangle(x - (width >> 1), top, width, HEIGHT);
	}

	/**
	 * Every bar to draw this frame.
	 *
	 * @param actors  every player and NPC in the scene
	 * @param covered actors the plugin already draws a health readout over,
	 *                which takes the bar's place
	 */
	static <A> List<Bar> plan(Iterable<? extends A> actors, Predicate<? super A> covered, Access<A> access)
	{
		final List<Bar> bars = new ArrayList<>();
		for (A actor : actors)
		{
			final int ratio = access.ratio(actor);
			final int scale = access.scale(actor);
			if (!shown(ratio, scale) || covered.test(actor))
			{
				continue;
			}
			final int[] at = access.anchor(actor);
			if (at == null)
			{
				continue;
			}
			final int width = width(scale);
			bars.add(new Bar(box(at[0], at[1], width, access.talking(actor)), filled(ratio, scale, width)));
		}
		return bars;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;

/**
 * Turns a recovered health range into the text and colour drawn on screen.
 *
 * Pure: no client, no config object, no state. Everything it needs is passed
 * in, so the formatting rules are unit testable without a running game.
 */
final class HealthReadout
{
	private HealthReadout()
	{
	}

	/**
	 * @param range      recovered health, or null when max health is unknown
	 * @param maxHealth  the actor's max health, or -1 when unknown
	 * @param ratio      the raw health ratio
	 * @param scale      the raw health scale
	 * @param mode       what the user asked to see
	 * @param decimals   show one decimal place on percentages
	 * @return the text to draw, or null if there is nothing meaningful to say
	 */
	static String text(HealthRecovery.Range range, int maxHealth, int ratio, int scale,
		DisplayMode mode, boolean decimals, int exactHealth)
	{
		final String percent = percentText(ratio, scale, decimals, exactHealth, maxHealth);

		// Without a max health there is no hitpoints value to show, only the
		// fraction of the bar. Falling back is better than showing nothing.
		if (maxHealth <= 0 || (range == null && exactHealth < 0))
		{
			return percent;
		}

		// An exact value is used as-is. Recovering a number the client already
		// knows would print a guess in place of a fact.
		final String hp = (exactHealth >= 0 ? exactHealth : range.midpoint()) + " / " + maxHealth;

		switch (mode)
		{
			case PERCENTAGE:
				return percent;
			case BOTH:
				return hp + " (" + percent + ")";
			case HITPOINTS:
			default:
				return hp;
		}
	}

	static String percentText(int ratio, int scale, boolean decimals, int exactHealth, int maxHealth)
	{
		final double fraction = fraction(ratio, scale, exactHealth, maxHealth) * 100.0;
		return decimals
			? String.format("%.1f%%", fraction)
			: String.format("%d%%", Math.round(fraction));
	}

	/**
	 * Remaining health as 0..1. Uses the exact values when they are known, and
	 * otherwise the bar's own ratio, which needs no recovery to be a fraction.
	 */
	static double fraction(int ratio, int scale, int exactHealth, int maxHealth)
	{
		if (exactHealth >= 0 && maxHealth > 0)
		{
			return Math.max(0, Math.min(1.0, (double) exactHealth / maxHealth));
		}
		if (scale <= 0 || ratio <= 0)
		{
			return 0;
		}
		return Math.min(1.0, (double) ratio / scale);
	}

	/**
	 * Interpolates through three user-chosen stops so the colour moves smoothly
	 * as health drops rather than snapping between bands.
	 */
	static Color colour(double fraction, Color full, Color mid, Color low)
	{
		final double f = Math.max(0, Math.min(1, fraction));
		return f >= 0.5
			? blend(mid, full, (f - 0.5) * 2)
			: blend(low, mid, f * 2);
	}

	private static Color blend(Color from, Color to, double t)
	{
		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * t),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * t),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * t),
			(int) Math.round(from.getAlpha() + (to.getAlpha() - from.getAlpha()) * t));
	}
}

package com.vinnyvangogh.combatvitals;

/**
 * Inverts the server's health-bar quantisation.
 *
 * The server broadcasts a health bar as a ratio out of a scale rather than a
 * value, computing
 *
 *     healthRatio = 1 + (healthScale - 1) * health / maxHealth
 *
 * with integer division, and forcing healthRatio = 0 when health = 0. Inverting
 * that recovers a range of healths consistent with the observation, which
 * collapses to a single value only when {@code maxHealth <= healthScale}.
 *
 * Phase 0.5 measured healthScale at 30 for every actor, so NPCs at or under 30
 * hitpoints resolve exactly and players never do. The range is the honest
 * result; {@link Range#midpoint()} is the best single guess within it and is
 * what the base client displays.
 *
 * Pure arithmetic — no client, no state, fully unit testable.
 */
final class HealthRecovery
{
	private HealthRecovery()
	{
	}

	static final class Range
	{
		private final int min;
		private final int max;

		private Range(int min, int max)
		{
			this.min = min;
			this.max = max;
		}

		int min()
		{
			return min;
		}

		int max()
		{
			return max;
		}

		/** True when the observation pins the health to a single value. */
		boolean isExact()
		{
			return min == max;
		}

		/**
		 * The value that minimises worst-case error, not the most likely value.
		 * Every health in the range is equally consistent with the observation;
		 * this one is simply never wrong by more than half the range's width.
		 */
		int midpoint()
		{
			return (min + max + 1) / 2;
		}

		int width()
		{
			return max - min + 1;
		}

		@Override
		public String toString()
		{
			return isExact() ? Integer.toString(min) : min + "-" + max;
		}
	}

	/**
	 * @param healthRatio the actor's {@code getHealthRatio()}
	 * @param healthScale the actor's {@code getHealthScale()}
	 * @param maxHealth   the actor's true maximum health, known independently
	 * @return every health consistent with the observation
	 */
	static Range recover(int healthRatio, int healthScale, int maxHealth)
	{
		if (maxHealth <= 0 || healthScale <= 0)
		{
			throw new IllegalArgumentException(
				"maxHealth and healthScale must be positive, got " + maxHealth + " and " + healthScale);
		}

		// health = 0 forces healthRatio = 0, so a zero ratio is unambiguous.
		if (healthRatio <= 0)
		{
			return new Range(0, 0);
		}

		int min = 1;
		int max;

		if (healthScale > 1)
		{
			// healthRatio = 1 carries no lower bound beyond "alive", because the
			// health = 0 special case means ratio 1 is not produced by the
			// general formula the way ratios above 1 are.
			if (healthRatio > 1)
			{
				min = (maxHealth * (healthRatio - 1) + healthScale - 2) / (healthScale - 1);
			}

			max = Math.min((maxHealth * healthRatio - 1) / (healthScale - 1), maxHealth);
		}
		else
		{
			// With a scale of 1 the ratio is 1 for any living actor, so the
			// observation says only that they are alive.
			max = maxHealth;
		}

		// Guard the degenerate cases rather than trusting the arithmetic to stay
		// ordered at the boundaries.
		min = Math.max(1, Math.min(min, maxHealth));
		max = Math.max(min, Math.min(max, maxHealth));

		return new Range(min, max);
	}
}

package com.vinnyvangogh.combatvitals;

import net.runelite.api.Skill;

/**
 * Keeps the skilling badge up after you stop, as "Not fishing", instead of
 * letting it vanish (Board, 2026-11-04).
 *
 * Idle starts the tick the badge would otherwise have gone: the activity's
 * own linger ({@link SkillingState#expire}) has run out, or it was released
 * by clicking something else. It ends when another activity starts, when a
 * fight starts, or after the configured seconds.
 *
 * Pure: skills and wall-clock milliseconds in, the idle skill out.
 */
final class IdleBadge
{
	private Skill lastSkill;

	/** When the badge went idle, or -1 while working or with nothing to show. */
	private long idleSince = -1;

	/**
	 * Once per game tick.
	 *
	 * @param active the skill the badge is up for now, or null
	 * @param combat a fight or a hitsplat is in progress
	 */
	void tick(Skill active, boolean combat, long nowMillis)
	{
		if (active != null)
		{
			lastSkill = active;
			idleSince = -1;
			return;
		}

		if (combat)
		{
			clear();
			return;
		}

		if (lastSkill != null && idleSince < 0)
		{
			idleSince = nowMillis;
		}
	}

	/** The skill to show as "Not ..." now, or null when the idle badge should not be up. */
	Skill idleSkill(IdleBadgeMode mode, int seconds, long nowMillis)
	{
		if (lastSkill == null || idleSince < 0 || mode == IdleBadgeMode.OFF)
		{
			return null;
		}
		if (mode == IdleBadgeMode.TIMED && nowMillis - idleSince >= seconds * 1000L)
		{
			return null;
		}
		return lastSkill;
	}

	void clear()
	{
		lastSkill = null;
		idleSince = -1;
	}
}

