package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * How full the inventory is, for the bar under the skilling badge.
 *
 * Only slots that gathering fills count as filled. A stackable (feathers,
 * bait, coins, coin pouches, noted items), a tool (net, rod, pot, axe,
 * pickaxe, hammer...) or a piece of equipment sits in its slot for the whole
 * trip, so it is taken out of the capacity rather than counted as fill: a
 * harpoon and 27 fish is a full bar, and so is any inventory with no free
 * slot left.
 *
 * Pure: slot classes in, a fraction and a colour out.
 */
final class InventoryFill
{
	static final int SLOTS = 28;

	enum Slot
	{
		EMPTY,
		/** Something the trip is filling the inventory with. */
		FILLING,
		/** A stackable, tool or piece of equipment: holds its slot, fills nothing. */
		FIXED
	}

	/**
	 * Tools that live in the inventory while gathering or making. Names, not
	 * ids, so every metal and variant is covered. Source: OSRS wiki,
	 * "Fishing", "Woodcutting", "Mining", "Crafting", "Smithing".
	 */
	private static final Pattern TOOL = Pattern.compile(
		"^(?:small fishing net|big fishing net|fishing rod|fly fishing rod|barbarian rod|oily fishing rod"
			+ "|pearl (?:fishing|fly fishing|barbarian) rod|lobster pot|karambwan vessel|harpoon"
			+ "|.*\\b(?:axe|pickaxe|harpoon)(?: \\(.*\\))?"
			+ "|tinderbox|hammer|imcando hammer|chisel|knife|needle|glassblowing pipe|saw|crystal saw"
			+ "|pestle and mortar|bucket|ammo mould|.*\\bmould|noose wand|butterfly net|.*\\bbutterfly net"
			+ "|rope|bird snare|box trap|rabbit snare|teasing stick)$");

	private InventoryFill()
	{
	}

	/**
	 * @param stackable the item stacks, noted items included
	 * @param name      the item's name
	 * @param actions   the item's inventory options, {@code ItemComposition#getInventoryActions()}
	 */
	static Slot classify(boolean stackable, String name, String[] actions)
	{
		if (stackable)
		{
			return Slot.FIXED;
		}
		if (name != null && TOOL.matcher(name.toLowerCase(Locale.ROOT)).matches())
		{
			return Slot.FIXED;
		}
		if (actions != null)
		{
			for (String action : actions)
			{
				if ("Wield".equalsIgnoreCase(action) || "Wear".equalsIgnoreCase(action)
					|| "Equip".equalsIgnoreCase(action))
				{
					return Slot.FIXED;
				}
			}
		}
		return Slot.FILLING;
	}

	/**
	 * @return 0 for nothing gathered yet, 1 for no free slot left; the share of
	 *         the free capacity (filled plus empty slots) that is filled
	 */
	static double fraction(int filling, int empty)
	{
		if (empty <= 0)
		{
			return 1.0;
		}
		final int capacity = Math.max(0, filling) + empty;
		return (double) Math.max(0, filling) / capacity;
	}

	/**
	 * The inventory line's label: free slots out of the whole inventory. A
	 * stack or a tool holds a slot, so it is not free.
	 *
	 * @param empty empty slots, or -1 when the inventory has not been read
	 * @return e.g. "Inv 26/28 free", or null when unknown
	 */
	static String label(int empty)
	{
		return label(empty, InventoryCount.FREE);
	}

	/** "Inv 26/28 free", or the same inventory counted the other way, "Inv 2/28 used". */
	static String label(int empty, InventoryCount count)
	{
		if (empty < 0)
		{
			return null;
		}
		return count == InventoryCount.USED
			? "Inv " + (SLOTS - empty) + "/" + SLOTS + " used"
			: "Inv " + empty + "/" + SLOTS + " free";
	}

	/**
	 * Green while empty, through yellow at half, to red when full: the health
	 * ramp run the other way, since a full inventory is the thing to act on.
	 */
	static Color colour(double fill, Color empty, Color half, Color full)
	{
		return HealthReadout.colour(1.0 - fill, empty, half, full);
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.function.IntUnaryOperator;

/**
 * Sizes the badge's inventory line so the label and the catch icons never
 * meet: the label is measured with every digit at the font's widest digit,
 * and a gap is kept before the icons.
 *
 * Pure: a label and a font's character widths in, pixels out.
 */
final class InventoryLine
{
	/** Pixels always kept between the label and the first catch icon. */
	static final int LABEL_GAP = 6;

	private InventoryLine()
	{
	}

	/**
	 * The label's width with each digit as wide as the font's widest, never
	 * less than its measured width.
	 *
	 * @param charWidth a character's advance in the font, {@code FontMetrics#charWidth(int)}
	 * @param measured  the label's own width, {@code FontMetrics#stringWidth}
	 */
	static int reservedWidth(String label, IntUnaryOperator charWidth, int measured)
	{
		int widestDigit = 0;
		for (char digit = '0'; digit <= '9'; digit++)
		{
			widestDigit = Math.max(widestDigit, charWidth.applyAsInt(digit));
		}

		int width = 0;
		for (int i = 0; i < label.length(); i++)
		{
			final char c = label.charAt(i);
			width += Character.isDigit(c) ? widestDigit : charWidth.applyAsInt(c);
		}
		return Math.max(width, measured);
	}
}

package com.vinnyvangogh.combatvitals;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.FishingSpot;

/**
 * The bundled list of fishing spot locations, for when no spot of the right
 * type is loaded in the scene. Read once from {@code fishing_spots.tsv}
 * beside this class; the file cites its sources and says what was left out.
 *
 * One row per line, tab separated: the {@link FishingSpot} constant, x, y,
 * plane, {@code members} or {@code free}, the Fishing level the location
 * itself needs (0 for none), and the location's name. A row that does not
 * parse is skipped and logged rather than failing the whole list.
 */
@Slf4j
final class KnownFishingSpots
{
	static final String RESOURCE = "fishing_spots.tsv";

	private static final int COLUMNS = 7;

	private KnownFishingSpots()
	{
	}

	/** The bundled list, or an empty one when it cannot be read. */
	static List<NextFishingSpot.Spot> load()
	{
		// getResourceAsStream, not getResource: the plugin ships inside a jar.
		try (InputStream in = KnownFishingSpots.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("{} is missing from the plugin jar", RESOURCE);
				return Collections.emptyList();
			}
			return parse(new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)));
		}
		catch (IOException e)
		{
			log.warn("Could not read {}", RESOURCE, e);
			return Collections.emptyList();
		}
	}

	static List<NextFishingSpot.Spot> parse(BufferedReader reader) throws IOException
	{
		final List<NextFishingSpot.Spot> spots = new ArrayList<>();
		String line;
		while ((line = reader.readLine()) != null)
		{
			final String trimmed = line.trim();
			if (trimmed.isEmpty() || trimmed.startsWith("#"))
			{
				continue;
			}
			final NextFishingSpot.Spot spot = row(trimmed.split("\t"));
			if (spot == null)
			{
				log.warn("Skipping bad {} row: {}", RESOURCE, trimmed);
				continue;
			}
			spots.add(spot);
		}
		return Collections.unmodifiableList(spots);
	}

	private static NextFishingSpot.Spot row(String[] cells)
	{
		if (cells.length != COLUMNS)
		{
			return null;
		}
		try
		{
			final FishingSpot type = FishingSpot.valueOf(cells[0].trim());
			return NextFishingSpot.Spot.known(type,
				Integer.parseInt(cells[1].trim()),
				Integer.parseInt(cells[2].trim()),
				Integer.parseInt(cells[3].trim()),
				"members".equals(cells[4].trim()),
				Integer.parseInt(cells[5].trim()),
				cells[6].trim());
		}
		catch (IllegalArgumentException e)
		{
			// NumberFormatException is an IllegalArgumentException, as is an unknown enum name.
			return null;
		}
	}
}

