package com.vinnyvangogh.combatvitals;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntFunction;
import net.runelite.api.gameval.SpriteID;

/**
 * Hides the game's own overhead health bar by overriding its sprites with
 * transparent ones of the same size.
 *
 * Global, not per actor: the client looks sprites up by id alone, so an
 * override applies to every standard health bar on screen, yours included.
 * See docs/native-hp-bar.md for why there is no per-actor route.
 *
 * Interface Styles' "HD health bars" overrides these same ids. Rather than
 * fight it, this remembers whatever override it displaced and puts it back on
 * restore, and {@link #apply()} is called every client tick so that when
 * Interface Styles rewrites or clears the map ours is reasserted within a
 * frame. Must only be called on the client thread.
 *
 * @param <S> the sprite type; {@code SpritePixels} in the client, anything in
 *            tests, since only identity is compared
 */
final class NativeHealthBarHider<S>
{
	/** Front and back sprites of every standard-width health bar, 30px to 160px. */
	static final int[] SPRITE_IDS = {
		SpriteID.StandardHealth30.FRONT, SpriteID.StandardHealth30.BACK,
		SpriteID.StandardHealth40.FRONT, SpriteID.StandardHealth40.BACK,
		SpriteID.StandardHealth50.FRONT, SpriteID.StandardHealth50.BACK,
		SpriteID.StandardHealth60.FRONT, SpriteID.StandardHealth60.BACK,
		SpriteID.StandardHealth70.FRONT, SpriteID.StandardHealth70.BACK,
		SpriteID.StandardHealth80.FRONT, SpriteID.StandardHealth80.BACK,
		SpriteID.StandardHealth90.FRONT, SpriteID.StandardHealth90.BACK,
		SpriteID.StandardHealth100.FRONT, SpriteID.StandardHealth100.BACK,
		SpriteID.StandardHealth120.FRONT, SpriteID.StandardHealth120.BACK,
		SpriteID.StandardHealth140.FRONT, SpriteID.StandardHealth140.BACK,
		SpriteID.StandardHealth160.FRONT, SpriteID.StandardHealth160.BACK,
	};

	/** The client's sprite override map, keyed by sprite id. */
	private final Map<Integer, S> overrides;

	/** Builds the transparent stand-in for one sprite id. */
	private final IntFunction<S> blankFor;

	/** Our transparent sprites, by id. Empty means nothing is hidden. */
	private final Map<Integer, S> ours = new HashMap<>();

	/** Another plugin's override we replaced, to hand back on restore. */
	private final Map<Integer, S> displaced = new HashMap<>();

	/**
	 * Calls to {@link #apply()} between attempts at a sprite that could not
	 * be built. Building one reads and decodes it from the game cache, and
	 * apply runs every client tick: retrying a sprite that is not there yet
	 * on every one of them is a cache decode per frame. About a second.
	 */
	static final int RETRY_CALLS = 50;

	/** Calls left before the missing sprites are tried again; 0 tries them on the next call. */
	private int retryIn;

	NativeHealthBarHider(Map<Integer, S> overrides, IntFunction<S> blankFor)
	{
		this.overrides = overrides;
		this.blankFor = blankFor;
	}

	/**
	 * Installs the transparent sprites, or reasserts them if something
	 * replaced or removed them.
	 *
	 * @return true when the map changed, meaning the client's health bar
	 *         sprite cache has to be reset for the change to show
	 */
	boolean apply()
	{
		if (retryIn > 0)
		{
			retryIn--;
		}
		final boolean retry = retryIn == 0;
		boolean missing = false;
		boolean changed = false;
		for (int id : SPRITE_IDS)
		{
			final S mine = blank(id, retry);
			if (mine == null)
			{
				missing = true;
				continue;
			}

			final S current = overrides.get(id);
			if (current == mine)
			{
				continue;
			}

			// Whatever sits there now is the latest word from everyone else:
			// remember it, or forget the old one if they cleared it.
			if (current == null)
			{
				displaced.remove(id);
			}
			else
			{
				displaced.put(id, current);
			}

			overrides.put(id, mine);
			changed = true;
		}
		if (retry && missing)
		{
			retryIn = RETRY_CALLS;
		}
		return changed;
	}

	/** Our transparent sprite for this id, built now when this call may retry; null while it cannot be. */
	private S blank(int id, boolean retry)
	{
		final S mine = ours.get(id);
		if (mine != null || !retry)
		{
			return mine;
		}
		final S built = blankFor.apply(id);
		if (built != null)
		{
			ours.put(id, built);
		}
		return built;
	}

	/**
	 * Takes our sprites out and puts back anything they displaced. An id
	 * another plugin has overwritten since is left with that plugin.
	 *
	 * @return true when the map changed
	 */
	boolean restore()
	{
		// Switching back on tries every sprite straight away.
		retryIn = 0;
		if (ours.isEmpty())
		{
			return false;
		}

		boolean changed = false;
		for (Map.Entry<Integer, S> entry : ours.entrySet())
		{
			final int id = entry.getKey();
			if (overrides.get(id) != entry.getValue())
			{
				continue;
			}

			final S previous = displaced.get(id);
			if (previous != null)
			{
				overrides.put(id, previous);
			}
			else
			{
				overrides.remove(id);
			}
			changed = true;
		}

		ours.clear();
		displaced.clear();
		return changed;
	}

	boolean isActive()
	{
		return !ours.isEmpty();
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.List;
import lombok.Getter;
import net.runelite.client.game.FishingSpot;

/**
 * Picks the fishing spot to go to next: the nearest one of the same spot
 * type (net/bait, lure/bait, cage/harpoon...) that offers a fish the player
 * can catch with the method they were using. Spots loaded in the scene win;
 * the bundled list of known locations ({@link KnownFishingSpots}) is only
 * used when none is loaded.
 *
 * Pure and stateless.
 */
final class NextFishingSpot
{
	/** Tiles added to the distance of a spot on another plane, so any spot on this plane wins. */
	private static final int OTHER_PLANE = 10_000;

	/** A candidate: a spot NPC in the scene, or a known location from the bundled list. */
	@Getter
	static final class Spot
	{
		private final FishingSpot type;
		private final int x;
		private final int y;
		private final int plane;
		private final boolean members;
		private final int minLevel;
		private final String name;

		/** The spot's NPC when it is loaded in the scene, null for a known location. */
		private final Object npc;

		private Spot(FishingSpot type, int x, int y, int plane, boolean members, int minLevel, String name, Object npc)
		{
			this.type = type;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.members = members;
			this.minLevel = minLevel;
			this.name = name;
			this.npc = npc;
		}

		/** A spot NPC in the scene: being there already proves the world lets the player reach it. */
		static Spot loaded(FishingSpot type, int x, int y, int plane, Object npc)
		{
			return new Spot(type, x, y, plane, false, 0, null, npc);
		}

		/** A location from the bundled list, with its members flag and any level the location itself needs. */
		static Spot known(FishingSpot type, int x, int y, int plane, boolean members, int minLevel, String name)
		{
			return new Spot(type, x, y, plane, members, minLevel, name, null);
		}
	}

	/** What the next spot has to be. */
	static final class Need
	{
		private final FishingSpot type;
		private final String method;
		private final int level;
		private final boolean membersWorld;
		private final Object exclude;

		/**
		 * @param type         the spot type being fished
		 * @param method       the menu option it was fished with ("Cage"), or null when unknown
		 * @param level        the player's boosted Fishing level
		 * @param membersWorld whether members-only locations count
		 * @param exclude      the spot NPC being fished now, never the next one; may be null
		 */
		Need(FishingSpot type, String method, int level, boolean membersWorld, Object exclude)
		{
			this.type = type;
			this.method = method;
			this.level = level;
			this.membersWorld = membersWorld;
			this.exclude = exclude;
		}
	}

	private NextFishingSpot()
	{
	}

	/** The nearest loaded spot, or failing that the nearest known location; null when neither fits. */
	static Spot choose(List<Spot> loaded, List<Spot> known, int x, int y, int plane, Need need)
	{
		final Spot spot = nearest(loaded, x, y, plane, need);
		return spot != null ? spot : nearest(known, x, y, plane, need);
	}

	/**
	 * The nearest eligible spot by tile distance (Chebyshev, the way the game
	 * counts). A tie goes to the lower x, then the lower y, so the answer never
	 * depends on the order the scene lists its NPCs in.
	 */
	static Spot nearest(Iterable<Spot> candidates, int x, int y, int plane, Need need)
	{
		if (need.type == null || !offersCatch(need))
		{
			return null;
		}

		Spot best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (Spot spot : candidates)
		{
			if (!eligible(spot, need))
			{
				continue;
			}
			final int distance = distance(spot, x, y, plane);
			if (best == null || distance < bestDistance || (distance == bestDistance && before(spot, best)))
			{
				best = spot;
				bestDistance = distance;
			}
		}
		return best;
	}

	private static boolean eligible(Spot spot, Need need)
	{
		return spot.type == need.type
			&& (spot.npc == null || spot.npc != need.exclude)
			&& (!spot.members || need.membersWorld)
			&& spot.minLevel <= need.level;
	}

	/**
	 * Whether the method lands any fish at this level on this spot type. A
	 * method the table does not know is let through: the player was fishing
	 * with it, so it catches something.
	 */
	private static boolean offersCatch(Need need)
	{
		final List<FishingCatches.Fish> fish = FishingCatches.forOption(need.type, need.method);
		return fish.isEmpty() || !FishingCatches.catchable(fish, need.level).isEmpty();
	}

	private static int distance(Spot spot, int x, int y, int plane)
	{
		final int tiles = Math.max(Math.abs(spot.x - x), Math.abs(spot.y - y));
		return spot.plane == plane ? tiles : tiles + OTHER_PLANE;
	}

	private static boolean before(Spot a, Spot b)
	{
		return a.x != b.x ? a.x < b.x : a.y < b.y;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
