import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Marks the next fishing spot until the player fishes again: its tile
 * outlined, a line from the player to it, and an arrow at the edge of the
 * game view while it is off screen.
 *
 * Drawn whether or not the spot also went to Shortest Path. Shortest Path
 * ends its own path once the player is within its "Finish distance" of the
 * target (config key {@code finishDistance}, default 5 tiles, read straight
 * from its config in {@code ShortestPathPlugin#onGameTick}; a
 * {@code PluginMessage} cannot change it), and the next spot is usually
 * closer than that, so its line showed for a moment and went (Board's
 * in-game test, 2026-11-06). This mark stays.
 *
 * A known location outside the loaded scene has no screen position to mark;
 * Shortest Path's path covers that case.
 */
class NextSpotOverlay extends Overlay
{
	/** Fishing's skill colour, so the mark reads as the badge's. */
	private static final Color OUTLINE = SkillColours.of(Skill.FISHING);
	private static final Color LINE = new Color(OUTLINE.getRed(), OUTLINE.getGreen(), OUTLINE.getBlue(), 170);
	private static final Stroke LINE_STROKE = new BasicStroke(2);

	private final Client client;
	private final CombatVitalsPlugin plugin;

	@Inject
	NextSpotOverlay(Client client, CombatVitalsPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final NextFishingSpot.Spot spot = plugin.getNextSpot();
		final WorldView view = client.getTopLevelWorldView();
		final Player self = client.getLocalPlayer();
		if (spot == null || view == null || self == null || spot.getPlane() != view.getPlane())
		{
			return null;
		}

		final LocalPoint target = targetLocation(view, spot);
		final LocalPoint from = self.getLocalLocation();
		if (target != null && from != null)
		{
			mark(graphics, from, target, view.getPlane());
		}
		return null;
	}

	/** The tile outline, the line from you, and the edge arrow while the spot is off screen. */
	private void mark(Graphics2D graphics, LocalPoint from, LocalPoint target, int plane)
	{
		final Polygon tile = Perspective.getCanvasTilePoly(client, target);
		if (tile != null)
		{
			OverlayUtil.renderPolygon(graphics, tile, OUTLINE);
		}

		final Point to = Perspective.localToCanvas(client, target, plane);
		final Point at = Perspective.localToCanvas(client, from, plane);
		if (to != null && at != null)
		{
			drawLine(graphics, at, to);
		}

		final Rectangle game = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
			client.getViewportWidth(), client.getViewportHeight());
		if (to == null || !EdgeArrow.inside(game, to.getX(), to.getY(), EdgeArrow.MARGIN))
		{
			drawEdgeArrow(graphics, game, direction(from, target, at, to));
		}
	}

	private static void drawLine(Graphics2D graphics, Point at, Point to)
	{
		final Stroke stroke = graphics.getStroke();
		graphics.setStroke(LINE_STROKE);
		graphics.setColor(LINE);
		graphics.drawLine(at.getX(), at.getY(), to.getX(), to.getY());
		graphics.setStroke(stroke);
	}

	/** Where the spot is now: a loaded spot NPC's own tile, else the spot's. Null outside the scene. */
	private static LocalPoint targetLocation(WorldView view, NextFishingSpot.Spot spot)
	{
		if (spot.getNpc() instanceof NPC)
		{
			final LocalPoint npc = ((NPC) spot.getNpc()).getLocalLocation();
			if (npc != null)
			{
				return npc;
			}
		}
		return LocalPoint.fromWorld(view, new WorldPoint(spot.getX(), spot.getY(), spot.getPlane()));
	}

	/**
	 * Which way the spot lies on screen: from you to it when both project,
	 * else from the minimap, which turns with the camera so that up on it is
	 * into the screen. Null when neither is known.
	 */
	private double[] direction(LocalPoint from, LocalPoint target, Point at, Point to)
	{
		if (to != null && at != null)
		{
			return new double[]{to.getX() - at.getX(), to.getY() - at.getY()};
		}
		final Point mapFrom = Perspective.localToMinimap(client, from);
		final Point mapTo = Perspective.localToMinimap(client, target);
		if (mapFrom == null || mapTo == null)
		{
			return null;
		}
		return new double[]{mapTo.getX() - mapFrom.getX(), mapTo.getY() - mapFrom.getY()};
	}

	private static void drawEdgeArrow(Graphics2D graphics, Rectangle game, double[] direction)
	{
		final int[] tip = direction == null ? null : EdgeArrow.tip(game, direction[0], direction[1], EdgeArrow.MARGIN);
		if (tip == null)
		{
			return;
		}
		final Polygon head = EdgeArrow.head(tip[0], tip[1], direction[0], direction[1]);
		graphics.setColor(OUTLINE);
		graphics.fillPolygon(head);
		graphics.setColor(Color.BLACK);
		graphics.drawPolygon(head);
	}
}

package com.vinnyvangogh.combatvitals;

import net.runelite.api.Skill;

/**
 * Decides when the player is working a skilling object: a tree, a rock, a
 * stall.
 *
 * Objects are never interacted with the way NPCs are; no
 * {@code InteractingChanged} fires for a tree. Two things together are the
 * evidence instead: the player clicked a skilling option on the object
 * ("Chop down", "Mine"), and is now animating within reach of it. Either one
 * alone is not enough. A click is followed by a walk that may never arrive,
 * and an animation could be a potion being drunk on the way.
 *
 * Walking out of reach clears the badge at once. Stopping in place (the tree
 * fell, the rock emptied) lets it linger for the timeout like any other
 * engagement, so a respawn a few seconds later does not flicker it.
 *
 * Pure: ticks and tile coordinates in, steps out, no client. Not thread
 * safe; the plugin touches it from the client thread only.
 */
final class ObjectSkilling
{
	/** How long after the click the swing may start: about 18 s of walking. */
	static final int START_TICKS = 30;

	/**
	 * Tiles beyond the object's footprint that still count as at it. The
	 * player works from an adjacent tile; one more covers a rotated
	 * footprint, which the menu does not tell us about.
	 */
	static final int REACH = 2;

	enum Step
	{
		NONE,
		/** The swing started, or started again: raise the badge, cancel any linger. */
		ENGAGE,
		/** The swing stopped in place: let the badge linger. */
		DISENGAGE,
		/** The player left the object: drop the badge now. */
		RELEASE
	}

	private Skill skill;
	private int plane;
	private int minX;
	private int minY;
	private int maxX;
	private int maxY;
	private int clickTick = -1;

	/** The player has been seen working it since the click. */
	private boolean started;

	/** Animating at it on the last tick. */
	private boolean animating;

	/**
	 * The player clicked an option on an object.
	 *
	 * @param skill the skill the option trains, or null to forget any object
	 * @param x     the object's south-west world tile
	 * @param sizeX its footprint, at least 1
	 */
	void clicked(Skill skill, int x, int y, int plane, int sizeX, int sizeY, int tick)
	{
		forget();
		if (skill == null)
		{
			return;
		}

		this.skill = skill;
		this.plane = plane;
		minX = x;
		minY = y;
		maxX = x + Math.max(1, sizeX) - 1;
		maxY = y + Math.max(1, sizeY) - 1;
		clickTick = tick;
	}

	/** Drop the object: another click, combat, or the badge expired. */
	void forget()
	{
		skill = null;
		clickTick = -1;
		started = false;
		animating = false;
	}

	/** An object is clicked and not yet forgotten. */
	boolean held()
	{
		return skill != null;
	}

	/** The badge is up for this object, lingering or not. */
	boolean started()
	{
		return skill != null && started;
	}

	/** Still swinging at it: holds the badge against the linger timeout. */
	boolean working()
	{
		return started() && animating;
	}

	Skill skill()
	{
		return skill;
	}

	/**
	 * One game tick.
	 *
	 * @param animating the local player has a non-idle animation
	 * @return what the badge should do
	 */
	Step tick(int tick, int playerX, int playerY, int playerPlane, boolean animating)
	{
		if (skill == null)
		{
			return Step.NONE;
		}

		final boolean near = near(playerX, playerY, playerPlane);

		if (!started)
		{
			if (animating && near)
			{
				started = true;
				this.animating = true;
				return Step.ENGAGE;
			}
			if (tick - clickTick > START_TICKS)
			{
				forget();
			}
			return Step.NONE;
		}

		if (!near)
		{
			forget();
			return Step.RELEASE;
		}

		if (animating != this.animating)
		{
			this.animating = animating;
			return animating ? Step.ENGAGE : Step.DISENGAGE;
		}
		return Step.NONE;
	}

	private boolean near(int x, int y, int playerPlane)
	{
		if (playerPlane != plane)
		{
			return false;
		}

		final int dx = Math.max(0, Math.max(minX - x, x - maxX));
		final int dy = Math.max(0, Math.max(minY - y, y - maxY));
		return Math.max(dx, dy) <= REACH;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Rectangle;

/**
 * Keeps the actor's overhead chat readable over the overhead readout.
 *
 * The game draws an actor's chat line at the same height the readout uses,
 * and the overlay paints over it. The game's text cannot be moved, so while
 * the readout covers it, the overlay draws its own copy of the line just
 * above the readout and the readout stays where it is.
 *
 * Pure: screen rectangles in, a baseline out, so it is testable without a
 * running game.
 */
final class OverheadChat
{
	/** Pixels left between the bottom of the chat copy and the readout. */
	static final int GAP = 2;

	private OverheadChat()
	{
	}

	/**
	 * @param text            the actor's overhead text
	 * @param cyclesRemaining client ticks before the game stops drawing it
	 * @return whether the game is drawing a chat line over the actor right now
	 */
	static boolean showing(String text, int cyclesRemaining)
	{
		// The text is left behind after it times out, so the countdown is what
		// says whether it is still on screen.
		return text != null && !text.trim().isEmpty() && cyclesRemaining > 0;
	}

	/**
	 * @param readout the readout's box on screen, bar included; not modified
	 * @param chat    the game's chat line's box on screen
	 * @param descent the chat font's descent
	 * @return the baseline to draw the chat copy at, or null when the readout
	 *         does not cover the game's line and no copy should be drawn
	 */
	static Integer baselineAbove(Rectangle readout, Rectangle chat, int descent)
	{
		// Only redraw when the line is actually covered: an uncovered line is
		// already readable, and a copy beside it would show the message twice.
		if (!readout.intersects(chat))
		{
			return null;
		}

		return readout.y - GAP - descent;
	}

	/**
	 * Where to draw a held line, whose game copy is hidden and so must always
	 * be drawn by the overlay: above the readout when the readout covers it,
	 * otherwise exactly where the game would have put it.
	 *
	 * @param readout the readout's box on screen; not modified
	 * @param chat    the game's chat line's box on screen
	 * @param descent the chat font's descent
	 */
	static int baseline(Rectangle readout, Rectangle chat, int descent)
	{
		final Integer above = baselineAbove(readout, chat, descent);
		return above != null ? above : chat.y + chat.height - descent;
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Collection;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;

/**
 * Takes the game's own overhead chat line off an actor while the overlay
 * draws its copy above the readout, so only one line is on screen.
 *
 * The game's line is hidden by swapping the actor's text for a blank, the way
 * the base client's Chat Filter blanks a filtered message. The countdown is
 * left alone, so the message lasts exactly as long as the game would have
 * shown it, and the stacking of the bar and head icons does not shift.
 * Releasing writes the text back and the game carries on drawing it for
 * whatever time is left.
 *
 * Never drops a message: a hold is let go the moment it is no longer wanted,
 * and if the game writes a new message over the blank, the new one wins and
 * the old hold is forgotten rather than restored over it. Must only be used on
 * the client thread.
 *
 * @param <A> the actor type; {@code Actor} in the client, anything in tests
 */
final class OverheadChatHolder<A>
{
	/** What the game's line is swapped for. Draws nothing. */
	static final String BLANK = " ";

	/** The three actor calls this needs, so it can be tested without a client. */
	interface Access<A>
	{
		String text(A actor);

		int cyclesRemaining(A actor);

		void setText(A actor, String text);
	}

	private final Access<A> access;

	/** The real text of every actor whose line is hidden. Identity: actors have no value equality. */
	private final Map<A, String> held = new IdentityHashMap<>();

	OverheadChatHolder(Access<A> access)
	{
		this.access = access;
	}

	/**
	 * The line the overlay must draw for this actor: the held text while the
	 * game's copy is hidden. Nothing held means the game is drawing its own
	 * line, and a copy would show the message twice.
	 *
	 * @return the text, or null when nothing is held
	 */
	String heldText(A actor)
	{
		return stillHeld(actor) ? held.get(actor) : null;
	}

	/**
	 * Takes a new message off the game the moment it is posted, from inside
	 * the text change ({@code OverheadTextChanged}), so the game never draws
	 * it for even one frame. Replaces any older hold: the newest message wins.
	 *
	 * The countdown is not checked: the client may set it just after the
	 * text. A message whose countdown never starts is dropped by the next
	 * {@link #update} without being written back, and the game would not
	 * have drawn it either.
	 *
	 * Our own blank posts back through the same event and is ignored here.
	 */
	void hold(A actor, String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			return;
		}

		held.put(actor, text);
		access.setText(actor, BLANK);
	}

	/**
	 * Brings the holds in line with the latest frame: hides the game's line
	 * for every covered actor that is talking, and gives it back to every
	 * other actor held so far.
	 *
	 * @param covered actors whose readout covered their chat line last frame
	 */
	void update(Collection<A> covered)
	{
		for (Iterator<Map.Entry<A, String>> it = held.entrySet().iterator(); it.hasNext(); )
		{
			final Map.Entry<A, String> entry = it.next();
			final A actor = entry.getKey();
			if (!stillHeld(actor))
			{
				// Timed out, or the game wrote a newer message over the blank.
				it.remove();
			}
			else if (!covered.contains(actor))
			{
				access.setText(actor, entry.getValue());
				it.remove();
			}
		}

		for (A actor : covered)
		{
			if (held.containsKey(actor))
			{
				continue;
			}

			final String text = access.text(actor);
			if (OverheadChat.showing(text, access.cyclesRemaining(actor)))
			{
				held.put(actor, text);
				access.setText(actor, BLANK);
			}
		}
	}

	/** Gives every held line back to the game. */
	void releaseAll()
	{
		for (Map.Entry<A, String> entry : held.entrySet())
		{
			if (stillHeld(entry.getKey()))
			{
				access.setText(entry.getKey(), entry.getValue());
			}
		}
		held.clear();
	}

	boolean isHolding(A actor)
	{
		return held.containsKey(actor) && stillHeld(actor);
	}

	/**
	 * Our blank is still in place and the game's countdown has not run out. A
	 * different text means the game has posted a new message since.
	 */
	private boolean stillHeld(A actor)
	{
		return held.containsKey(actor)
			&& BLANK.equals(access.text(actor))
			&& access.cyclesRemaining(actor) > 0;
	}
}

