package com.vinnyvangogh.combatvitals;

/**
 * Glides a pillar's fill to its new value over a few frames instead of
 * jumping a whole tick's worth at once. A big fall (a level gained, the
 * inventory banked) and anything after a long pause are shown at once:
 * sliding down past them would show something that never happened.
 *
 * Pure: the target and the frame's time in, the fraction to draw out.
 */
final class PillarAnimation
{
	/** About how long a change takes to settle. */
	static final long DURATION_MILLIS = 300;

	/** Falls bigger than this snap. */
	private static final double SNAP_FALL = 0.5;

	/** A frame gap longer than this, the overlay was not drawn: snap. */
	private static final long SNAP_PAUSE_MILLIS = 1_000;

	private static final double SETTLED = 0.002;

	private double shown = -1;
	private long lastMillis;

	double next(double target, long nowMillis)
	{
		final long elapsed = nowMillis - lastMillis;
		lastMillis = nowMillis;
		if (shown < 0 || shown - target > SNAP_FALL || elapsed > SNAP_PAUSE_MILLIS || elapsed < 0)
		{
			shown = target;
			return shown;
		}

		// Exponential approach: a quarter of the duration is one time constant,
		// so a change is within 2% of its target by the end of it.
		shown += (target - shown) * (1 - Math.exp(-elapsed / (DURATION_MILLIS / 4.0)));
		if (Math.abs(target - shown) < SETTLED)
		{
			shown = target;
		}
		return shown;
	}

	void reset()
	{
		shown = -1;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * The inventory pillar's icon: a small brown backpack, drawn here rather
 * than taken from a game sprite so it needs no sprite id and no client.
 * Sized like the small skill icons the other pillars carry.
 */
final class PillarIcons
{
	static final int SIZE = 16;

	private static final Color LEATHER = new Color(150, 100, 50);
	private static final Color FLAP = new Color(115, 72, 34);
	private static final Color BUCKLE = new Color(230, 190, 80);
	private static final Color OUTLINE = new Color(20, 12, 4);

	private static BufferedImage backpack;

	private PillarIcons()
	{
	}

	static synchronized BufferedImage backpack()
	{
		if (backpack == null)
		{
			backpack = drawBackpack();
		}
		return backpack;
	}

	private static BufferedImage drawBackpack()
	{
		final BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(new BasicStroke(1f));

			// Carry handle.
			g.setColor(OUTLINE);
			g.drawRoundRect(5, 0, 5, 4, 3, 3);

			// Body.
			g.setColor(LEATHER);
			g.fillRoundRect(2, 3, 12, 12, 5, 5);
			g.setColor(OUTLINE);
			g.drawRoundRect(2, 3, 11, 12, 5, 5);

			// Flap over the top half, and its buckle.
			g.setColor(FLAP);
			g.fillRoundRect(3, 4, 10, 5, 3, 3);
			g.setColor(OUTLINE);
			g.drawLine(3, 9, 12, 9);
			g.setColor(BUCKLE);
			g.fillRect(7, 8, 2, 3);

			// Front pocket.
			g.setColor(OUTLINE);
			g.drawRoundRect(4, 11, 7, 3, 2, 2);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}
}

