package com.vinnyvangogh.combatvitals;

/**
 * What each side pillar says: the short number under its icon, the level
 * at its foot, its hover text, and where its tick marks go.
 *
 * A pillar is 20 px wide, so the number is three or four characters at
 * most; the hover text says the rest in words.
 *
 * Pure: values in, text and positions out.
 */
final class PillarText
{
	private PillarText()
	{
	}

	/**
	 * "82%", or the XP left, "65" or "1.2k", per the XP display setting;
	 * "Max" at 200m. Every skill's percent carries its sign (Board,
	 * 2026-11-09); {@link PillarPainter} condenses one too wide for the bar.
	 */
	static String xpNumber(XpProgress xp, XpDisplay display)
	{
		if (maxed(xp))
		{
			return "Max";
		}
		// Both reads as the percentage: there is room for one number.
		return display == XpDisplay.XP_LEFT ? compact(xp.getXpLeft()) : percent(xp) + "%";
	}

	/**
	 * Four characters at most, for 20 px: "65", "1.2k", "29k", "1.2m", "13m".
	 * The session row's short numbers, without the decimal from 10k and 10m.
	 */
	static String compact(long n)
	{
		if (n < 9_950 || (n >= 999_500 && n < 9_950_000))
		{
			return SessionRow.shortNumber(n);
		}
		return n < 999_500 ? Math.round(n / 1_000.0) + "k" : Math.round(n / 1_000_000.0) + "m";
	}

	/** The level being worked through, at the foot of the XP pillar: "16". */
	static String xpBottom(XpProgress xp)
	{
		return Integer.toString(xp.getLevel());
	}

	/** "Fishing XP: 82% to level 17 (65 xp left)", "Fishing XP: 6% to 200m (...)", "Fishing XP: 200m". */
	static String xpTooltip(String skillName, XpProgress xp)
	{
		if (maxed(xp))
		{
			return skillName + " XP: 200m";
		}
		final String to = xp.getNextLevel() > 0 ? "level " + xp.getNextLevel() : "200m";
		return String.format("%s XP: %d%% to %s (%,d xp left)", skillName, percent(xp), to, xp.getXpLeft());
	}

	/** Free slots, or used ones, per the Inventory count setting: "18"; null while unread. */
	static String inventoryNumber(int empty, InventoryCount count)
	{
		if (empty < 0)
		{
			return null;
		}
		return Integer.toString(count == InventoryCount.USED ? InventoryFill.SLOTS - empty : empty);
	}

	/** "Inventory: 10 of 28 free", "Inventory: 18 of 28 used"; null while unread. */
	static String inventoryTooltip(int empty, InventoryCount count)
	{
		final String number = inventoryNumber(empty, count);
		return number == null ? null
			: "Inventory: " + number + " of " + InventoryFill.SLOTS + (count == InventoryCount.USED ? " used" : " free");
	}

	/**
	 * The target's hitpoints: exact when known, else the middle of the
	 * recovered range, else -1 (only the bar's fraction is known).
	 */
	static int targetHp(int exactHealth, HealthRecovery.Range range, int maxHealth)
	{
		if (exactHealth >= 0)
		{
			return exactHealth;
		}
		return range != null && maxHealth > 0 ? range.midpoint() : -1;
	}

	/** "12", or "82%" when only the fraction is known. */
	static String targetNumber(int hp, double fraction)
	{
		return hp >= 0 ? Integer.toString(hp) : Math.round(fraction * 100) + "%";
	}

	/** "Target: Rock Crab 12/50", or "Target: Goblin 82%". */
	static String targetTooltip(String name, int hp, int maxHealth, double fraction)
	{
		final String health = hp >= 0 && maxHealth > 0 ? hp + "/" + maxHealth : Math.round(fraction * 100) + "%";
		return "Target: " + name + " " + health;
	}

	/**
	 * Where the marks between {@code divisions} equal parts of a track go,
	 * top to bottom: 3 for quarters, 27 between 28 slots.
	 *
	 * @param top    the track's top y
	 * @param height the track's height
	 */
	static int[] ticks(int top, int height, int divisions)
	{
		if (divisions <= 1 || height <= 0)
		{
			return new int[0];
		}
		final int[] ticks = new int[divisions - 1];
		for (int i = 1; i < divisions; i++)
		{
			ticks[i - 1] = top + (int) Math.round((double) height * i / divisions);
		}
		return ticks;
	}

	/** Rounded down, as the badge: 1 xp short of a level reads 99%. */
	private static int percent(XpProgress xp)
	{
		return (int) Math.floor(xp.getFraction() * 100);
	}

	private static boolean maxed(XpProgress xp)
	{
		return xp.getNextLevel() < 0 && xp.getXpLeft() <= 0;
	}
}

package com.vinnyvangogh.combatvitals;

/**
 * Lays out the badge's session row: each column as wide as its own cell,
 * not as wide as the widest (Board's in-game test, 2026-11-04: with every
 * stat on the badge was far too wide).
 *
 * In the Full layout the count has a line of its own and the rates go on
 * the line under it, for every skill alike. Wrapping only when the row was
 * wider than the rest of the badge made the layout depend on how wide the
 * skill's header happened to be: woodcutting and thieving put "xp/h" on its
 * own line while mining and fishing kept one (Board, 2026-11-06).
 *
 * Pure: cell counts and widths in pixels, padding included, in; lines and
 * column widths out.
 */
final class SessionColumns
{
	private SessionColumns()
	{
	}

	/**
	 * The row's lines, each as {from, to} cell indexes, top line first.
	 *
	 * @param cells      how many cells the row has
	 * @param countFirst the first cell is the count ("24 caught in 3m")
	 * @param wrap       whether two lines are allowed (the Full layout)
	 */
	static int[][] lines(int cells, boolean countFirst, boolean wrap)
	{
		if (!wrap || !countFirst || cells < 2)
		{
			return new int[][]{{0, cells}};
		}
		return new int[][]{{0, 1}, {1, cells}};
	}

	/** The widest line's natural width. */
	static int width(int[] widths, int[][] lines)
	{
		int widest = 0;
		for (int[] line : lines)
		{
			widest = Math.max(widest, sum(widths, line[0], line[1]));
		}
		return widest;
	}

	/**
	 * One line's columns stretched to fill the badge: every column keeps its
	 * own width and the spare pixels are shared out evenly, the leftover
	 * ones to the leftmost columns.
	 */
	static int[] fit(int[] widths, int[] line, int lineWidth)
	{
		final int count = line[1] - line[0];
		final int[] columns = new int[count];
		if (count == 0)
		{
			return columns;
		}

		final int spare = Math.max(0, lineWidth - sum(widths, line[0], line[1]));
		for (int i = 0; i < count; i++)
		{
			columns[i] = widths[line[0] + i] + spare / count + (i < spare % count ? 1 : 0);
		}
		return columns;
	}

	private static int sum(int[] widths, int from, int to)
	{
		int total = 0;
		for (int i = from; i < to; i++)
		{
			total += widths[i];
		}
		return total;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import lombok.Value;
import net.runelite.api.Skill;

/**
 * The badge's session row as columns: "24 caught in 3m", "10.6k xp/h",
 * "459 fish/h", "lvl 18 in 6m". Each cell is one stat with its own soft
 * shade of the skill colour; the renderer draws them in equal columns with
 * a thin rule between, in place of the old "Caught 24 | 10,597 xp/h | 459/h".
 *
 * Pure: counts, rates and milliseconds in, short text out.
 */
final class SessionRow
{
	private static final long SECOND = 1_000;
	private static final long MINUTE = 60 * SECOND;
	private static final long HOUR = 60 * MINUTE;
	private static final long DAY = 24 * HOUR;

	enum Kind
	{
		COUNT,
		XP_RATE,
		ACTION_RATE,
		TIME_TO_LEVEL
	}

	@Value
	static class Cell
	{
		Kind kind;
		String text;
	}

	private SessionRow()
	{
	}

	/**
	 * @param elapsedMillis  since the session's first gain, or -1 before it
	 * @param xpPerHour      -1 while not yet known
	 * @param actionsPerHour -1 while not yet known
	 * @param timeToLevel    add the time to the next level when the rates are on
	 * @return the cells, left to right; empty when both the count and the rates are off
	 */
	static List<Cell> cells(Skill skill, int actions, long elapsedMillis, int xpPerHour, int actionsPerHour,
		XpProgress xp, boolean count, boolean rates, boolean timeToLevel)
	{
		if (!count && !rates)
		{
			return Collections.emptyList();
		}

		final List<Cell> cells = new ArrayList<>(4);
		if (count)
		{
			cells.add(new Cell(Kind.COUNT, count(skill, actions, elapsedMillis)));
		}
		if (rates)
		{
			add(cells, Kind.XP_RATE, xpRate(xpPerHour));
			add(cells, Kind.ACTION_RATE, actionRate(skill, actionsPerHour));
			if (timeToLevel)
			{
				add(cells, Kind.TIME_TO_LEVEL, timeToLevel(xp, xpPerHour));
			}
		}
		return cells;
	}

	/**
	 * The Compact layout's one short line: "24 caught | 10.6k xp/h", the
	 * count without its time and the XP rate alone. Either half follows its
	 * own switch.
	 *
	 * @return the cells, left to right; empty when both the count and the rates are off
	 */
	static List<Cell> compactCells(Skill skill, int actions, int xpPerHour, boolean count, boolean rates)
	{
		final List<Cell> cells = new ArrayList<>(2);
		if (count)
		{
			cells.add(new Cell(Kind.COUNT, count(skill, actions, -1)));
		}
		if (rates)
		{
			add(cells, Kind.XP_RATE, xpRate(xpPerHour));
		}
		return cells;
	}

	private static void add(List<Cell> cells, Kind kind, String text)
	{
		if (text != null)
		{
			cells.add(new Cell(kind, text));
		}
	}

	/** "24 caught in 3m"; "0 caught" before the first gain. */
	static String count(Skill skill, int actions, long elapsedMillis)
	{
		final String done = actions + " " + done(skill);
		return elapsedMillis < 0 ? done : done + " in " + duration(elapsedMillis);
	}

	/**
	 * "10.6k xp/h", or null for the first minute: nothing is shown until a
	 * rate exists, rather than "-- xp/h" (Board, 2026-11-06).
	 */
	static String xpRate(int xpPerHour)
	{
		return xpPerHour < 0 ? null : shortNumber(xpPerHour) + " xp/h";
	}

	/** "459 fish/h", or null while not yet known. */
	static String actionRate(Skill skill, int actionsPerHour)
	{
		return actionsPerHour < 0 ? null : shortNumber(actionsPerHour) + " " + noun(skill) + "/h";
	}

	/**
	 * "lvl 18 in 6m" at this rate, or null with no rate yet, a rate of 0, or
	 * no level left to reach (99 and past: the 200m cap is not a level).
	 */
	static String timeToLevel(XpProgress xp, int xpPerHour)
	{
		if (xpPerHour <= 0 || xp.getNextLevel() < 0)
		{
			return null;
		}
		final long millis = xp.getXpLeft() * HOUR / xpPerHour;
		return "lvl " + xp.getNextLevel() + " in " + duration(millis);
	}

	/** "45s", "3m", "1h 05m", "2d 3h": two units at most, rounded down. */
	static String duration(long millis)
	{
		final long ms = Math.max(0, millis);
		if (ms < MINUTE)
		{
			return ms / SECOND + "s";
		}
		if (ms < HOUR)
		{
			return ms / MINUTE + "m";
		}
		if (ms < DAY)
		{
			return String.format(Locale.ROOT, "%dh %02dm", ms / HOUR, ms % HOUR / MINUTE);
		}
		return ms / DAY + "d " + ms % DAY / HOUR + "h";
	}

	/** 459, 1.2k, 10.6k, 125k, 1.2m: three significant figures at most, ".0" dropped. */
	static String shortNumber(long n)
	{
		if (n < 1_000)
		{
			return Long.toString(n);
		}
		// 999,500 and up would round to "1000k"; it reads as 1m.
		return n < 999_500 ? scaled(n / 1_000.0, "k") : scaled(n / 1_000_000.0, "m");
	}

	private static String scaled(double value, String unit)
	{
		if (value >= 99.95)
		{
			return Math.round(value) + unit;
		}
		final String text = String.format(Locale.ROOT, "%.1f", value);
		return (text.endsWith(".0") ? text.substring(0, text.length() - 2) : text) + unit;
	}

	/**
	 * A soft shade of the skill colour per stat, lighter for each, so the
	 * columns tell apart at a glance and all read as the one skill.
	 */
	static Color tint(Color skill, Kind kind)
	{
		final double white = 0.35 + 0.15 * kind.ordinal();
		return new Color(
			lighten(skill.getRed(), white),
			lighten(skill.getGreen(), white),
			lighten(skill.getBlue(), white));
	}

	private static int lighten(int channel, double white)
	{
		return (int) Math.round(channel + (255 - channel) * white);
	}

	/** What was done, after the count: "24 caught". */
	private static String done(Skill skill)
	{
		switch (skill)
		{
			case FISHING:
			case HUNTER:
				return "caught";
			case WOODCUTTING:
				return "chopped";
			case MINING:
				return "mined";
			case THIEVING:
				return "stolen";
			case RUNECRAFT:
				return "crafted";
			default:
				return "done";
		}
	}

	/** One action, in the per-hour rate: "459 fish/h". */
	private static String noun(Skill skill)
	{
		switch (skill)
		{
			case FISHING:
				return "fish";
			case WOODCUTTING:
				return "logs";
			case MINING:
				return "ores";
			case THIEVING:
				return "steals";
			case HUNTER:
				return "catches";
			case RUNECRAFT:
				return "crafts";
			default:
				return "actions";
		}
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Collection;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;

/**
 * Hands a tile to the Shortest Path plugin (Skretzo/shortest-path) as a
 * target, and clears it again.
 *
 * Copied from QuestPath's {@code ShortestPathBridge}
 * (VinnyVanGogh/questpath-plugin, main), which verified every constant and
 * the message shape with {@code javap -c} against the installed Shortest Path
 * jar; that class's doc has the full record. In short:
 *
 * <ul>
 * <li>Nothing here reflects into Shortest Path. It listens for RuneLite's own
 * {@link PluginMessage} (shipped in {@code runelite-client}), namespace
 * {@code "shortestpath"}: {@code "path"} with a {@code "target"} entry that
 * may be a {@code WorldPoint}, a packed int or a {@code Set} of either, and
 * {@code "clear"} to clear. An empty target set does NOT clear; it re-sends
 * the previous targets. Re-checked against Skretzo/shortest-path master
 * 4c6595e (2026-11-04): {@code api/PluginMessageHandler#onPluginMessage}
 * (L90-103) routes {@code "path"} to {@code onPathMessage} (L107-138), which
 * reads {@code "target"} and hands it to {@code PluginMessageTargets#decode}
 * (L49-68): a {@code Collection} is decoded element by element, and a
 * {@code WorldPoint} element is accepted.</li>
 * <li>Its {@code onPluginMessage} asserts it is on the client thread, and
 * {@code EventBus#post} calls subscribers on the posting thread, so the
 * poster must land the post there: build it with
 * {@link #clientThreadEventPoster}. The assertion is an {@code Error}, which
 * is why the catches below take {@code AssertionError} too.</li>
 * <li>Posting is fire-and-forget: {@link RouteOutcome#SENT} means the event
 * went out, never that a path is drawn. Seeing the line needs a human at a
 * client.</li>
 * <li>Shortest Path clears its own path when the player gets within its
 * "reached distance" of the target.</li>
 * </ul>
 */
@Slf4j
class ShortestPathBridge
{
	static final String PLUGIN_CLASS_NAME = "shortestpath.ShortestPathPlugin";
	static final String CONFIG_GROUP = "shortestpath";
	static final String MESSAGE_NAME = "path";
	static final String CLEAR_MESSAGE_NAME = "clear";
	static final String TARGET_KEY = "target";

	/** Whether a path can be handed to Shortest Path right now, and why not when it cannot. */
	enum Availability
	{
		AVAILABLE,
		NOT_INSTALLED,
		NOT_ENABLED,
	}

	/** What became of a {@link #route} call. */
	enum RouteOutcome
	{
		UNAVAILABLE,
		/** The poster threw; logged at warn. */
		CALL_FAILED,
		/** Handed to the poster without throwing. Not proof a path is drawn. */
		SENT,
	}

	private final Supplier<Collection<?>> plugins;
	private final Predicate<Object> pluginEnabled;
	private final String pluginClassName;
	private final Consumer<Object> eventPoster;

	/**
	 * @param plugins       every plugin RuneLite knows about, e.g. {@code pluginManager::getPlugins}
	 * @param pluginEnabled whether a plugin instance is switched on
	 * @param eventPoster   posts on the client thread; build with {@link #clientThreadEventPoster}
	 */
	ShortestPathBridge(Supplier<Collection<?>> plugins, Predicate<Object> pluginEnabled, Consumer<Object> eventPoster)
	{
		this(plugins, pluginEnabled, PLUGIN_CLASS_NAME, eventPoster);
	}

	/** Test seam: the plugin class name is overridable so a test can stand in a fixture. */
	ShortestPathBridge(Supplier<Collection<?>> plugins, Predicate<Object> pluginEnabled, String pluginClassName,
		Consumer<Object> eventPoster)
	{
		this.plugins = plugins;
		this.pluginEnabled = pluginEnabled;
		this.pluginClassName = pluginClassName;
		this.eventPoster = eventPoster;
	}

	/**
	 * A poster that always lands {@code post} on the client thread, whichever
	 * thread calls it.
	 *
	 * @param onClientThread production passes {@code clientThread::invoke}
	 * @param post           production passes {@code eventBus::post}
	 */
	static Consumer<Object> clientThreadEventPoster(Consumer<Runnable> onClientThread, Consumer<Object> post)
	{
		return object -> onClientThread.accept(() -> post.accept(object));
	}

	Availability availability()
	{
		final Object plugin = findPlugin();
		if (plugin == null)
		{
			return Availability.NOT_INSTALLED;
		}
		return isEnabledSafely(plugin) ? Availability.AVAILABLE : Availability.NOT_ENABLED;
	}

	/** Sends one tile as Shortest Path's target, replacing whatever path it had. */
	RouteOutcome route(WorldPoint target)
	{
		final Availability availability = availability();
		if (availability != Availability.AVAILABLE)
		{
			log.debug("Not sending a fishing spot to Shortest Path -- {}", availability);
			return RouteOutcome.UNAVAILABLE;
		}
		if (!post(MESSAGE_NAME, Map.of(TARGET_KEY, Set.of(target))))
		{
			return RouteOutcome.CALL_FAILED;
		}
		log.debug("Sent fishing spot {} to Shortest Path", target);
		return RouteOutcome.SENT;
	}

	/** Clears Shortest Path's path. @return whether the message went out */
	boolean clear()
	{
		return availability() == Availability.AVAILABLE && post(CLEAR_MESSAGE_NAME, Map.of());
	}

	private boolean post(String name, Map<String, Object> data)
	{
		try
		{
			eventPoster.accept(new PluginMessage(CONFIG_GROUP, name, data));
			return true;
		}
		// Not Throwable: an OutOfMemoryError this deep is not "Shortest Path
		// didn't get the message" and must not be reported as one.
		catch (RuntimeException | AssertionError e)
		{
			log.warn("Posting PluginMessage(\"{}\", \"{}\") failed -- Shortest Path may be out of date",
				CONFIG_GROUP, name, e);
			return false;
		}
	}

	private boolean isEnabledSafely(Object plugin)
	{
		try
		{
			return pluginEnabled.test(plugin);
		}
		catch (RuntimeException e)
		{
			log.warn("Could not read Shortest Path's enabled state", e);
			return false;
		}
	}

	private Object findPlugin()
	{
		final Collection<?> loaded;
		try
		{
			loaded = plugins.get();
		}
		catch (RuntimeException e)
		{
			log.warn("Could not list loaded plugins while looking for Shortest Path", e);
			return null;
		}
		if (loaded == null)
		{
			return null;
		}
		for (Object candidate : loaded)
		{
			if (candidate != null && pluginClassName.equals(candidate.getClass().getName()))
			{
				return candidate;
			}
		}
		return null;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Rectangle;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.gameval.InterfaceID;

/**
 * Where the two vertical bars beside the side panel (the "pillars") go.
 *
 * The placement follows RuneLite's own Status Bars plugin (BSD-2-Clause,
 * runelite-client {@code net.runelite.client.plugins.statusbars}:
 * {@code StatusBarsOverlay#render} and {@code Viewport}), so the bars sit
 * exactly where a RuneLite user expects them: the first visible of four
 * side-panel widgets decides the layout, and each has fixed offsets from
 * that widget's canvas location. The numbers are the same; the code is
 * this plugin's own.
 *
 * Alongside Status Bars: while it is off, or has both its bars set to
 * Disabled, ours take the two pillars. While it draws either bar, both of
 * ours stack to the left of its leftmost bar, beside it, out over the game
 * view where there is always room; stacking rather than taking a free
 * pillar keeps our two bars together and in order. They never go over the
 * inventory and never overlap its bars.
 *
 * Pure: a widget's bounds and Status Bars' settings in, two rectangles out.
 */
final class SidePillars
{
	/** Status Bars' {@code BarRenderer.DEFAULT_WIDTH}, and the width of ours. */
	static final int WIDTH = 20;

	/** Status Bars' bar heights: the classic layouts, and resizable with the panel along the bottom. */
	static final int HEIGHT = 252;
	static final int RESIZED_BOTTOM_HEIGHT = 272;

	/** Space between our bar and a Status Bars bar beside it. */
	static final int GAP = 2;

	/** Status Bars' {@code RESIZED_BOTTOM_OFFSET_X} and {@code _Y}. */
	private static final int RESIZED_BOTTOM_OFFSET_X = 10;
	private static final int RESIZED_BOTTOM_OFFSET_Y = 12;

	/** The four side-panel layouts, in the order Status Bars checks them, with its offsets. */
	@Getter
	@AllArgsConstructor
	enum Viewport
	{
		RESIZED_BOX(InterfaceID.ToplevelOsrsStretch.SIDE_CONTAINER, 20, -4, 0, -4),
		RESIZED_BOTTOM(InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND, 61, -12, 35, -12),
		FIXED(InterfaceID.Toplevel.SIDE_PANELS, 20, -4, 0, -4),
		FIXED_BANK(InterfaceID.Bankside.ITEMS, 20, -4, 0, -4);

		private final int widget;
		private final int leftX;
		private final int leftY;
		private final int rightX;
		private final int rightY;
	}

	/** Status Bars as this plugin sees it: on or off, which pillars it uses, and its width setting. */
	@AllArgsConstructor
	static final class StatusBars
	{
		static final StatusBars OFF = new StatusBars(false, false, false, WIDTH);

		final boolean enabled;
		final boolean left;
		final boolean right;
		final int width;

		boolean usesAny()
		{
			return enabled && (left || right);
		}
	}

	/** Our two bars. */
	@Getter
	@AllArgsConstructor
	static final class Layout
	{
		private final Rectangle left;
		private final Rectangle right;

		Rectangle get(PillarSide side)
		{
			return side == PillarSide.LEFT ? left : right;
		}
	}

	private SidePillars()
	{
	}

	/**
	 * @param widgetX     the side-panel widget's canvas x
	 * @param widgetY     its canvas y
	 * @param widgetWidth its width
	 */
	static Layout layout(Viewport viewport, int widgetX, int widgetY, int widgetWidth, StatusBars statusBars)
	{
		if (!statusBars.usesAny())
		{
			// Nothing of Status Bars is drawn, so its width setting is moot:
			// the pillars as they are at the default width.
			final Rectangle[] free = statusBarSlots(viewport, widgetX, widgetY, widgetWidth, StatusBars.OFF);
			return new Layout(free[0], free[1]);
		}

		final Rectangle[] slots = statusBarSlots(viewport, widgetX, widgetY, widgetWidth, statusBars);
		final Rectangle left = slots[0];
		final Rectangle right = slots[1];

		// Status Bars is drawing: ours go left of its leftmost bar. When only
		// its right pillar is used, its left slot is free, and in the classic
		// layouts that slot is the edge to stack from.
		final boolean bottom = viewport == Viewport.RESIZED_BOTTOM;
		final int edge = statusBars.left ? left.x : bottom ? right.x : left.x + WIDTH + GAP;
		final int ourRight = edge - WIDTH - GAP;
		return new Layout(ours(ourRight - WIDTH - GAP, left), ours(ourRight, left));
	}

	/**
	 * Where Status Bars draws its left and right bars. Its width setting only
	 * applies with the panel along the bottom; the classic layouts always use
	 * the default.
	 */
	static Rectangle[] statusBarSlots(Viewport viewport, int widgetX, int widgetY, int widgetWidth,
		StatusBars statusBars)
	{
		if (viewport == Viewport.RESIZED_BOTTOM)
		{
			final int width = statusBars.enabled ? Math.max(3, Math.min(40, statusBars.width)) : WIDTH;
			final int extra = width - WIDTH;
			final int x = widgetX + RESIZED_BOTTOM_OFFSET_X;
			final int y = widgetY - RESIZED_BOTTOM_OFFSET_Y;
			return new Rectangle[] {
				new Rectangle(x - viewport.leftX - 2 * extra, y - viewport.leftY, width, RESIZED_BOTTOM_HEIGHT),
				new Rectangle(x - viewport.rightX - extra, y - viewport.rightY, width, RESIZED_BOTTOM_HEIGHT),
			};
		}

		return new Rectangle[] {
			new Rectangle(widgetX - viewport.leftX, widgetY - viewport.leftY, WIDTH, HEIGHT),
			new Rectangle(widgetX - viewport.rightX + widgetWidth, widgetY - viewport.rightY, WIDTH, HEIGHT),
		};
	}

	/** One of our bars at {@code x}, at the slot's height. */
	private static Rectangle ours(int x, Rectangle slot)
	{
		return new Rectangle(x, slot.y, WIDTH, slot.height);
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * The skilling badge's colour per skill, so the skill reads at a glance.
 *
 * Every colour sits in the middle of the luminance range (WCAG relative
 * luminance about 0.15 to 0.25), which keeps a contrast of at least 3:1
 * against both white and black: readable as text over snow or a cave, and
 * under the badge's white text when used as the bar fill.
 * {@code SkillColoursTest} checks every skill.
 */
final class SkillColours
{
	/** Slate grey, for any skill without its own colour. */
	static final Color DEFAULT = new Color(0x6E7681);

	private static final Map<Skill, Color> COLOURS = new EnumMap<>(Skill.class);

	static
	{
		COLOURS.put(Skill.FISHING, new Color(0x3A7BD5));
		COLOURS.put(Skill.WOODCUTTING, new Color(0x2E8B3A));
		COLOURS.put(Skill.MINING, new Color(0x8C6E52));
		COLOURS.put(Skill.THIEVING, new Color(0x9050C8));
		COLOURS.put(Skill.HUNTER, new Color(0xB0602A));
		COLOURS.put(Skill.RUNECRAFT, new Color(0xA88418));
	}

	private SkillColours()
	{
	}

	static Color of(Skill skill)
	{
		return skill == null ? DEFAULT : COLOURS.getOrDefault(skill, DEFAULT);
	}

	/** WCAG 2 contrast ratio between two colours, 1 to 21. */
	static double contrast(Color a, Color b)
	{
		final double la = luminance(a);
		final double lb = luminance(b);
		return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
	}

	private static double luminance(Color c)
	{
		return 0.2126 * linear(c.getRed()) + 0.7152 * linear(c.getGreen()) + 0.0722 * linear(c.getBlue());
	}

	private static double linear(int channel)
	{
		final double s = channel / 255.0;
		return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * Works out which skill an NPC or object trains, from its menu options.
 *
 * A fishing spot's menu says "Net" or "Harpoon"; a pickpocket target's says
 * "Pickpocket". The option is the only thing the client exposes that ties the
 * NPC to a skill, and it is enough: an unknown option means no badge rather
 * than a guess, which is the same rule the health readout follows.
 *
 * Pure and stateless, so the table is testable without a client.
 */
final class SkillingActions
{
	/** Menu option, lower case, to the skill it trains. */
	private static final Map<String, Skill> BY_ACTION = new HashMap<>();

	static
	{
		// Fishing spots: every style the OSRS wiki lists for an NPC spot.
		for (String action : new String[] {
			"net", "small net", "big net", "bait", "lure", "cage", "harpoon", "use-rod", "fish", "cast"})
		{
			BY_ACTION.put(action, Skill.FISHING);
		}

		BY_ACTION.put("pickpocket", Skill.THIEVING);
		BY_ACTION.put("knock-out", Skill.THIEVING);

		// Implings and butterflies. Aerial fishing shoals also say "Catch" and
		// are told apart by name below.
		BY_ACTION.put("catch", Skill.HUNTER);

		// Trees, rocks, stalls and altars are objects, matched by the clicked
		// option alone; rare as NPCs, but harmless there too.
		BY_ACTION.put("mine", Skill.MINING);
		BY_ACTION.put("chop down", Skill.WOODCUTTING);
		BY_ACTION.put("chop", Skill.WOODCUTTING);
		BY_ACTION.put("steal-from", Skill.THIEVING);
		BY_ACTION.put("craft-rune", Skill.RUNECRAFT);
	}

	private SkillingActions()
	{
	}

	/**
	 * @param actions the NPC's menu options, {@code NPCComposition#getActions()}
	 * @param name    the NPC's name, used only to split "Catch" between fishing
	 *                and hunter
	 * @return the skill the NPC trains, or null when none is recognised
	 */
	static Skill skill(String[] actions, String name)
	{
		if (actions == null)
		{
			return null;
		}

		for (String action : actions)
		{
			final Skill skill = forOption(action, name);
			if (skill != null)
			{
				return skill;
			}
		}
		return null;
	}

	/**
	 * The skill one clicked menu option trains. This is what decides an NPC
	 * that can be both fought and skilled, a Man that can be pickpocketed,
	 * and every object: a tree's "Chop down", a rock's "Mine".
	 *
	 * @param option the menu option, e.g. "Pickpocket"
	 * @param name   the target's name, used only to split "Catch"
	 * @return the skill, or null when the option is not a skilling one
	 */
	static Skill forOption(String option, String name)
	{
		if (option == null)
		{
			return null;
		}

		final Skill skill = BY_ACTION.get(option.toLowerCase(Locale.ROOT));
		if (skill == Skill.HUNTER && name != null
			&& name.toLowerCase(Locale.ROOT).contains("shoal"))
		{
			return Skill.FISHING;
		}
		return skill;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The skilling badge with "Fixed on screen": an ordinary overlay the user
 * Alt-drags wherever they like, and RuneLite remembers where.
 */
class SkillingBadgeOverlay extends Overlay
{
	private final CombatVitalsPlugin plugin;
	private final CombatVitalsConfig config;
	private final SkillingBadgeRenderer badge;

	@Inject
	SkillingBadgeOverlay(CombatVitalsPlugin plugin, CombatVitalsConfig config, SkillingBadgeRenderer badge)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.badge = badge;

		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final SkillingReadout readout = plugin.getSkillingReadout();
		if (readout == null || !config.skillingEnabled() || config.skillingPosition() != BadgePosition.FIXED)
		{
			return null;
		}
		return badge.drawFromCorner(graphics, readout);
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws the skilling badge, for whichever overlay places it: over your
 * head, over the spot, or fixed on screen. The badge is drawn with its
 * bottom centre at the origin of the current transform, so the caller
 * translates to the anchor and scales for the size setting first.
 *
 * Rows, bottom up, each one of the same width and each with its own switch:
 * <ol>
 * <li>the inventory line: free or used slots on the fill bar, and on a
 * fishing spot every fish the method can give;</li>
 * <li>the session line: count this session and the hourly rates;</li>
 * <li>the XP line: progress to the next level;</li>
 * <li>"Needs: Fishing rod + bait" in red, for a few seconds after clicking
 * a fishing option without what it takes;</li>
 * <li>the header, in the skill's colour: icon, level, boost, timer; or
 * "Not fishing" in the idle colour once you stop.</li>
 * </ol>
 */
class SkillingBadgeRenderer
{
	/** Space between the text and the edge of the bar behind it. */
	static final int PAD_X = 4;
	static final int PAD_Y = 2;

	/** Space between the skill icon and the header text. */
	private static final int ICON_GAP = 3;

	/** Space between the badge's rows. */
	private static final int ROW_GAP = 1;

	/** Fish the player's level does not land yet are dimmed, with the level they need over them. */
	private static final float LOCKED_FISH_ALPHA = 0.35f;

	/** Height of a catch icon in the inventory line; item sprites are 32 high, so about half. */
	private static final int FISH_ICON = 18;

	/** Height of the skill icon before the session count, inside a small-font row. */
	private static final int SESSION_ICON = 11;

	/** The faint rule between the session row's columns. */
	private static final Color SESSION_RULE = new Color(255, 255, 255, 60);

	/**
	 * The light backing behind every session icon, whatever the skill, so a
	 * near-black icon (Thieving's mask) reads on the dark row and every skill
	 * looks the same. No per-icon brightness test: measured mean brightness
	 * cannot tell Thieving (0.152) from Mining (0.142) or Fishing (0.167).
	 */
	static final Color ICON_BACKING = new Color(255, 255, 255, 110);

	private final Client client;
	private final CombatVitalsConfig config;
	private final SkillIconManager skillIconManager;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;

	/** The readout and font {@link #measured} was taken for. Client thread only, like every overlay. */
	private SkillingReadout measuredFor;
	private Font measuredFont;
	private Measured measured;

	@Inject
	SkillingBadgeRenderer(Client client, CombatVitalsConfig config, SkillIconManager skillIconManager,
		ItemManager itemManager, TooltipManager tooltipManager)
	{
		this.client = client;
		this.config = config;
		this.skillIconManager = skillIconManager;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
	}

	/**
	 * Draws the badge, scaled by the size setting, with its bottom centre at
	 * ({@code x}, {@code y}).
	 *
	 * @return the badge's box on screen, or null when every row is off
	 */
	Rectangle drawAt(Graphics2D graphics, SkillingReadout readout, int x, int y)
	{
		final Layout layout = layout(graphics, readout);
		if (layout == null)
		{
			return null;
		}

		final double scale = scale();
		paintScaled(graphics, readout, layout, x, y, scale);
		final Rectangle box = layout.box;
		return new Rectangle(x + (int) Math.floor(box.x * scale), y + (int) Math.floor(box.y * scale),
			(int) Math.ceil(box.width * scale), (int) Math.ceil(box.height * scale));
	}

	/**
	 * Draws the badge, scaled, with its top left corner at the origin, for an
	 * overlay that the overlay manager places.
	 *
	 * @return the badge's size on screen, or null when every row is off
	 */
	Dimension drawFromCorner(Graphics2D graphics, SkillingReadout readout)
	{
		final Layout layout = layout(graphics, readout);
		if (layout == null)
		{
			return null;
		}

		final double scale = scale();
		final Rectangle box = layout.box;
		paintScaled(graphics, readout, layout, (int) Math.ceil(-box.x * scale), (int) Math.ceil(-box.y * scale), scale);
		return new Dimension((int) Math.ceil(box.width * scale), (int) Math.ceil(box.height * scale));
	}

	private double scale()
	{
		return Math.max(50, Math.min(200, config.skillingScale())) / 100.0;
	}

	private void paintScaled(Graphics2D graphics, SkillingReadout readout, Layout layout, int x, int y, double scale)
	{
		final AffineTransform saved = graphics.getTransform();
		graphics.translate(x, y);
		graphics.scale(scale, scale);
		try
		{
			paint(graphics, readout, layout);
		}
		finally
		{
			graphics.setTransform(saved);
		}
	}

	/** Every row's box, relative to the badge's bottom centre; null when every row is off. */
	private Layout layout(Graphics2D graphics, SkillingReadout readout)
	{
		final String text = headerText(readout);
		final FontMetrics metrics = graphics.getFontMetrics();
		final BufferedImage icon = skillIconManager.getSkillImage(readout.getSkill(), true);
		final int iconWidth = icon == null ? 0 : icon.getWidth() + ICON_GAP;
		final int headHeight = Math.max(metrics.getAscent() + metrics.getDescent(),
			icon == null ? 0 : icon.getHeight()) + PAD_Y * 2;

		// The lower rows use the small font, so each grows the badge by a short row.
		final FontMetrics small = graphics.getFontMetrics(FontManager.getRunescapeSmallFont());
		final int lineHeight = small.getAscent() + small.getDescent() + PAD_Y * 2;
		final Measured measured = measure(readout, small);

		// The session row's columns carry their own padding; in the Full
		// layout the count and the rates take a line each, for every skill.
		final int others = PAD_X * 2 + max(measured.gear,
			readout.isHeader() ? iconWidth + metrics.stringWidth(text) : 0, measured.xp, measured.inv);
		final List<SessionRow.Cell> cells = readout.getSessionCells();
		final int[][] lines = SessionColumns.lines(cells.size(),
			!cells.isEmpty() && cells.get(0).getKind() == SessionRow.Kind.COUNT,
			config.skillingBadgeLayout() == BadgeLayout.FULL);
		final int width = Math.max(SessionColumns.width(measured.cells, lines), others);

		final Rows rows = new Rows(-width / 2, width);
		final int invHeight = readout.getCatches().isEmpty() ? lineHeight : Math.max(lineHeight, FISH_ICON + 2);
		final Layout layout = new Layout(text, icon, measured.cells, lines);
		layout.inv = rows.add(readout.hasInventoryLine(), invHeight);
		// Stacked upward, so the last line goes on first.
		final boolean session = !readout.getSessionCells().isEmpty();
		for (int i = lines.length - 1; i >= 0; i--)
		{
			layout.session[i] = rows.add(session, lineHeight);
		}
		layout.xp = rows.add(readout.getXpText() != null, lineHeight);
		layout.gear = rows.add(readout.getGearText() != null, lineHeight);
		layout.head = rows.add(readout.isHeader(), headHeight);
		layout.box = rows.box();
		return rows.empty() ? null : layout;
	}

	private void paint(Graphics2D graphics, SkillingReadout readout, Layout layout)
	{
		if (layout.head != null)
		{
			drawHeader(graphics, layout.head, readout, layout.text, layout.icon);
		}

		final Font previous = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		try
		{
			drawSmallRows(graphics, readout, layout);
		}
		finally
		{
			graphics.setFont(previous);
		}
	}

	private void drawSmallRows(Graphics2D graphics, SkillingReadout readout, Layout layout)
	{
		final Rectangle gear = layout.gear;
		final Rectangle xp = layout.xp;
		final Rectangle inv = layout.inv;
		if (gear != null)
		{
			// Full in the low colour: something is missing, said before the game says it.
			Bars.across(graphics, gear, 1.0, config.healthLowColour(), config.barBackground());
			centredText(graphics, gear, readout.getGearText());
		}
		if (xp != null)
		{
			Bars.across(graphics, xp, readout.getXp().getFraction(), readout.getColour(), config.barBackground());
			centredText(graphics, xp, readout.getXpText());
		}
		for (int i = 0; i < layout.session.length; i++)
		{
			if (layout.session[i] != null)
			{
				drawSessionLine(graphics, layout, i, readout);
			}
		}
		if (inv != null)
		{
			drawInventoryLine(graphics, inv, readout);
		}
	}

	/**
	 * One line of the session row, each column as wide as its own stat with
	 * the badge's spare width shared out, one stat each in its own shade of
	 * the skill colour, with a faint rule between; the count leads with the
	 * skill icon: "[fish] 24 caught in 3m | 10.6k xp/h", then on a second
	 * line when it would be too wide, "459 fish/h | lvl 18 in 6m".
	 */
	private void drawSessionLine(Graphics2D graphics, Layout layout, int index, SkillingReadout readout)
	{
		final Rectangle row = layout.session[index];
		final int[] line = layout.sessionLines[index];
		Bars.across(graphics, row, 0, readout.getColour(), config.barBackground());

		final List<SessionRow.Cell> cells = readout.getSessionCells();
		final int baseline = textBaseline(row, graphics.getFontMetrics());
		final int[] columns = SessionColumns.fit(layout.cellWidths, line, row.width);
		int left = row.x;
		for (int i = 0; i < columns.length; i++)
		{
			if (i > 0)
			{
				graphics.setColor(SESSION_RULE);
				graphics.drawLine(left, row.y + 3, left, row.y + row.height - 4);
			}
			final Rectangle cell = new Rectangle(left, row.y, columns[i], row.height);
			drawSessionCell(graphics, cell, cells.get(line[0] + i), readout, baseline);
			left += columns[i];
		}
	}

	private void drawSessionCell(Graphics2D graphics, Rectangle cell, SessionRow.Cell c, SkillingReadout readout,
		int baseline)
	{
		final BufferedImage icon = c.getKind() == SessionRow.Kind.COUNT
			? skillIconManager.getSkillImage(readout.getSkill(), true) : null;
		final int iconWidth = sessionIconWidth(icon);
		final int x = cell.x + (cell.width - iconWidth - graphics.getFontMetrics().stringWidth(c.getText())) / 2;
		if (icon != null)
		{
			drawSessionIcon(graphics, icon, x, cell.y + (cell.height - SESSION_ICON) / 2, iconWidth - ICON_GAP);
		}
		OverlayUtil.renderTextLocation(graphics, new Point(x + iconWidth, baseline), c.getText(),
			SessionRow.tint(readout.getColour(), c.getKind()));
	}

	/**
	 * The small rows' text widths, measured once per readout rather than
	 * every frame: the readout is rebuilt once a game tick, so between ticks
	 * every frame would measure the same strings and look up the same icons.
	 */
	private Measured measure(SkillingReadout readout, FontMetrics small)
	{
		if (readout != measuredFor || !small.getFont().equals(measuredFont))
		{
			measured = new Measured(sessionCellWidths(small, readout), width(small, readout.getGearText()),
				width(small, readout.getXpText()), inventoryWidth(small, readout));
			measuredFor = readout;
			measuredFont = small.getFont();
		}
		return measured;
	}

	/**
	 * The inventory line's content: the label at its widest digits, a gap,
	 * and the catch icons. The icons are drawn from the right edge, so this
	 * space is theirs whatever the count: at some counts the label used to
	 * run into the first icon (Board's screenshots, 2026-11-06: "Inv 12/28
	 * free", "14/28", "0/28").
	 */
	private int inventoryWidth(FontMetrics metrics, SkillingReadout readout)
	{
		final String label = readout.getInventoryLabel();
		final int labelWidth = label == null ? 0 : InventoryLine.reservedWidth(label, metrics::charWidth,
			metrics.stringWidth(label));
		final List<FishingCatches.Catch> catches = readout.getCatches();
		final int gap = label != null && !catches.isEmpty() ? InventoryLine.LABEL_GAP : 0;
		return labelWidth + gap + catchesWidth(catches, metrics);
	}

	/** Each session cell's own width, the count's icon and the column padding included. */
	private int[] sessionCellWidths(FontMetrics metrics, SkillingReadout readout)
	{
		final List<SessionRow.Cell> cells = readout.getSessionCells();
		final int[] widths = new int[cells.size()];
		for (int i = 0; i < widths.length; i++)
		{
			final SessionRow.Cell c = cells.get(i);
			final int icon = c.getKind() == SessionRow.Kind.COUNT
				? sessionIconWidth(skillIconManager.getSkillImage(readout.getSkill(), true)) : 0;
			widths[i] = icon + metrics.stringWidth(c.getText()) + PAD_X * 2;
		}
		return widths;
	}

	/** A session icon {@code width} by {@link #SESSION_ICON} at (x, top), on the same {@link #ICON_BACKING} for every skill. */
	static void drawSessionIcon(Graphics2D graphics, BufferedImage icon, int x, int top, int width)
	{
		graphics.setColor(ICON_BACKING);
		graphics.fillRoundRect(x - 1, top - 1, width + 2, SESSION_ICON + 2, 4, 4);
		graphics.drawImage(icon, x, top, width, SESSION_ICON, null);
	}

	/** The count's skill icon at {@link #SESSION_ICON} high with the gap after it, or 0 without one. */
	private static int sessionIconWidth(BufferedImage icon)
	{
		return icon == null || icon.getHeight() <= 0 ? 0 : icon.getWidth() * SESSION_ICON / icon.getHeight() + ICON_GAP;
	}

	/** The header's words: the level and boost while working, "Not fishing" once stopped. */
	private static String headerText(SkillingReadout readout)
	{
		if (readout.isIdle())
		{
			return SkillingText.idleHeader(readout.getSkill());
		}

		final int seconds = SkillingText.seconds(readout.getTicksUntilDrop(),
			System.currentTimeMillis() - readout.getTickMillis());
		return SkillingText.text(readout.getSkill().getName(), readout.getReal(), readout.getBoosted(), seconds,
			!readout.isTimerConfirmed(), readout.getSpecPercent(), readout.getSource(), readout.getWarning());
	}

	/**
	 * The top row: filled behind white text in the Bar style, the text itself
	 * in the colour otherwise. The colour is the skill's; the low colour for a
	 * moment after a boost drop; the idle colour once you stop. The fill is the
	 * boost time left while boosted, full otherwise.
	 */
	private void drawHeader(Graphics2D graphics, Rectangle head, SkillingReadout readout, String text,
		BufferedImage icon)
	{
		final boolean warning = readout.getGearText() != null || readout.getWarning() != SkillingState.Warning.NONE;
		final Color colour = headerColour(readout, warning);
		final boolean bar = config.overheadStyle() == OverheadStyle.BAR;
		if (bar)
		{
			Bars.across(graphics, head, warning ? 1.0 : boostFraction(readout), colour, config.barBackground());
		}

		final FontMetrics metrics = graphics.getFontMetrics();
		final int iconWidth = icon == null ? 0 : icon.getWidth() + ICON_GAP;
		final int x = head.x + (head.width - iconWidth - metrics.stringWidth(text)) / 2;
		if (icon != null)
		{
			graphics.drawImage(icon, x, head.y + (head.height - icon.getHeight()) / 2, null);
		}

		OverlayUtil.renderTextLocation(graphics, new Point(x + iconWidth, textBaseline(head, metrics)), text,
			bar ? Color.WHITE : colour);
	}

	/** Missing gear is red even on an idle badge; otherwise idle, then a boost warning, then the skill. */
	private Color headerColour(SkillingReadout readout, boolean warning)
	{
		if (readout.getGearText() != null)
		{
			return config.healthLowColour();
		}
		if (readout.isIdle())
		{
			return config.skillingIdleColour();
		}
		return warning ? config.healthLowColour() : readout.getColour();
	}

	private static double boostFraction(SkillingReadout readout)
	{
		if (readout.isIdle() || !readout.isBoosted() || readout.getTicksUntilDrop() < 0 || readout.getCycleLength() <= 0)
		{
			return 1.0;
		}
		return (double) readout.getTicksUntilDrop() / readout.getCycleLength();
	}

	/**
	 * The inventory label on a bar filled as the inventory fills, green while
	 * empty to red when full: the health colours run backwards. Then every
	 * fish the spot's method can give. Either half can be off.
	 */
	private void drawInventoryLine(Graphics2D graphics, Rectangle row, SkillingReadout readout)
	{
		final String label = readout.getInventoryLabel();
		final double fill = label == null ? 0 : readout.getInventoryFill();
		Bars.across(graphics, row, fill,
			InventoryFill.colour(fill, config.healthFullColour(), config.healthMidColour(), config.healthLowColour()),
			config.barBackground());

		final FontMetrics metrics = graphics.getFontMetrics();
		final int baseline = textBaseline(row, metrics);
		if (label != null)
		{
			OverlayUtil.renderTextLocation(graphics, new Point(row.x + PAD_X, baseline), label, Color.WHITE);
		}

		// From the right edge, in the space measured for them, never after
		// the label's drawn end.
		final List<FishingCatches.Catch> catches = readout.getCatches();
		int x = row.x + row.width - PAD_X - catchesWidth(catches, metrics);
		final int iconTop = row.y + (row.height - FISH_ICON) / 2;
		for (FishingCatches.Catch c : catches)
		{
			x += ICON_GAP;
			x += drawCatch(graphics, c, readout, x, iconTop, baseline, metrics);
		}
	}

	/**
	 * A fish you can catch at full strength; one you cannot yet dimmed, with
	 * "Lv 15" over it in red and "Needs Fishing 15" on hover.
	 *
	 * @return the width the catch took
	 */
	private int drawCatch(Graphics2D graphics, FishingCatches.Catch c, SkillingReadout readout, int x, int top,
		int baseline, FontMetrics metrics)
	{
		final BufferedImage image = itemManager.getImage(c.getFish().getItemId());
		final int width = catchWidth(c, image, metrics);
		final int iconWidth = scaledWidth(image);
		final int iconX = x + (width - iconWidth) / 2;
		if (c.isCatchable())
		{
			graphics.drawImage(image, iconX, top, iconWidth, FISH_ICON, null);
			return width;
		}

		final Composite composite = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, LOCKED_FISH_ALPHA));
		graphics.drawImage(image, iconX, top, iconWidth, FISH_ICON, null);
		graphics.setComposite(composite);

		final int level = c.getFish().getLevel();
		final String label = SkillingText.lockedLabel(level);
		OverlayUtil.renderTextLocation(graphics,
			new Point(x + (width - metrics.stringWidth(label)) / 2, baseline), label, SkillingText.LOCKED_LEVEL);

		if (hovered(graphics, new Rectangle(x, top, width, FISH_ICON)))
		{
			tooltipManager.add(new Tooltip(SkillingText.lockedTooltip(readout.getSkill().getName(), level)));
		}
		return width;
	}

	/** The mouse is over this box, drawn under the current translate and scale. */
	private boolean hovered(Graphics2D graphics, Rectangle box)
	{
		final Point mouse = client.getMouseCanvasPosition();
		return mouse != null && graphics.getTransform().createTransformedShape(box).contains(mouse.getX(), mouse.getY());
	}

	/** Every catch icon with the gap before it, as {@link #drawInventoryLine} lays them out. */
	private int catchesWidth(List<FishingCatches.Catch> catches, FontMetrics metrics)
	{
		int width = 0;
		for (FishingCatches.Catch c : catches)
		{
			width += ICON_GAP + catchWidth(c, itemManager.getImage(c.getFish().getItemId()), metrics);
		}
		return width;
	}

	/** The icon, or the level written over a locked one if that is wider. */
	private static int catchWidth(FishingCatches.Catch c, BufferedImage image, FontMetrics metrics)
	{
		final int icon = scaledWidth(image);
		return c.isCatchable() ? icon
			: Math.max(icon, metrics.stringWidth(SkillingText.lockedLabel(c.getFish().getLevel())));
	}

	/** An item icon's width at {@link #FISH_ICON} high, keeping its shape. */
	private static int scaledWidth(BufferedImage image)
	{
		return image == null || image.getHeight() <= 0 ? FISH_ICON : image.getWidth() * FISH_ICON / image.getHeight();
	}

	private static void centredText(Graphics2D graphics, Rectangle row, String text)
	{
		final FontMetrics metrics = graphics.getFontMetrics();
		OverlayUtil.renderTextLocation(graphics,
			new Point(row.x + (row.width - metrics.stringWidth(text)) / 2, textBaseline(row, metrics)),
			text, Color.WHITE);
	}

	/** Text vertically centred in a row. */
	private static int textBaseline(Rectangle row, FontMetrics metrics)
	{
		return row.y + (row.height - metrics.getAscent() - metrics.getDescent()) / 2 + metrics.getAscent();
	}

	private static int width(FontMetrics metrics, String text)
	{
		return text == null ? 0 : metrics.stringWidth(text);
	}

	private static int max(int a, int b, int c, int d)
	{
		return Math.max(Math.max(a, b), Math.max(c, d));
	}

	/** One readout's small-row widths, as {@link #measure} keeps them between ticks. */
	private static final class Measured
	{
		private final int[] cells;
		private final int gear;
		private final int xp;
		private final int inv;

		Measured(int[] cells, int gear, int xp, int inv)
		{
			this.cells = cells;
			this.gear = gear;
			this.xp = xp;
			this.inv = inv;
		}
	}

	/**
	 * One frame's badge: the header's words and icon, each row's box or null
	 * when it is off, and the session row's lines, top first.
	 */
	private static final class Layout
	{
		private final String text;
		private final BufferedImage icon;
		private final int[] cellWidths;
		private final int[][] sessionLines;
		private final Rectangle[] session;
		private Rectangle head;
		private Rectangle gear;
		private Rectangle xp;
		private Rectangle inv;
		private Rectangle box;

		Layout(String text, BufferedImage icon, int[] cellWidths, int[][] sessionLines)
		{
			this.text = text;
			this.icon = icon;
			this.cellWidths = cellWidths;
			this.sessionLines = sessionLines;
			this.session = new Rectangle[sessionLines.length];
		}
	}

	/** Rows stacked upward from the origin, each the badge's full width, with a gap between. */
	private static final class Rows
	{
		private final int left;
		private final int width;
		private int top;
		private boolean any;

		Rows(int left, int width)
		{
			this.left = left;
			this.width = width;
		}

		/** @return the row's box, or null when it is off */
		Rectangle add(boolean on, int height)
		{
			if (!on)
			{
				return null;
			}
			final int bottom = any ? top - ROW_GAP : 0;
			final Rectangle row = new Rectangle(left, bottom - height, width, height);
			top = row.y;
			any = true;
			return row;
		}

		boolean empty()
		{
			return !any;
		}

		Rectangle box()
		{
			return new Rectangle(left, top, width, -top);
		}
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Getter;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

/**
 * Immutable snapshot of everything the skilling badge needs for one tick.
 *
 * Every row's text that can be built once per tick is built here, by the
 * plugin, so the overlays only lay it out. The header is the exception: its
 * boost timer counts down between ticks.
 *
 * The badge is drawn over the local player unless the position setting
 * asks for the spot; the spot fields say where that is.
 */
@Getter
@Builder
final class SkillingReadout
{
	private final Skill skill;
	private final int real;
	private final int boosted;

	/** The skill's colour, the user's override or the palette ({@link SkillColours}). */
	private final Color colour;

	/** The activity has stopped and the header says "Not fishing" ({@link IdleBadge}). */
	private final boolean idle;

	/** The top row is on. */
	private final boolean header;

	/** Ticks until the boost drops by one, or -1 while the cycle phase is unknown. */
	@Builder.Default
	private final int ticksUntilDrop = -1;

	/** Length of the drain cycle in force, for drawing the bar. */
	private final int cycleLength;

	/** The timer is anchored on an observed drop rather than on login. */
	private final boolean timerConfirmed;

	/** Remaining special attack energy, or -1 when no spec tool is wielded. */
	@Builder.Default
	private final int specPercent = -1;

	private final String source;

	@Builder.Default
	private final SkillingState.Warning warning = SkillingState.Warning.NONE;

	/**
	 * "Needs: Fishing rod + bait" after clicking a fishing option without
	 * what it takes ({@link FishingGear}), or null. Turns the header red.
	 */
	private final String gearText;

	/** Progress through the current level, from the skill's XP. */
	private final XpProgress xp;

	/** The XP row's text, or null with the row off. */
	private final String xpText;

	/** The session row's columns ({@link SessionRow#cells}), empty with it off. */
	@Builder.Default
	private final List<SessionRow.Cell> sessionCells = Collections.emptyList();

	/**
	 * Every fish the clicked method can give, the catchable ones first
	 * ({@link FishingCatches#options}). Empty for an unknown spot or method,
	 * with the catch icons off, and for every skill but fishing.
	 */
	@Builder.Default
	private final List<FishingCatches.Catch> catches = Collections.emptyList();

	/** Wall clock of the tick this was built on, for counting down between ticks. */
	private final long tickMillis;

	/** How full the inventory is, 0 to 1 ({@link InventoryFill}), or -1 when the line is off or unknown. */
	@Builder.Default
	private final double inventoryFill = -1;

	/** "Inv 26/28 free", or null when the line is off or the inventory unread. */
	private final String inventoryLabel;

	/** Empty slots, for the inventory pillar's number, or -1 when the line is off or unread. */
	@Builder.Default
	private final int inventoryFree = -1;

	/** The fishing spot or other NPC being worked, or null. */
	private final NPC spotNpc;

	/** The south-west tile of the tree, rock or stall being worked, or null. */
	private final WorldPoint spotTile;

	/** The object's larger side in tiles, for centring over it. */
	private final int spotSize;

	/**
	 * Pickpocketing: your own health is drawn above the badge rather than
	 * under it, for as long as you are at it, since the target can stun and
	 * hit you at any attempt.
	 */
	private final boolean healthAbove;

	boolean isBoosted()
	{
		return boosted > real;
	}

	/** The inventory line has something to show: the fill, the catch icons, or both. */
	boolean hasInventoryLine()
	{
		return inventoryLabel != null || !catches.isEmpty();
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Arrays;
import net.runelite.api.Skill;

/**
 * This session's count and rates per skill, for the badge's session row:
 * how many fish were caught, logs chopped or ores mined, and the XP and
 * actions per hour.
 *
 * Every experience gain is one action: a catch, a log, an ore, a
 * pickpocket. The first reading of a skill after login is its baseline,
 * never a gain. Rates run from the first gain, and that gain's own XP is
 * not counted toward them because it was earned before the clock started.
 *
 * Pure: XP totals and wall-clock milliseconds in, counts and rates out.
 */
final class SkillingSession
{
	/** Rates are not shown until the first gain is this old: two quick catches are not an hourly rate. */
	static final long MIN_RATE_MILLIS = 60_000;

	private static final long HOUR = 3_600_000;

	private final int[] lastXp = new int[Skill.values().length];
	private final int[] actions = new int[lastXp.length];
	private final long[] firstGain = new long[lastXp.length];
	private final long[] xpSinceFirst = new long[lastXp.length];

	SkillingSession()
	{
		clear();
	}

	void xp(Skill skill, int xp, long nowMillis)
	{
		final int i = skill.ordinal();
		final int previous = lastXp[i];
		lastXp[i] = xp;
		if (previous < 0 || xp <= previous)
		{
			return;
		}

		if (actions[i] == 0)
		{
			firstGain[i] = nowMillis;
		}
		else
		{
			xpSinceFirst[i] += xp - previous;
		}
		actions[i]++;
	}

	int actions(Skill skill)
	{
		return actions[skill.ordinal()];
	}

	/** Milliseconds since this session's first gain in the skill, or -1 before it. */
	long elapsed(Skill skill, long nowMillis)
	{
		final int i = skill.ordinal();
		return actions[i] == 0 ? -1 : Math.max(0, nowMillis - firstGain[i]);
	}

	/** XP per hour since the first gain, or -1 until {@link #MIN_RATE_MILLIS} has passed. */
	int xpPerHour(Skill skill, long nowMillis)
	{
		final int i = skill.ordinal();
		return perHour(xpSinceFirst[i], i, nowMillis);
	}

	/** Actions per hour since the first gain, or -1 until {@link #MIN_RATE_MILLIS} has passed. */
	int actionsPerHour(Skill skill, long nowMillis)
	{
		final int i = skill.ordinal();
		return perHour(actions[i] - 1, i, nowMillis);
	}

	private int perHour(long amount, int i, long nowMillis)
	{
		final long elapsed = nowMillis - firstGain[i];
		if (actions[i] == 0 || elapsed < MIN_RATE_MILLIS)
		{
			return -1;
		}
		return (int) (amount * HOUR / elapsed);
	}

	/** The reset option: counts start again, the XP baselines stay so no gain is invented. */
	void reset()
	{
		Arrays.fill(actions, 0);
		Arrays.fill(firstGain, 0);
		Arrays.fill(xpSinceFirst, 0);
	}

	/** Logout: everything goes, baselines included. */
	void clear()
	{
		Arrays.fill(lastXp, -1);
		reset();
	}
}

package com.vinnyvangogh.combatvitals;

import java.time.Duration;
import java.time.Instant;
import net.runelite.api.Skill;

/**
 * Decides whether the skilling badge is up, and what it can honestly say
 * about where a boost came from and what just happened to it.
 *
 * Engagement mirrors {@link CombatState}: working a skilling NPC or object
 * raises the badge, and it lingers for the timeout after the work stops
 * unless the game still has the player on it.
 *
 * The boost source is attributed from what was seen. A rise that follows a
 * Drink or Eat within a few ticks is likely that item, and labelled
 * "likely"; one that follows a special attack from a recognised tool is
 * that tool; anything else has no source.
 * Attribution is kept per skill, because the usual order is drink, then
 * click the spot, and the badge is not up yet when the boost lands.
 *
 * Pure: ticks and instants in, decisions out, no client. Not thread safe;
 * the plugin touches it from the client thread only.
 */
final class SkillingState
{
	/** How long after a Drink, Eat or special attack a rise is credited to it. */
	static final int ATTRIBUTION_TICKS = 3;

	/** How long the on-badge cue stays after a drop (3 s) and after expiry (about 5 s). */
	static final int DROP_CUE_TICKS = 5;
	static final int EXPIRY_CUE_TICKS = 8;

	enum Warning
	{
		NONE,
		DROPPED,
		EXPIRED
	}

	private boolean engaged;
	private Skill skill;
	private Instant interactionEnded;

	/** The menu option of the last NPC click, until an engagement takes it. */
	private String pendingClick;

	/** The option the current engagement was started with: Net, Bait, Harpoon... */
	private String method;

	/** Item id of the last fish landed, or -1. */
	private int lastCatch = -1;

	private final String[] sourceBySkill = new String[Skill.values().length];

	private String consumedItem;
	private int consumedTick = -1;

	private String specTool;
	private Skill specSkill;
	private int specTick = -1;

	private Skill warningSkill;
	private Warning lastWarning = Warning.NONE;
	private int warningTick = -1;

	/**
	 * The player clicked a menu option on an NPC. Remembered until the
	 * interaction it starts arrives, a tick later, so the badge knows which
	 * method the spot is being worked with.
	 */
	void clicked(String option)
	{
		pendingClick = option;
	}

	/**
	 * The player started interacting with an NPC that trains {@code skill}.
	 * A click just before this names the method; without one (the spot moved
	 * and the game re-engaged it) the method from the last click stands.
	 */
	void engage(Skill skill)
	{
		engaged = true;
		this.skill = skill;
		interactionEnded = null;
		if (pendingClick != null)
		{
			method = pendingClick;
			pendingClick = null;
		}
	}

	/** The player moved on to something that is not a skilling NPC: no linger. */
	void release()
	{
		engaged = false;
		skill = null;
		interactionEnded = null;
		pendingClick = null;
		method = null;
		lastCatch = -1;
	}

	/** The option the current engagement was clicked with, or null when none was seen. */
	String method()
	{
		return method;
	}

	/** A fish landed: from the catch message or the inventory. */
	void caught(int itemId)
	{
		lastCatch = itemId;
	}

	/** Item id of the last fish landed this engagement, or -1. */
	int lastCatch()
	{
		return lastCatch;
	}

	/** The player stopped interacting. The badge lingers until {@link #expire}. */
	void disengage(Instant now)
	{
		if (engaged && interactionEnded == null)
		{
			interactionEnded = now;
		}
	}

	/**
	 * Retires the badge once the interaction has been over for the timeout.
	 *
	 * @return true when the caller should drop its reference to the NPC
	 */
	boolean expire(Instant now, Duration timeout, boolean stillInteractingWithTarget)
	{
		if (!engaged || interactionEnded == null || stillInteractingWithTarget)
		{
			return false;
		}

		if (Duration.between(interactionEnded, now).compareTo(timeout) > 0)
		{
			engaged = false;
			skill = null;
			interactionEnded = null;
			method = null;
			lastCatch = -1;
			return true;
		}
		return false;
	}

	/** The badge should be up, and for this skill. Null when it should not. */
	Skill skill()
	{
		return engaged ? skill : null;
	}

	/** The player chose Drink or Eat on an item. */
	void consumed(String itemName, int tick)
	{
		consumedItem = itemName == null ? null : stripDoses(itemName);
		consumedTick = tick;
	}

	/**
	 * Special attack energy fell while a recognised skilling tool was wielded.
	 *
	 * @param toolName  the tool
	 * @param toolSkill the skill its special boosts; a rise in any other skill
	 *                  is not credited to it
	 */
	void specUsed(String toolName, Skill toolSkill, int tick)
	{
		specTool = toolName;
		specSkill = toolSkill;
		specTick = tick;
	}

	/**
	 * A boost event for any skill, from {@link BoostTracker}.
	 *
	 * @return the warning to raise, if the badge is up for this skill
	 */
	Warning boostChanged(Skill changed, BoostTracker.Change change, int tick)
	{
		final int idx = changed.ordinal();
		switch (change)
		{
			case RISE:
				sourceBySkill[idx] = attribute(changed, tick);
				return Warning.NONE;
			case DROP:
				return warn(changed, Warning.DROPPED, tick);
			case EXPIRED:
				sourceBySkill[idx] = null;
				return warn(changed, Warning.EXPIRED, tick);
			case NONE:
			default:
				return Warning.NONE;
		}
	}

	/** Where the current boost on the engaged skill came from, or null. */
	String source()
	{
		return skill == null ? null : sourceBySkill[skill.ordinal()];
	}

	/** The cue the badge should show now, if any. */
	Warning warning(int tick)
	{
		if (warningSkill == null || warningSkill != skill || lastWarning == Warning.NONE)
		{
			return Warning.NONE;
		}

		final int window = lastWarning == Warning.DROPPED ? DROP_CUE_TICKS : EXPIRY_CUE_TICKS;
		return tick - warningTick < window ? lastWarning : Warning.NONE;
	}

	void clear()
	{
		engaged = false;
		skill = null;
		interactionEnded = null;
		pendingClick = null;
		method = null;
		lastCatch = -1;
		java.util.Arrays.fill(sourceBySkill, null);
		consumedItem = null;
		consumedTick = -1;
		specTool = null;
		specSkill = null;
		specTick = -1;
		warningSkill = null;
		lastWarning = Warning.NONE;
		warningTick = -1;
	}

	private Warning warn(Skill changed, Warning warning, int tick)
	{
		warningSkill = changed;
		lastWarning = warning;
		warningTick = tick;
		return changed == skill() ? warning : Warning.NONE;
	}

	/** The most recent of a Drink/Eat or a special attack inside the window, else nothing. */
	private String attribute(Skill changed, int tick)
	{
		final boolean itemRecent = consumedItem != null && consumedTick != -1
			&& tick - consumedTick >= 0 && tick - consumedTick <= ATTRIBUTION_TICKS;
		final boolean specRecent = specTool != null && specSkill == changed && specTick != -1
			&& tick - specTick >= 0 && tick - specTick <= ATTRIBUTION_TICKS;

		if (itemRecent && (!specRecent || consumedTick >= specTick))
		{
			// Any Drink or Eat counts, so a rise after a stew is only a
			// correlation; the label says as much.
			return "likely " + consumedItem;
		}
		if (specRecent)
		{
			return specTool + " special";
		}
		return null;
	}

	/** "Fishing potion(3)" names the dose, which is not the source. */
	static String stripDoses(String itemName)
	{
		return itemName.replaceAll("\\s*\\(\\d+\\)$", "");
	}
}

package com.vinnyvangogh.combatvitals;

/**
 * Tells when the player has clearly stopped working a skilling NPC, so the
 * badge can switch to "Not fishing" within a tick or two instead of after the
 * whole linger (Board's in-game test, 2026-11-06: walking away took the
 * timeout, 5 s by default, about 8 ticks, before the badge changed).
 *
 * Read once per game tick, while a skilling NPC is held:
 * <ul>
 * <li>Still interacting with it, or a click on an NPC waiting for its
 * interaction to arrive: working. Nothing changes.</li>
 * <li>The interaction has ended and the player's tile changed: they walked
 * off. Stopped at once. Nobody moves while fishing, pickpocketing or
 * catching; walking up to the next spot starts with a click on it, which
 * counts as working until its interaction arrives.</li>
 * <li>Fishing only: the interaction has ended and the player has stood still
 * without animating for {@link #STILL_TICKS} ticks: the spot moved or the
 * inventory filled. Stopped. While fishing the game keeps the player on the
 * spot through every gap in the animation, so only a real end of the
 * interaction starts this count. Thieving and hunting are a click per
 * attempt, with the interaction ending between them, so they keep the
 * ordinary linger instead.</li>
 * </ul>
 *
 * Pure: booleans and packed tiles in, a decision out.
 */
final class SkillingStop
{
	/** Ticks standing still, not animating and not on the spot, before fishing counts as stopped. */
	static final int STILL_TICKS = 2;

	/** A tile not read yet. */
	static final long UNKNOWN = SpotPathing.UNKNOWN;

	private long lastTile = UNKNOWN;
	private int stillTicks;

	/**
	 * @param working    the player is still interacting with the NPC, or has
	 *                   just clicked an NPC whose interaction has not arrived
	 * @param tile       the player's tile, {@link SpotPathing#tile}, or {@link #UNKNOWN}
	 * @param animating  the player is animating
	 * @param fishing    the NPC is a fishing spot
	 * @return true when the work has clearly stopped
	 */
	boolean tick(boolean working, long tile, boolean animating, boolean fishing)
	{
		final boolean moved = lastTile != UNKNOWN && tile != UNKNOWN && tile != lastTile;
		lastTile = tile;
		if (working)
		{
			stillTicks = 0;
			return false;
		}
		if (moved)
		{
			return true;
		}
		if (!fishing || animating)
		{
			stillTicks = 0;
			return false;
		}
		return ++stillTicks >= STILL_TICKS;
	}

	/** A new engagement, or none: forget the last tile and the count. */
	void reset()
	{
		lastTile = UNKNOWN;
		stillTicks = 0;
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import java.util.Locale;
import net.runelite.api.Constants;
import net.runelite.api.Skill;

/**
 * Turns the skilling snapshot into the badge text.
 *
 * Pure: no client, no config object, no state, so the wording is unit
 * testable without a running game.
 */
final class SkillingText
{
	/**
	 * The level written over a fish you cannot catch yet. Red, and "Lv 15"
	 * rather than a bare "15", which read as a quantity (Board, 2026-11-04).
	 */
	static final Color LOCKED_LEVEL = new Color(255, 64, 64);

	private SkillingText()
	{
	}

	/** "Lv 15", over a dimmed fish. */
	static String lockedLabel(int level)
	{
		return "Lv " + level;
	}

	/** "Needs Fishing 15", the hover text on a dimmed fish. */
	static String lockedTooltip(String skillName, int level)
	{
		return "Needs " + skillName + " " + level;
	}

	/** "Not fishing": the header once you stop. */
	static String idleHeader(Skill skill)
	{
		return "Not " + activity(skill);
	}

	/** The activity's name in a sentence, "fishing", "hunting". */
	private static String activity(Skill skill)
	{
		switch (skill)
		{
			case HUNTER:
				return "hunting";
			case RUNECRAFT:
				return "runecrafting";
			default:
				return skill.getName().toLowerCase(Locale.ROOT);
		}
	}

	/**
	 * @param skillName   the skill, e.g. "Fishing"
	 * @param real        base level
	 * @param boosted     boosted level now
	 * @param seconds     seconds until the boost drops by one, or -1 when unknown
	 * @param estimated   the timer is anchored on login, not on an observed drop
	 * @param specPercent remaining special attack energy, or -1 when no spec tool is wielded
	 * @param source      where the boost came from, or null
	 * @param warning     the cue to show
	 * @return the text to draw
	 */
	static String text(String skillName, int real, int boosted, int seconds, boolean estimated,
		int specPercent, String source, SkillingState.Warning warning)
	{
		final StringBuilder text = new StringBuilder(skillName).append(' ').append(boosted);

		if (warning == SkillingState.Warning.EXPIRED)
		{
			text.append(" boost ended");
		}
		else if (boosted != real)
		{
			final int boost = boosted - real;
			text.append(" (").append(boost > 0 ? "+" : "").append(boost).append(')');

			if (warning == SkillingState.Warning.DROPPED)
			{
				text.append(" dropped");
			}
			else if (boost > 0 && seconds >= 0)
			{
				text.append(' ').append(estimated ? "~" : "").append(seconds).append('s');
			}
		}

		if (specPercent >= 0)
		{
			text.append(" | Spec ").append(specPercent).append('%');
		}

		if (source != null && boosted > real && warning != SkillingState.Warning.EXPIRED)
		{
			text.append(" | ").append(source);
		}

		return text.toString();
	}

	/**
	 * Seconds left, counted down between ticks so the number moves every
	 * second rather than every 0.6 s. Rounds up: a boost with 0.4 s left has
	 * not dropped yet.
	 *
	 * @param ticks        ticks until the drop
	 * @param msSinceTick  milliseconds since the last game tick
	 */
	static int seconds(int ticks, long msSinceTick)
	{
		if (ticks < 0)
		{
			return -1;
		}
		final long ms = ticks * (long) Constants.GAME_TICK_LENGTH - Math.max(0, msSinceTick);
		return (int) Math.max(0, (ms + 999) / 1000);
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Skill;

/**
 * Recognises the skilling tools whose special attack boosts a skill.
 *
 * Lumber Up (+3 Woodcutting), Rock Knocker (+3 Mining) and Fishstabber
 * (+3 Fishing) live on the dragon, infernal, crystal, 3rd age and event
 * variants of the axe, pickaxe and harpoon, all for 100% special attack
 * energy. Matching on the item name rather than a list of ids keeps the
 * ornamented and felling variants covered without maintaining every id.
 *
 * Source: OSRS wiki, "Special attack", skilling tools table.
 */
final class SkillingTools
{
	private static final Pattern SPEC_TOOL = Pattern.compile(
		"^(?:dragon|infernal|crystal|3rd age|trailblazer|echo) (?:felling )?(axe|pickaxe|harpoon)\\b");

	private SkillingTools()
	{
	}

	/**
	 * @param weaponName the equipped weapon's name, or null when nothing is wielded
	 * @return the skill the weapon's special attack boosts, or null when it has none
	 */
	static Skill specSkill(String weaponName)
	{
		if (weaponName == null)
		{
			return null;
		}

		final String name = weaponName.toLowerCase(Locale.ROOT);

		// An uncharged crystal tool cannot be used at all, let alone spec'd.
		if (name.contains("(inactive)") || name.contains("(uncharged)"))
		{
			return null;
		}

		final Matcher matcher = SPEC_TOOL.matcher(name);
		if (!matcher.find())
		{
			return null;
		}

		switch (matcher.group(1))
		{
			case "axe":
				return Skill.WOODCUTTING;
			case "pickaxe":
				return Skill.MINING;
			case "harpoon":
				return Skill.FISHING;
			default:
				return null;
		}
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.FishingSpot;

/**
 * When to find the next fishing spot, and what to do with it: send it to
 * Shortest Path, or highlight it when Shortest Path is not there.
 *
 * Requests (the spot moving, the badge's right-click) only mark a search as
 * due; the search itself runs once on the next game tick. A spot that moves
 * twice in one tick therefore sends one path, and a target that moves again
 * before the player gets there is searched for again, so the path always
 * points at the latest spot. Starting to fish clears what this sent, and
 * nothing else: a path the player set up themselves is never touched.
 *
 * Client thread only. The game is reached through {@link Router},
 * {@link Picker} and {@link Locator}, so the whole flow is testable without
 * a client.
 *
 * Whether the spot moved is decided here, from the spot being fished and
 * whether the player has clicked or walked elsewhere since, never from the
 * player's interaction at the moment of the despawn: the game clears that
 * around the same tick the spot moves (Board in-game test, 2026-11-04).
 */
@Slf4j
final class SpotPathing
{
	/** Shortest Path, or whatever stands in for it. */
	interface Router
	{
		/** Installed and switched on. */
		boolean available();

		/** @return whether the path went out */
		boolean route(NextFishingSpot.Spot spot);

		/** Clears the path this sent. */
		void clear();
	}

	/** Finds the next spot of this type, worked with this method, or null. */
	interface Picker
	{
		NextFishingSpot.Spot pick(FishingSpot type, String method);
	}

	/** Where a spot NPC stands now, as {@link #tile}, or {@link #UNKNOWN} when it is not loaded. */
	interface Locator
	{
		long tile(Object npc);
	}

	/** A spot NPC that is not loaded, or a tile not read yet. */
	static final long UNKNOWN = -1;

	/** One world tile as a single comparable value. */
	static long tile(int x, int y, int plane)
	{
		return ((long) plane << 40) | ((long) (x & 0xFFFFF) << 20) | (y & 0xFFFFF);
	}

	/**
	 * Game ticks the fished spot is still "ours" after the interaction with it
	 * ends. The game clears the interaction around the tick the spot moves, in
	 * either order, so the despawn can land just after it.
	 */
	static final int GRACE_TICKS = 2;

	private final Supplier<FishingSpotPath> mode;
	private final Router router;

	/** The spot type and method last fished; null before any fishing. */
	private FishingSpot type;
	private String method;

	/**
	 * The spot NPC being fished, until the player clicks or walks elsewhere,
	 * or {@link #GRACE_TICKS} after the interaction with it ended. Its
	 * showing on another tile, despawning or turning into another spot is the
	 * spot moving.
	 */
	private Object fished;

	/** Where {@link #fished} stood on the last tick it was read; {@link #UNKNOWN} until then. */
	private long fishedTile = UNKNOWN;

	/** Ticks left of {@link #fished} once the interaction ended; -1 while still on it. */
	private int graceLeft = -1;

	private boolean due;

	/** The spot pathed to or highlighted, until the player fishes again. */
	private NextFishingSpot.Spot target;

	/** Whether {@link #target} went to Shortest Path, so there is a path of ours to clear. */
	private boolean routed;

	SpotPathing(Supplier<FishingSpotPath> mode, Router router)
	{
		this.mode = mode;
		this.router = router;
	}

	/** The player started fishing a spot: any path of ours is done with. */
	void fishingOn(FishingSpot type, String method, Object spot)
	{
		clearTarget();
		due = false;
		this.type = type;
		this.method = method;
		fished = spot;
		fishedTile = UNKNOWN;
		graceLeft = -1;
	}

	/** The player stopped interacting; the fished spot stays ours for {@link #GRACE_TICKS}. */
	void interactionEnded()
	{
		if (fished != null && graceLeft < 0)
		{
			graceLeft = GRACE_TICKS;
		}
	}

	/**
	 * The player clicked an NPC, an object or a tile, or turned to an NPC.
	 * Anything but the spot being fished means they left it, so it going is
	 * not it moving.
	 *
	 * @param npc the NPC clicked or turned to; null for a tile or object
	 */
	void turnedTo(Object npc)
	{
		if (npc != fished)
		{
			fished = null;
		}
	}

	/** The spot being fished turned into something else in place. */
	void changed(Object npc)
	{
		if (npc != null && npc == fished)
		{
			fishedSpotMoved();
		}
	}

	/** The spot being fished moved. Each fished spot moves once. */
	private void fishedSpotMoved()
	{
		fished = null;
		if (mode.get() == FishingSpotPath.ON_SPOT_MOVE)
		{
			log.debug("Fishing spot moved: searching for the next {} spot", type);
			request();
		}
	}

	/** "Path to next spot" on the badge. */
	void requested()
	{
		if (mode.get() != FishingSpotPath.OFF)
		{
			log.debug("Path to next spot clicked: searching for the next {} spot", type);
			request();
		}
	}

	/**
	 * An NPC despawned. The spot being fished going is the spot moving; the
	 * spot being walked to going means finding the next one again.
	 */
	void despawned(Object npc)
	{
		if (npc == null)
		{
			return;
		}
		if (npc == fished)
		{
			fishedSpotMoved();
		}
		if (target != null && target.getNpc() == npc && mode.get() != FishingSpotPath.OFF)
		{
			log.debug("Next fishing spot moved before it was reached: searching again");
			request();
		}
	}

	/**
	 * Checks whether the spots moved, runs a due search, once, and ages the
	 * fished spot's grace. The tiles are read before the grace ages, so a
	 * spot seen on its new tile on the tick its grace runs out still counts.
	 */
	void tick(Picker picker, Locator locator)
	{
		watchFished(locator);
		watchTarget(locator);
		ageGrace();
		if (!due)
		{
			return;
		}
		due = false;

		final NextFishingSpot.Spot next = picker.pick(type, method);
		if (next == null)
		{
			log.debug("No next {} spot found for \"{}\" (instance, level or none known)", type, method);
			clearTarget();
			return;
		}
		log.debug("Picked {} spot at ({}, {}, {})", next.getType(), next.getX(), next.getY(), next.getPlane());

		if (router.available() && router.route(next))
		{
			log.debug("Sent next fishing spot to Shortest Path");
			target = next;
			routed = true;
			return;
		}

		// No Shortest Path (or switched off here): the plugin's own mark is all there is.
		log.debug("Shortest Path not available or not wanted: marking the spot only");
		clearTarget();
		target = next;
	}

	/**
	 * A spot moves by relocating: the same NPC shows on a new tile, without a
	 * despawn or an id change (the Board's in-game test, 2026-11-04; RuneLite's
	 * own FishingPlugin likewise keys spots by NPC index and resets a minnow
	 * spot when its world location changes). A tick it is not loaded is not
	 * a move; it is compared again once it is.
	 */
	private void watchFished(Locator locator)
	{
		if (fished == null)
		{
			return;
		}
		final long now = locator.tile(fished);
		if (now == UNKNOWN)
		{
			return;
		}
		if (fishedTile != UNKNOWN && now != fishedTile)
		{
			fishedSpotMoved();
			return;
		}
		fishedTile = now;
	}

	/** The spot being walked to relocating before it is reached means finding the next one again. */
	private void watchTarget(Locator locator)
	{
		final Object npc = target == null ? null : target.getNpc();
		if (npc == null || mode.get() == FishingSpotPath.OFF)
		{
			return;
		}
		final long now = locator.tile(npc);
		if (now != UNKNOWN && now != tile(target.getX(), target.getY(), target.getPlane()))
		{
			log.debug("Next fishing spot moved before it was reached: searching again");
			request();
		}
	}

	private void ageGrace()
	{
		if (graceLeft > 0 && --graceLeft == 0)
		{
			fished = null;
			graceLeft = -1;
		}
	}

	/** Logged out, hopped or shut down: clears our path and forgets the spot. */
	void reset()
	{
		clearTarget();
		due = false;
		type = null;
		method = null;
		fished = null;
		fishedTile = UNKNOWN;
		graceLeft = -1;
	}

	/** The spot NPC to highlight, when there is one and no path went out for it. */
	Object highlighted()
	{
		return target == null || routed ? null : target.getNpc();
	}

	NextFishingSpot.Spot target()
	{
		return target;
	}

	private void request()
	{
		if (type != null)
		{
			due = true;
		}
	}

	private void clearTarget()
	{
		if (routed)
		{
			router.clear();
		}
		routed = false;
		target = null;
	}
}

