package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Bosses and high-HP NPCs can show a different display from everything else
 * (group member feedback via the Board, 2026-11-04: "%hp on bosses only ...
 * hitpoints only for everything else").
 */
public class BigTargetsTest
{
	private static final int N = 200;

	@Test
	public void bossViaTheGamesHudIsBig()
	{
		assertTrue(BigTargets.isBoss(true, "Some new boss"));
		assertTrue(BigTargets.isBig(BigTargetRule.BOSSES, true, -1, N));
	}

	@Test
	public void bossViaTheBundledListIsBigWithoutTheHud()
	{
		assertTrue(BigTargets.isBoss(false, "Vorkath"));
		assertTrue(BigTargets.isBoss(false, "general graardor"));
		assertTrue(BigTargets.isBoss(false, "Kree'arra"));
		assertFalse(BigTargets.isBoss(false, "Rock Crab"));
		assertFalse(BigTargets.isBoss(false, null));
	}

	@Test
	public void thresholdIsInclusiveAtN()
	{
		assertFalse(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, false, N - 1, N));
		assertTrue(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, false, N, N));
		assertTrue(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, false, N + 1, N));
		assertFalse(BigTargets.isBig(BigTargetRule.HP_ONLY, false, N - 1, N));
		assertTrue(BigTargets.isBig(BigTargetRule.HP_ONLY, false, N, N));
		assertTrue(BigTargets.isBig(BigTargetRule.HP_ONLY, false, N + 1, N));
	}

	@Test
	public void unknownMaxHpFallsToEverythingElse()
	{
		assertFalse(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, false, -1, N));
		assertFalse(BigTargets.isBig(BigTargetRule.HP_ONLY, false, -1, N));
		assertFalse(BigTargets.isBig(BigTargetRule.HP_ONLY, false, 0, N));
	}

	@Test
	public void bossesOnlyIgnoresMaxHp()
	{
		assertFalse(BigTargets.isBig(BigTargetRule.BOSSES, false, 5000, N));
		assertTrue(BigTargets.isBig(BigTargetRule.BOSSES, true, 10, N));
	}

	@Test
	public void bossesAndHpTakesEither()
	{
		assertTrue(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, true, 10, N));
		assertTrue(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, false, 250, N));
		assertFalse(BigTargets.isBig(BigTargetRule.BOSSES_AND_HP, false, 10, N));
	}

	@Test
	public void hpOnlyIgnoresBossStatus()
	{
		assertFalse(BigTargets.isBig(BigTargetRule.HP_ONLY, true, 10, N));
		assertTrue(BigTargets.isBig(BigTargetRule.HP_ONLY, true, 250, N));
	}

	@Test
	public void sameAsDisplayKeepsTheMainSetting()
	{
		for (DisplayMode mode : DisplayMode.values())
		{
			assertEquals(mode, TargetDisplay.SAME.resolve(mode));
		}
		assertEquals(DisplayMode.PERCENTAGE, TargetDisplay.PERCENTAGE.resolve(DisplayMode.HITPOINTS));
		assertEquals(DisplayMode.HITPOINTS, TargetDisplay.HITPOINTS.resolve(DisplayMode.BOTH));
		assertEquals(DisplayMode.BOTH, TargetDisplay.BOTH.resolve(DisplayMode.PERCENTAGE));
	}

	@Test
	public void eachSideGetsItsOwnChoice()
	{
		assertEquals(DisplayMode.PERCENTAGE,
			BigTargets.mode(true, TargetDisplay.PERCENTAGE, TargetDisplay.HITPOINTS, DisplayMode.BOTH));
		assertEquals(DisplayMode.HITPOINTS,
			BigTargets.mode(false, TargetDisplay.PERCENTAGE, TargetDisplay.HITPOINTS, DisplayMode.BOTH));
	}

	@Test
	public void defaultsReproduceTodaysDisplayForAnExistingProfile()
	{
		final CombatVitalsConfig profile = new CombatVitalsConfig()
		{
		};
		assertEquals(TargetDisplay.SAME, profile.bigTargetDisplay());
		assertEquals(TargetDisplay.SAME, profile.otherTargetDisplay());
		assertEquals(BigTargetRule.BOSSES_AND_HP, profile.bigTargetRule());
		assertEquals(200, profile.bigTargetMaxHp());
		for (DisplayMode saved : DisplayMode.values())
		{
			for (boolean big : new boolean[]{true, false})
			{
				assertEquals(saved, BigTargets.mode(big, profile.bigTargetDisplay(), profile.otherTargetDisplay(), saved));
			}
		}
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * The drain cycle: 100 ticks, 150 with Preserve, anchored on login or on an
 * observed drop. The Preserve cases are the Boosts plugin's own model.
 */
public class BoostTimerTest
{
	@Test
	public void unknownUntilAnchored()
	{
		BoostTimer timer = new BoostTimer();
		assertFalse(timer.isKnown());
		assertEquals(-1, timer.ticksUntilDrop(500, false));
	}

	@Test
	public void loginAnchorsAnEstimate()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorLogin(1000);

		assertTrue(timer.isKnown());
		assertFalse("an estimate until a drop confirms it", timer.isConfirmed());
		assertEquals(100, timer.ticksUntilDrop(1000, false));
		assertEquals(60, timer.ticksUntilDrop(1040, false));
		assertEquals(BoostTimer.CYCLE, timer.cycleLength());
	}

	@Test
	public void anObservedDropConfirmsThePhase()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorLogin(1000);
		timer.anchorDrop(1030);

		assertTrue(timer.isConfirmed());
		assertEquals(100, timer.ticksUntilDrop(1030, false));
		assertEquals(1, timer.ticksUntilDrop(1129, false));
		assertEquals(0, timer.ticksUntilDrop(1130, false));
	}

	@Test
	public void rollingKeepsThePhaseWhenNothingWasBoosted()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorDrop(0);
		assertEquals(0, timer.ticksUntilDrop(100, false));

		timer.roll(100);
		assertTrue("confidence survives a roll", timer.isConfirmed());
		assertEquals(100, timer.ticksUntilDrop(100, false));
		assertEquals(50, timer.ticksUntilDrop(150, false));
	}

	@Test
	public void rollingDoesNothingWhileUnknown()
	{
		BoostTimer timer = new BoostTimer();
		timer.roll(100);
		assertFalse(timer.isKnown());
	}

	@Test
	public void preserveStretchesTheCycleToNinetySeconds()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorDrop(0);

		// Preserve on from the start: the cycle is 150 ticks throughout.
		assertEquals(150, timer.ticksUntilDrop(0, true));
		assertEquals(80, timer.ticksUntilDrop(70, true));
		assertEquals(BoostTimer.PRESERVE_CYCLE, timer.cycleLength());
		assertEquals(10, timer.ticksUntilDrop(140, true));
	}

	@Test
	public void preserveSwitchedOnLateDoesNotHelpThisCycle()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorDrop(0);

		assertEquals(20, timer.ticksUntilDrop(80, false));
		// Switched on inside the final quarter, after tick 75: too late.
		assertEquals(15, timer.ticksUntilDrop(85, true));
	}

	@Test
	public void preserveSwitchedOffInsideTheFinalQuarterLosesTheExtension()
	{
		// The Boosts plugin's model: Preserve has to stay on through the final
		// quarter (ticks 75 to 100) to earn the extra 50 ticks.
		BoostTimer timer = new BoostTimer();
		timer.anchorDrop(0);

		assertEquals(80, timer.ticksUntilDrop(70, true));
		assertEquals(70, timer.ticksUntilDrop(80, true));
		assertEquals("off at 90: back to the 100 tick cycle", 10, timer.ticksUntilDrop(90, false));
	}

	@Test
	public void preserveHeldThroughTheFinalQuarterKeepsTheExtension()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorDrop(0);

		// On before the final quarter starts, and kept on through it.
		assertEquals(80, timer.ticksUntilDrop(70, true));
		assertEquals(70, timer.ticksUntilDrop(80, true));
		assertEquals(50, timer.ticksUntilDrop(100, true));
		// Off after the quarter is complete: the 150 tick cycle stands.
		assertEquals(40, timer.ticksUntilDrop(110, true));
		assertEquals(BoostTimer.PRESERVE_CYCLE, timer.cycleLength());
	}

	@Test
	public void clearForgetsThePhase()
	{
		BoostTimer timer = new BoostTimer();
		timer.anchorDrop(0);
		timer.clear();

		assertFalse(timer.isKnown());
		assertFalse(timer.isConfirmed());
		assertEquals(-1, timer.ticksUntilDrop(10, false));
	}

	@Test
	public void combatStatsRunOnTheOtherTimer()
	{
		assertTrue(BoostTimer.onSkillingTimer(Skill.FISHING));
		assertTrue(BoostTimer.onSkillingTimer(Skill.WOODCUTTING));
		assertTrue(BoostTimer.onSkillingTimer(Skill.THIEVING));
		assertFalse(BoostTimer.onSkillingTimer(Skill.ATTACK));
		assertFalse(BoostTimer.onSkillingTimer(Skill.HITPOINTS));
		assertFalse(BoostTimer.onSkillingTimer(Skill.PRAYER));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

public class BoostTrackerTest
{
	@Test
	public void firstUpdateOnlySeeds()
	{
		BoostTracker tracker = new BoostTracker();
		assertFalse(tracker.isSeeded(Skill.FISHING));

		assertEquals(BoostTracker.Change.NONE, tracker.observe(Skill.FISHING, 76, 79));
		assertTrue(tracker.isSeeded(Skill.FISHING));
	}

	@Test
	public void drinkingAPotionIsARise()
	{
		BoostTracker tracker = new BoostTracker();
		tracker.seed(Skill.FISHING, 76);

		assertEquals(BoostTracker.Change.RISE, tracker.observe(Skill.FISHING, 76, 79));
	}

	@Test
	public void theTimerDroppingOneIsADrop()
	{
		BoostTracker tracker = new BoostTracker();
		tracker.seed(Skill.FISHING, 79);

		assertEquals(BoostTracker.Change.DROP, tracker.observe(Skill.FISHING, 76, 78));
		assertEquals(BoostTracker.Change.DROP, tracker.observe(Skill.FISHING, 76, 77));
		assertEquals("the last drop reaches base", BoostTracker.Change.EXPIRED,
			tracker.observe(Skill.FISHING, 76, 76));
	}

	@Test
	public void noChangeIsNothing()
	{
		BoostTracker tracker = new BoostTracker();
		tracker.seed(Skill.FISHING, 79);

		assertEquals(BoostTracker.Change.NONE, tracker.observe(Skill.FISHING, 76, 79));
	}

	@Test
	public void aFallBelowBaseIsNotTheDrainTimer()
	{
		BoostTracker tracker = new BoostTracker();
		tracker.seed(Skill.FISHING, 76);

		assertEquals("drained by something", BoostTracker.Change.NONE,
			tracker.observe(Skill.FISHING, 76, 75));
		assertEquals("restoring up from below base is not a boost", BoostTracker.Change.NONE,
			tracker.observe(Skill.FISHING, 76, 76));
	}

	@Test
	public void aLargerFallIsNotTheDrainTimer()
	{
		// A world hop to free-to-play resets a boost in one step.
		BoostTracker tracker = new BoostTracker();
		tracker.seed(Skill.FISHING, 79);

		assertEquals(BoostTracker.Change.NONE, tracker.observe(Skill.FISHING, 76, 76));
	}

	@Test
	public void clearForgetsTheLevels()
	{
		BoostTracker tracker = new BoostTracker();
		tracker.seed(Skill.FISHING, 79);
		tracker.clear();

		assertFalse(tracker.isSeeded(Skill.FISHING));
		assertEquals(BoostTracker.Change.NONE, tracker.observe(Skill.FISHING, 76, 78));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.time.Duration;
import java.time.Instant;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import org.junit.Test;

/**
 * The four scenarios from the bug report, plus the attackability rule they
 * rest on. Pure: instants and booleans in, decisions out, no client.
 */
public class CombatStateTest
{
	private static final Duration TIMEOUT = Duration.ofSeconds(5);
	private static final Instant T0 = Instant.parse("2026-11-02T12:00:00Z");

	/** A fishing spot's menu options: Net, Bait, nothing else. Combat level -1. */
	private static final String[] FISHING_SPOT = {"Net", "Bait", null, null, null};

	/** A goblin: Attack, Talk-to. Combat level 2. */
	private static final String[] GOBLIN = {"Attack", null, "Talk-to", null, null};

	private static final String[] BANKER = {"Bank", "Talk-to", "Collect", null, null};

	@Test
	public void fishingSpotIsNotAttackable()
	{
		assertFalse(CombatState.attackable(FISHING_SPOT, -1));
	}

	@Test
	public void bankerIsNotAttackable()
	{
		assertFalse(CombatState.attackable(BANKER, -1));
	}

	@Test
	public void goblinIsAttackable()
	{
		assertTrue(CombatState.attackable(GOBLIN, 2));
	}

	@Test
	public void attackOptionAloneMakesAnNpcAttackable()
	{
		// Some attackable NPCs carry no combat level; the menu option still decides.
		assertTrue(CombatState.attackable(GOBLIN, -1));
	}

	@Test
	public void combatLevelAloneMakesAnNpcAttackable()
	{
		// A transformed or scripted NPC may hide Attack behind a different slot
		// or casing; a combat level is still proof it can be fought.
		assertTrue(CombatState.attackable(new String[] {null, null, null, null, null}, 50));
		assertTrue(CombatState.attackable(new String[] {"attack", null, null, null, null}, -1));
	}

	@Test
	public void nullActionsAreNotAttackable()
	{
		assertFalse(CombatState.attackable(null, -1));
		assertFalse(CombatState.attackable(null, 0));
	}

	@Test
	public void fishingSpotInteractionShowsNothing()
	{
		CombatState state = new CombatState();
		state.engage(CombatState.attackable(FISHING_SPOT, -1));

		assertFalse("no opponent readout for a skilling NPC", state.showTarget());
		assertFalse("no self bar for a skilling NPC", state.inCombat(T0, TIMEOUT));
		assertFalse("still nothing a few ticks later", state.inCombat(T0.plusSeconds(3), TIMEOUT));
	}

	@Test
	public void attackingAGoblinShowsTheBar()
	{
		CombatState state = new CombatState();
		state.engage(CombatState.attackable(GOBLIN, 2));

		assertTrue(state.showTarget());
		assertTrue(state.inCombat(T0, TIMEOUT));
	}

	@Test
	public void beingAttackedWhileSkillingShowsTheSelfBarOnly()
	{
		CombatState state = new CombatState();
		state.engage(CombatState.attackable(FISHING_SPOT, -1));
		state.hit(false, T0.plusSeconds(1));

		assertTrue("a hit on me is combat", state.inCombat(T0.plusSeconds(1), TIMEOUT));
		assertFalse("the fishing spot is still not an opponent", state.showTarget());
	}

	@Test
	public void beingAttackedWithNoTargetShowsTheSelfBar()
	{
		CombatState state = new CombatState();
		state.hit(false, T0);

		assertTrue(state.inCombat(T0.plusSeconds(4), TIMEOUT));
		assertFalse(state.showTarget());
	}

	@Test
	public void hitEvidenceExpiresAfterTheTimeout()
	{
		CombatState state = new CombatState();
		state.hit(false, T0);

		assertTrue(state.inCombat(T0.plus(TIMEOUT), TIMEOUT));
		assertFalse(state.inCombat(T0.plus(TIMEOUT).plusMillis(1), TIMEOUT));
	}

	@Test
	public void myHitOnTheTargetProvesItIsAttackable()
	{
		// Composition said no, but my damage landed on it: the evidence wins.
		CombatState state = new CombatState();
		state.engage(false);
		state.hit(true, T0.plusSeconds(1));

		assertTrue(state.showTarget());
	}

	@Test
	public void barExpiresAfterOpponentTimeout()
	{
		CombatState state = new CombatState();
		state.engage(true);
		state.disengage(T0.plusSeconds(1));

		Instant beforeTimeout = T0.plusSeconds(1).plus(TIMEOUT);
		assertFalse("not yet", state.expire(beforeTimeout, TIMEOUT, false));
		assertTrue("readout lingers until the timeout", state.showTarget());
		assertTrue(state.inCombat(beforeTimeout, TIMEOUT));

		Instant afterTimeout = beforeTimeout.plusMillis(1);
		assertTrue("the caller must drop the actor", state.expire(afterTimeout, TIMEOUT, false));
		assertFalse(state.showTarget());
		assertFalse(state.inCombat(afterTimeout, TIMEOUT));
	}

	@Test
	public void expiryWaitsWhileStillInteractingWithTheTarget()
	{
		CombatState state = new CombatState();
		state.engage(true);
		state.disengage(T0);

		Instant late = T0.plus(TIMEOUT).plusSeconds(10);
		assertFalse("the game still has us on the target", state.expire(late, TIMEOUT, true));
		assertTrue(state.showTarget());
	}

	@Test
	public void expiryDoesNotWaitForAnUnrelatedInteraction()
	{
		// The original bug: any interaction, a fishing spot included, kept the
		// old opponent alive. Only interacting with the target itself counts,
		// and that is the caller's comparison, so here it is simply false.
		CombatState state = new CombatState();
		state.engage(true);
		state.disengage(T0);

		assertTrue(state.expire(T0.plus(TIMEOUT).plusMillis(1), TIMEOUT, false));
		assertFalse(state.showTarget());
	}

	@Test
	public void reEngagingCancelsAPendingExpiry()
	{
		CombatState state = new CombatState();
		state.engage(true);
		state.disengage(T0);
		state.engage(true);

		assertFalse(state.expire(T0.plusSeconds(60), TIMEOUT, false));
		assertTrue(state.showTarget());
	}

	@Test
	public void switchingToAFishingSpotDropsTheOpponentReadout()
	{
		CombatState state = new CombatState();
		state.engage(true);
		state.engage(false);

		assertFalse(state.showTarget());
		assertFalse(state.inCombat(T0.plusSeconds(1), TIMEOUT));
	}

	@Test
	public void clearForgetsEverything()
	{
		CombatState state = new CombatState();
		state.engage(true);
		state.hit(true, T0);
		state.clear();

		assertFalse(state.showTarget());
		assertFalse(state.inCombat(T0, TIMEOUT));
		assertFalse(state.expire(T0.plusSeconds(60), TIMEOUT, false));
	}

	@Test
	public void damageAndBlocksAreCombatEvidence()
	{
		assertTrue("hit on me", CombatState.evidence(true, hitsplat(HitsplatID.DAMAGE_ME)));
		assertTrue("hit on me, typed as others", CombatState.evidence(true, hitsplat(HitsplatID.DAMAGE_OTHER)));
		assertTrue("blocked hit on me", CombatState.evidence(true, hitsplat(HitsplatID.BLOCK_OTHER)));
		assertTrue("max hit on me", CombatState.evidence(true, hitsplat(HitsplatID.DAMAGE_MAX_ME)));
		assertTrue("my hit on anyone", CombatState.evidence(false, hitsplat(HitsplatID.DAMAGE_ME)));
		assertTrue("my splash on anyone", CombatState.evidence(false, hitsplat(HitsplatID.BLOCK_ME)));
	}

	@Test
	public void poisonAndHealingOnMeAreNotCombat()
	{
		// Poison ticking while fishing must not pop the bar.
		assertFalse(CombatState.evidence(true, hitsplat(HitsplatID.POISON)));
		assertFalse(CombatState.evidence(true, hitsplat(HitsplatID.VENOM)));
		assertFalse(CombatState.evidence(true, hitsplat(HitsplatID.DISEASE)));
		assertFalse(CombatState.evidence(true, hitsplat(HitsplatID.HEAL)));
		assertFalse(CombatState.evidence(true, hitsplat(HitsplatID.PRAYER_DRAIN)));
	}

	@Test
	public void bystandersHittingEachOtherAreNotCombat()
	{
		assertFalse(CombatState.evidence(false, hitsplat(HitsplatID.DAMAGE_OTHER)));
		assertFalse(CombatState.evidence(false, hitsplat(HitsplatID.BLOCK_OTHER)));
		assertFalse(CombatState.evidence(false, hitsplat(HitsplatID.POISON)));
	}

	/** Only the type matters; {@code isMine()} and {@code isOthers()} derive from it. */
	private static Hitsplat hitsplat(int type)
	{
		return new Hitsplat()
		{
			@Override
			public int getHitsplatType()
			{
				return type;
			}

			@Override
			public int getAmount()
			{
				return 1;
			}

			@Override
			public int getDisappearsOnGameCycle()
			{
				return 0;
			}
		};
	}
}

