		// Null is what FishingSpot.findSpot returns for an NPC id it does not
		// know, and a known spot type this table has no row for is the same
		// case: the badge then shows the skill and level only.
		assertTrue(FishingCatches.forOption(null, "Net").isEmpty());
		assertTrue(FishingCatches.forOption(FishingSpot.COMMON_TENCH, "Catch").isEmpty());
		assertTrue(FishingCatches.forOption(FishingSpot.QUEST_RUM_DEAL, "Fish").isEmpty());
	}

	@Test
	public void unknownOrMissingOptionFallsBackToNothing()
	{
		assertTrue(FishingCatches.forOption(FishingSpot.SHRIMP, null).isEmpty());
		assertTrue(FishingCatches.forOption(FishingSpot.SHRIMP, "Harpoon").isEmpty());
		assertTrue(FishingCatches.forOption(FishingSpot.SHRIMP, "Talk-to").isEmpty());
	}

	@Test
	public void optionMatchingIgnoresCase()
	{
		assertEquals(Arrays.asList("Shrimps", "Anchovies"), names(FishingCatches.forOption(FishingSpot.SHRIMP, "NET")));
		assertEquals(Arrays.asList("Mackerel", "Cod", "Bass"), names(FishingCatches.forOption(FishingSpot.SHARK, "big net")));
	}

	@Test
	public void everyFishHasAnItemForItsIcon()
	{
		for (FishingSpot spot : FishingSpot.values())
		{
			for (String option : new String[] {"Net", "Small Net", "Big Net", "Bait", "Lure", "Cage", "Harpoon", "Use-rod", "Fish"})
			{
				for (FishingCatches.Fish fish : FishingCatches.forOption(spot, option))
				{
					assertTrue(fish.getName() + " has no item", fish.getItemId() > 0);
					assertTrue(fish.getName() + " has no level", fish.getLevel() >= 1);
					assertSame(fish.getName() + " round-trips by item", fish, FishingCatches.byItem(fish.getItemId()));
				}
			}
		}
	}

	@Test
	public void levelsAreAscendingWithinAMethod()
	{
		for (FishingSpot spot : FishingSpot.values())
		{
			for (String option : new String[] {"Net", "Big Net", "Bait", "Lure", "Cage", "Harpoon", "Use-rod", "Fish"})
			{
				int last = 0;
				for (FishingCatches.Fish fish : FishingCatches.forOption(spot, option))
				{
					assertTrue(spot + " " + option + " out of order at " + fish.getName(), fish.getLevel() >= last);
					last = fish.getLevel();
				}
			}
		}
	}

	@Test
	public void catchMessagesNameTheFish()
	{
		assertEquals(ItemID.RAW_SHRIMP, FishingCatches.fromCatchMessage("You catch some shrimps.").getItemId());
		assertEquals(ItemID.RAW_ANCHOVIES, FishingCatches.fromCatchMessage("You catch some anchovies.").getItemId());
		assertEquals(ItemID.RAW_SARDINE, FishingCatches.fromCatchMessage("You catch a sardine.").getItemId());
		assertEquals(ItemID.RAW_ANGLERFISH, FishingCatches.fromCatchMessage("You catch an anglerfish.").getItemId());
		assertEquals(ItemID.RAW_SHARK, FishingCatches.fromCatchMessage("You catch a shark!").getItemId());
		assertEquals(ItemID.TBWT_RAW_KARAMBWANJI, FishingCatches.fromCatchMessage("You catch some karambwanji.").getItemId());
		assertEquals(ItemID.BRUT_SPAWNING_TROUT, FishingCatches.fromCatchMessage("You catch a leaping trout.").getItemId());
		assertEquals(ItemID.MINNOW, FishingCatches.fromCatchMessage("You catch some minnows.").getItemId());
	}

	@Test
	public void otherMessagesAreNotCatches()
	{
		assertNull(FishingCatches.fromCatchMessage("You fail to catch anything."));
		assertNull(FishingCatches.fromCatchMessage("You catch a casket."));
		assertNull(FishingCatches.fromCatchMessage("You need a fishing rod to bait these fish."));
		assertNull(FishingCatches.fromCatchMessage(null));
	}

	@Test
	public void byItemKnowsOnlyFish()
	{
		assertEquals("Lobster", FishingCatches.byItem(ItemID.RAW_LOBSTER).getName());
		assertNull(FishingCatches.byItem(ItemID.CASKET));
		assertNull(FishingCatches.byItem(-1));
	}

	@Test
	public void lastCaughtFishComesFirst()
	{
		final List<FishingCatches.Fish> bait = FishingCatches.catchable(
			FishingCatches.forOption(FishingSpot.SHRIMP, "Bait"), 10);

		assertEquals(Arrays.asList("Herring", "Sardine"),
			names(FishingCatches.highlightFirst(bait, ItemID.RAW_HERRING)));
		assertEquals("unknown catch keeps the level order", Arrays.asList("Sardine", "Herring"),
			names(FishingCatches.highlightFirst(bait, -1)));
		assertEquals("a catch from another method keeps the level order", Arrays.asList("Sardine", "Herring"),
			names(FishingCatches.highlightFirst(bait, ItemID.RAW_SHRIMP)));
	}

	/** "Shrimps" for one the player can catch, "Anchovies 15" for one locked behind its level. */
	private static List<String> shown(List<FishingCatches.Catch> catches)
	{
		return catches.stream()
			.map(c -> c.isCatchable() ? c.getFish().getName() : c.getFish().getName() + " " + c.getFish().getLevel())
			.collect(Collectors.toList());
	}

	@Test
	public void netSpotShowsEveryFishWithTheLockedOnesMarked()
	{
		final List<FishingCatches.Fish> net = FishingCatches.forOption(FishingSpot.SHRIMP, "Net");
		// Below Anchovies: Shrimps now, Anchovies at 15.
		assertEquals(Arrays.asList("Shrimps", "Anchovies 15"), shown(FishingCatches.options(net, 14, -1)));
		// On the level: both.
		assertEquals(Arrays.asList("Shrimps", "Anchovies"), shown(FishingCatches.options(net, 15, -1)));
	}

	@Test
	public void baitSpotBelowBetweenAndAboveItsLevels()
	{
		final List<FishingCatches.Fish> bait = FishingCatches.forOption(FishingSpot.SHRIMP, "Bait");
		assertEquals("below both", Arrays.asList("Sardine 5", "Herring 10"), shown(FishingCatches.options(bait, 4, -1)));
		assertEquals("between", Arrays.asList("Sardine", "Herring 10"), shown(FishingCatches.options(bait, 7, -1)));
		assertEquals("above both", Arrays.asList("Sardine", "Herring"), shown(FishingCatches.options(bait, 99, -1)));
	}

	@Test
	public void lastCatchLeadsTheCatchableAndLockedStayLast()
	{
		final List<FishingCatches.Fish> bait = FishingCatches.forOption(FishingSpot.SHRIMP, "Bait");
		assertEquals(Arrays.asList("Herring", "Sardine"),
			shown(FishingCatches.options(bait, 10, ItemID.RAW_HERRING)));
		assertEquals(Arrays.asList("Sardine", "Herring 10"),
			shown(FishingCatches.options(bait, 9, ItemID.RAW_SARDINE)));
	}

	@Test
	public void unknownSpotHasNoOptions()
	{
		assertTrue(FishingCatches.options(FishingCatches.forOption(null, "Net"), 50, -1).isEmpty());
	}

	@Test
	public void lastCaughtAboveTheShownLevelStillLeadsWhenItIsInTheList()
	{
		// Net at 15: Shrimps and Anchovies are both catchable; the last catch
		// was anchovies, so anchovies lead.
		final List<FishingCatches.Fish> net = FishingCatches.catchable(
			FishingCatches.forOption(FishingSpot.SHRIMP, "Net"), 15);
		assertEquals(Arrays.asList("Anchovies", "Shrimps"),
			names(FishingCatches.highlightFirst(net, ItemID.RAW_ANCHOVIES)));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.game.FishingSpot;
import org.junit.Test;

/**
 * The "Needs:" row on a fishing click: each option with and without its
 * tool, worn or carried, the harpoon variants, barehanded harpooning, bait
 * and level (Board, 2026-11-04).
 */
public class FishingGearTest
{
	private static final List<FishingCatches.Fish> SHRIMP_NET = FishingCatches.forOption(FishingSpot.SHRIMP, "Net");
	private static final List<FishingCatches.Fish> SHRIMP_BAIT = FishingCatches.forOption(FishingSpot.SHRIMP, "Bait");
	private static final List<FishingCatches.Fish> TUNA_HARPOON = FishingCatches.forOption(FishingSpot.LOBSTER, "Harpoon");
	private static final List<FishingCatches.Fish> SHARK_HARPOON = FishingCatches.forOption(FishingSpot.SHARK, "Harpoon");

	private static FishingGear.Kit kit(int level, String... items)
	{
		return new FishingGear.Kit(Arrays.asList(items), false, level);
	}

	private static FishingGear.Kit barbarian(int level, String... items)
	{
		return new FishingGear.Kit(Arrays.asList(items), true, level);
	}

	private static List<String> missing(String option, List<FishingCatches.Fish> fish, FishingGear.Kit kit)
	{
		return FishingGear.missing(option, fish, kit);
	}

	@Test
	public void baitWithNothingNeedsRodAndBait()
	{
		final List<String> missing = missing("Bait", SHRIMP_BAIT, kit(99));
		assertEquals(Arrays.asList("Fishing rod", "bait"), missing);
		assertEquals("Needs: Fishing rod + bait", FishingGear.text(missing));
	}

	@Test
	public void baitWithRodButNoBaitNeedsBait()
	{
		assertEquals(Collections.singletonList("bait"), missing("Bait", SHRIMP_BAIT, kit(99, "Fishing rod")));
	}

	@Test
	public void baitWithBaitButNoRodNeedsRod()
	{
		assertEquals(Collections.singletonList("Fishing rod"), missing("Bait", SHRIMP_BAIT, kit(99, "Fishing bait")));
	}

	@Test
	public void baitWithEverythingNeedsNothing()
	{
		assertTrue(missing("Bait", SHRIMP_BAIT, kit(99, "Fishing rod", "Fishing bait")).isEmpty());
		assertTrue(missing("Bait", SHRIMP_BAIT, kit(99, "Pearl fishing rod", "Fishing bait")).isEmpty());
		assertTrue(missing("Bait", SHRIMP_BAIT, kit(99, "Oily fishing rod", "Fishing bait")).isEmpty());
		assertNull(FishingGear.text(missing("Bait", SHRIMP_BAIT, kit(99, "Fishing rod", "Fishing bait"))));
	}

	@Test
	public void aFlyRodIsNotABaitRod()
	{
		assertEquals(Collections.singletonList("Fishing rod"),
			missing("Bait", SHRIMP_BAIT, kit(99, "Fly fishing rod", "Fishing bait")));
	}

	@Test
	public void lureNeedsFlyRodAndFeathers()
	{
		assertEquals(Arrays.asList("Fly fishing rod", "feathers"), missing("Lure", Collections.emptyList(), kit(99)));
		assertEquals(Collections.singletonList("feathers"),
			missing("Lure", Collections.emptyList(), kit(99, "Fly fishing rod")));
		assertTrue(missing("Lure", Collections.emptyList(), kit(99, "Fly fishing rod", "Feather")).isEmpty());
		assertTrue(missing("Lure", Collections.emptyList(), kit(99, "Pearl fly fishing rod", "Stripy feather")).isEmpty());
	}

	@Test
	public void netsAndCage()
	{
		assertEquals(Collections.singletonList("Small fishing net"), missing("Net", SHRIMP_NET, kit(99)));
		assertTrue(missing("Small Net", SHRIMP_NET, kit(99, "Small fishing net")).isEmpty());
		assertEquals(Collections.singletonList("Big fishing net"), missing("Big Net", Collections.emptyList(), kit(99)));
		assertTrue(missing("Big Net", Collections.emptyList(), kit(99, "Big fishing net")).isEmpty());
		assertEquals(Collections.singletonList("Lobster pot"), missing("Cage", Collections.emptyList(), kit(99)));
		assertTrue(missing("Cage", Collections.emptyList(), kit(99, "Lobster pot")).isEmpty());
	}

	@Test
	public void wornCountsTheSameAsCarried()
	{
		// The kit is every item carried or worn; a wielded harpoon is one of them.
		assertTrue(missing("Harpoon", TUNA_HARPOON, kit(99, "Dragon harpoon")).isEmpty());
	}

	@Test
	public void everyHarpoonVariantCounts()
	{
		for (String harpoon : new String[] {
			"Harpoon", "Barb-tail harpoon", "Dragon harpoon", "Infernal harpoon", "Crystal harpoon",
			"Infernal harpoon (uncharged)", "Trailblazer harpoon"})
		{
			assertTrue(harpoon, missing("Harpoon", TUNA_HARPOON, kit(99, harpoon)).isEmpty());
		}
	}

	@Test
	public void harpoonWithoutOneNeedsOne()
	{
		assertEquals(Collections.singletonList("Harpoon"), missing("Harpoon", TUNA_HARPOON, kit(99)));
	}

	@Test
	public void barbarianTrainedHarpoonsBarehandedAtTwentyOver()
	{
		// Tuna is 35, so barehanded from 55; shark is 76, so from 96.
		assertTrue(missing("Harpoon", TUNA_HARPOON, barbarian(55)).isEmpty());
		assertEquals(Collections.singletonList("Harpoon"), missing("Harpoon", TUNA_HARPOON, barbarian(54)));
		assertTrue(missing("Harpoon", SHARK_HARPOON, barbarian(96)).isEmpty());
		assertEquals(Collections.singletonList("Harpoon"), missing("Harpoon", SHARK_HARPOON, barbarian(90)));
	}

	@Test
	public void barehandedOnAnUnknownSpotNeedsTunasLevel()
	{
		assertTrue(missing("Harpoon", Collections.emptyList(), barbarian(55)).isEmpty());
		assertEquals(Collections.singletonList("Harpoon"), missing("Harpoon", Collections.emptyList(), barbarian(40)));
	}

	@Test
	public void barbarianTrainingDoesNotFreeTheCage()
	{
		assertEquals(Collections.singletonList("Lobster pot"), missing("Cage", Collections.emptyList(), barbarian(99)));
	}

	@Test
	public void barbarianRodNeedsRodAndBait()
	{
		assertEquals(Arrays.asList("Barbarian rod", "bait"), missing("Use-rod", Collections.emptyList(), kit(99)));
		assertTrue(missing("Use-rod", Collections.emptyList(), kit(99, "Barbarian rod", "Feather")).isEmpty());
		assertTrue(missing("Use-rod", Collections.emptyList(), kit(99, "Barbarian rod", "Fish offcuts")).isEmpty());
	}

	@Test
	public void zeroBaitIsNoBait()
	{
		// Items with a quantity of 0 never reach the kit: the plugin skips empty slots.
		assertEquals(Collections.singletonList("bait"), missing("Bait", SHRIMP_BAIT, kit(99, "Fishing rod")));
	}

	@Test
	public void levelTooLowIsNamed()
	{
		// Sardine, the lowest Bait fish on a shrimp spot, is level 5.
		final List<String> missing = missing("Bait", SHRIMP_BAIT, kit(3, "Fishing rod", "Fishing bait"));
		assertEquals(Collections.singletonList("Fishing 5"), missing);
		assertEquals("Needs: Fishing 5", FishingGear.text(missing));
		assertEquals(Arrays.asList("Fishing rod", "bait", "Fishing 5"), missing("Bait", SHRIMP_BAIT, kit(3)));
	}

	@Test
	public void unknownOptionsSayNothing()
	{
		assertTrue(missing("Talk-to", Collections.emptyList(), kit(1)).isEmpty());
		assertTrue(missing("Cast", Collections.emptyList(), kit(1)).isEmpty());
		assertTrue(missing(null, Collections.emptyList(), kit(1)).isEmpty());
	}

	@Test
	public void optionCaseIsIgnored()
	{
		assertEquals(Collections.singletonList("Small fishing net"), missing("NET", SHRIMP_NET, kit(99)));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * A micro-benchmark of the work that runs every frame or every client tick
 * around a fishing spot, without a client: the health bar sprite retries,
 * the spot pather's per-tick tile check and the session row's layout. It
 * prints its numbers (run with {@code ./gradlew test --info} to see them)
 * and fails only on a count regression or a gross slowdown, so it does not
 * flake on a busy machine.
 */
public class FramePathBenchmarkTest
{
	/** About 20 seconds of client ticks at 50 a second. */
	private static final int FRAMES = 1_000;

	@Test
	public void healthBarSpritesNotReadyCostOneCacheReadASecondNotOneAFrame()
	{
		final int[] builds = {0};
		final NativeHealthBarHider<Object> hider = new NativeHealthBarHider<>(new java.util.HashMap<>(), id ->
		{
			builds[0]++;
			return null;
		});

		final long start = System.nanoTime();
		for (int i = 0; i < FRAMES; i++)
		{
			hider.apply();
		}
		final long nanos = System.nanoTime() - start;

		final int before = FRAMES * NativeHealthBarHider.SPRITE_IDS.length;
		System.out.printf("hider, sprites not ready: %d cache reads per %d frames (was %d), %.2f us/frame%n",
			builds[0], FRAMES, before, nanos / 1_000.0 / FRAMES);
		assertEquals(FRAMES / NativeHealthBarHider.RETRY_CALLS * NativeHealthBarHider.SPRITE_IDS.length, builds[0]);
	}

	@Test
	public void spotTileCheckIsCheapEnoughForEveryTick()
	{
		final Object spot = new Object();
		final SpotPathing pathing = new SpotPathing(() -> FishingSpotPath.ON_SPOT_MOVE, new SpotPathing.Router()
		{
			@Override
			public boolean available()
			{
				return false;
			}

			@Override
			public boolean route(NextFishingSpot.Spot s)
			{
				return false;
			}

			@Override
			public void clear()
			{
			}
		});
		pathing.fishingOn(net.runelite.client.game.FishingSpot.SHRIMP, "Net", spot);
		final long tile = SpotPathing.tile(3086, 3228, 0);
		final int[] picks = {0};

		final long start = System.nanoTime();
		for (int i = 0; i < FRAMES * 100; i++)
		{
			pathing.tick((type, method) ->
			{
				picks[0]++;
				return null;
			}, npc -> tile);
		}
		final long nanos = System.nanoTime() - start;

		System.out.printf("spot pather tick, spot standing still: %.1f ns/tick, %d searches%n",
			(double) nanos / (FRAMES * 100), picks[0]);
		assertEquals("a spot that does not move is never searched for", 0, picks[0]);
		assertTrue("under 50 microseconds a tick", nanos / (FRAMES * 100) < 50_000);
	}

	@Test
	public void sessionRowLayoutPerFrame()
	{
		final XpProgress xp = XpProgress.of(Experience.getXpForLevel(17) + 100);
		final List<SessionRow.Cell> cells = SessionRow.cells(Skill.FISHING, 24, 180_000, 10_597, 459, xp,
			true, true, true);
		final int[] widths = {96, 58, 60, 70};
		assertEquals(widths.length, cells.size());

		int sink = 0;
		final long start = System.nanoTime();
		for (int i = 0; i < FRAMES * 100; i++)
		{
			final int[][] lines = SessionColumns.lines(widths.length, true, true);
			for (int[] line : lines)
			{
				sink += SessionColumns.fit(widths, line, SessionColumns.width(widths, lines))[0];
			}
		}
		final long nanos = System.nanoTime() - start;

		System.out.printf("session row layout: %.1f ns/frame (sink %d)%n", (double) nanos / (FRAMES * 100), sink);
		assertTrue("under 50 microseconds a frame", nanos / (FRAMES * 100) < 50_000);
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

/**
 * Board's in-game test, 2026-11-06: "Hide game health bar" hid every
 * standard bar but the plugin drew back only some. Every bar hidden must be
 * drawn back, for every player and NPC that shows one.
 */
public class GameHealthBarsTest
{
	/** A stand-in actor: its bar reading and where it projects. */
	private static final class Fake
	{
		final int ratio;
		final int scale;
		final boolean talking;
		final int[] anchor;

		Fake(int ratio, int scale, boolean talking, int[] anchor)
		{
			this.ratio = ratio;
			this.scale = scale;
			this.talking = talking;
			this.anchor = anchor;
		}
	}

	private static final GameHealthBars.Access<Fake> ACCESS = new GameHealthBars.Access<Fake>()
	{
		@Override
		public int ratio(Fake actor)
		{
			return actor.ratio;
		}

		@Override
		public int scale(Fake actor)
		{
			return actor.scale;
		}

		@Override
		public boolean talking(Fake actor)
		{
			return actor.talking;
		}

		@Override
		public int[] anchor(Fake actor)
		{
			return actor.anchor;
		}
	};

	@Test
	public void aBarIsShownOnlyWithARatioAndAScale()
	{
		assertTrue(GameHealthBars.shown(0, 30));
		assertTrue(GameHealthBars.shown(30, 30));
		assertFalse("no bar: the client reports -1", GameHealthBars.shown(-1, 30));
		assertFalse(GameHealthBars.shown(10, -1));
	}

	@Test
	public void theBarSitsWhereTheClientDrawsIt()
	{
		// Projected at (200, 100): the client's offset starts at -2 and grows by
		// the bar's 5 px, so the top is 3 px above the point; centred on x.
		assertEquals(new Rectangle(185, 97, 30, 5), GameHealthBars.box(200, 100, 30, false));
	}

	@Test
	public void chatLiftsTheBarTwelvePixels()
	{
		assertEquals(new Rectangle(185, 85, 30, 5), GameHealthBars.box(200, 100, 30, true));
	}

	@Test
	public void anOddWidthCentresAsTheClientDoes()
	{
		// x - (width >> 1)
		assertEquals(200 - 7, GameHealthBars.box(200, 100, 15, false).x);
	}

	@Test
	public void theFillIsTheRatiosShareOfTheWidth()
	{
		assertEquals(30, GameHealthBars.filled(30, 30, 30));
		assertEquals(15, GameHealthBars.filled(15, 30, 30));
		assertEquals(0, GameHealthBars.filled(0, 30, 30));
		assertEquals("any health left shows a pixel", 1, GameHealthBars.filled(1, 255, 30));
		assertEquals("a boss bar", 60, GameHealthBars.filled(60, 120, 120));
	}

	@Test
	public void theWidthIsTheScaleUpToTheWidestBar()
	{
		assertEquals(30, GameHealthBars.width(30));
		assertEquals(120, GameHealthBars.width(120));
		assertEquals(160, GameHealthBars.width(255));
	}

	/**
	 * Several players fighting nearby, NPCs at different health, some talking,
	 * some off screen, and your target: every on-screen actor with a bar gets
	 * exactly one, in its own place, and the target is left to the readout.
	 */
	@Test
	public void aCrowdGetsABarEachExceptTheTarget()
	{
		final List<Fake> crowd = new ArrayList<>();
		for (int i = 0; i < 12; i++)
		{
			crowd.add(new Fake(i * 2, 30, i % 3 == 0, new int[]{100 + i * 40, 200}));
		}
		final Fake noBar = new Fake(-1, 30, false, new int[]{50, 50});
		final Fake offScreen = new Fake(10, 30, false, null);
		final Fake target = new Fake(5, 30, false, new int[]{700, 200});
		crowd.add(noBar);
		crowd.add(offScreen);
		crowd.add(target);

		final List<GameHealthBars.Bar> bars = GameHealthBars.plan(crowd, a -> a == target, ACCESS);

		assertEquals("one per on-screen actor with a bar, the target excepted", 12, bars.size());
		final Set<Integer> centres = new HashSet<>();
		for (int i = 0; i < 12; i++)
		{
			final GameHealthBars.Bar bar = bars.get(i);
			final Rectangle box = bar.getBox();
			centres.add(box.x + 15);
			assertEquals("fill follows its own ratio", i * 2, bar.getFilled());
			assertEquals("talking actors' bars sit higher", i % 3 == 0 ? 85 + 100 : 97 + 100, box.y);
		}
		assertEquals("each in its own place", 12, centres.size());
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class HealthReadoutTest
{
	/** Measured: Guard, 22 max hitpoints, healthScale 30, ratio 20 -> exactly 15. */
	private static HealthRecovery.Range guard()
	{
		return HealthRecovery.recover(20, 30, 22);
	}

	@Test
	public void showsHitpoints()
	{
		assertEquals("15 / 22",
			HealthReadout.text(guard(), 22, 20, 30, DisplayMode.HITPOINTS, false, -1));
	}

	@Test
	public void showsPercentage()
	{
		assertEquals("67%",
			HealthReadout.text(guard(), 22, 20, 30, DisplayMode.PERCENTAGE, false, -1));
	}

	@Test
	public void showsBoth()
	{
		assertEquals("15 / 22 (67%)",
			HealthReadout.text(guard(), 22, 20, 30, DisplayMode.BOTH, false, -1));
	}

	@Test
	public void showsDecimalPercentage()
	{
		assertEquals("66.7%",
			HealthReadout.text(guard(), 22, 20, 30, DisplayMode.PERCENTAGE, true, -1));
	}

	@Test
	public void fallsBackToPercentageWhenMaxHealthIsUnknown()
	{
		// An unranked player, or the lookup turned off. Showing the fraction is
		// honest; inventing a hitpoints value would not be.
		assertEquals("67%",
			HealthReadout.text(null, -1, 20, 30, DisplayMode.HITPOINTS, false, -1));
	}

	@Test
	public void anExactValueIsShownAsItselfNotRecovered()
	{
		// Your own health is known, so it must be printed rather than guessed.
		// The recovered range for this ratio is 28-30 with midpoint 29; if the
		// exact value ever loses to the midpoint, the readout has started
		// inventing numbers it did not need to.
		assertEquals("30 / 88",
			HealthReadout.text(HealthRecovery.recover(10, 30, 88), 88, 10, 30,
				DisplayMode.HITPOINTS, false, 30));
	}

	@Test
	public void anExactValueDrivesThePercentageToo()
	{
		assertEquals("34%",
			HealthReadout.text(null, 88, -1, -1, DisplayMode.PERCENTAGE, false, 30));
	}

	@Test
	public void exactFractionIgnoresTheBar()
	{
		// scale and ratio are absent for a self readout; the orb supplies both
		// numbers and the bar is not consulted at all.
		assertEquals(0.5, HealthReadout.fraction(-1, -1, 44, 88), 0.0001);
		assertEquals(1.0, HealthReadout.fraction(-1, -1, 99, 99), 0.0001);
		assertEquals(0.0, HealthReadout.fraction(-1, -1, 0, 99), 0.0001);
	}

	@Test
	public void fractionIsClampedAndSafe()
	{
		assertEquals(0.0, HealthReadout.fraction(0, 30, -1, -1), 0.0001);
		assertEquals(1.0, HealthReadout.fraction(30, 30, -1, -1), 0.0001);
		assertEquals(0.0, HealthReadout.fraction(10, 0, -1, -1), 0.0001);
		assertEquals(0.5, HealthReadout.fraction(15, 30, -1, -1), 0.0001);
	}

	private static final Color FULL = new Color(0, 146, 54, 230);
	private static final Color MID = new Color(255, 193, 7, 230);
	private static final Color LOW = new Color(199, 26, 26, 230);

	private static Color colour(double fraction)
	{
		return HealthReadout.colour(fraction, FULL, MID, LOW);
	}

	@Test
	public void colourReadsAsHealthyAtFullAndDangerousAtEmpty()
	{
		// Deliberately not asserting that any one channel moves monotonically.
		// The ramp passes through amber, whose green channel is higher than the
		// green endpoint's, so "greener as health rises" is not true and is not
		// what the gradient is for. What must hold is which channel dominates.
		assertTrue("full health should read green, not red",
			colour(1.0).getGreen() > colour(1.0).getRed());
		assertTrue("empty health should read red, not green",
			colour(0.0).getRed() > colour(0.0).getGreen());
		assertTrue("the ends must be visibly different",
			!colour(0.0).equals(colour(1.0)));
	}

	@Test
	public void colourHandlesOutOfRangeInput()
	{
		// Never throw over a display detail.
		colour(-5);
		colour(5);
	}

	@Test
	public void colourUsesTheStopsItIsGiven()
	{
		// The stops are user-configurable, so the ramp must follow them rather
		// than any palette baked into the class.
		final Color blue = new Color(0, 0, 255);
		final Color white = new Color(255, 255, 255);
		final Color black = new Color(0, 0, 0);

		assertEquals(blue, HealthReadout.colour(1.0, blue, white, black));
		assertEquals(black, HealthReadout.colour(0.0, blue, white, black));
		assertEquals(white, HealthReadout.colour(0.5, blue, white, black));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The recovery math is the one part of this plugin that is pure, so it is the
 * one part with no excuse for being untested.
 *
 * Several expectations below are pinned to measurements in BRIEF.md Phase 0.5
 * rather than to what the implementation happens to return.
 */
public class HealthRecoveryTest
{
	/** The server's own calculation, used to verify the inverse round-trips. */
	private static int serverRatio(int health, int healthScale, int maxHealth)
	{
		return health <= 0 ? 0 : 1 + (healthScale - 1) * health / maxHealth;
	}

	@Test
	public void recoversNpcHealthExactly()
	{
		// Measured: Guard, maxHealth 22, healthScale 30, ratio 20.
		HealthRecovery.Range r = HealthRecovery.recover(20, 30, 22);
		assertTrue("maxHealth <= healthScale must resolve exactly", r.isExact());
		assertEquals(15, r.min());
		assertEquals(15, r.midpoint());
	}

	@Test
	public void recoversPlayerHealthAsAnInterval()
	{
		// Measured: a live opponent, 88 max hitpoints, healthScale 30, ratio 10,
		// displayed by the stock plugin as "29/88".
		HealthRecovery.Range r = HealthRecovery.recover(10, 30, 88);
		assertFalse("maxHealth > healthScale cannot resolve exactly", r.isExact());
		assertEquals(28, r.min());
		assertEquals(30, r.max());
		assertEquals(3, r.width());
		assertEquals("the base client displays this midpoint", 29, r.midpoint());
	}

	@Test
	public void healthScaleOfOneKnowsOnlyThatTheActorLives()
	{
		HealthRecovery.Range r = HealthRecovery.recover(1, 1, 99);
		assertFalse(r.isExact());
		assertEquals(1, r.min());
		assertEquals(99, r.max());
	}

	@Test
	public void zeroRatioIsUnambiguouslyDead()
	{
		HealthRecovery.Range r = HealthRecovery.recover(0, 30, 88);
		assertTrue(r.isExact());
		assertEquals(0, r.min());
		assertEquals(0, r.midpoint());
	}

	@Test
	public void ratioOfOneHasNoLowerBoundBeyondAlive()
	{
		// health = 0 forces ratio 0, so ratio 1 is not produced by the general
		// formula and carries no usable lower bound.
		HealthRecovery.Range r = HealthRecovery.recover(1, 30, 88);
		assertEquals(1, r.min());
	}

	@Test
	public void everyRecoveredRangeContainsTheTrueHealth()
	{
		// The property the readout depends on: whatever the display shows, the
		// range must never exclude the actual value.
		for (int maxHealth = 1; maxHealth <= 120; maxHealth++)
		{
			for (int health = 1; health <= maxHealth; health++)
			{
				int ratio = serverRatio(health, 30, maxHealth);
				HealthRecovery.Range r = HealthRecovery.recover(ratio, 30, maxHealth);

				assertTrue(
					"range " + r + " excluded true health " + health + " of " + maxHealth,
					health >= r.min() && health <= r.max());
			}
		}
	}

	@Test
	public void midpointIsNeverWrongByMoreThanHalfTheRange()
	{
		for (int maxHealth = 1; maxHealth <= 120; maxHealth++)
		{
			for (int health = 1; health <= maxHealth; health++)
			{
				HealthRecovery.Range r =
					HealthRecovery.recover(serverRatio(health, 30, maxHealth), 30, maxHealth);

				assertTrue(
					"midpoint " + r.midpoint() + " too far from " + health + " for range " + r,
					Math.abs(r.midpoint() - health) <= r.width() / 2);
			}
		}
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsNonPositiveMaxHealth()
	{
		HealthRecovery.recover(10, 30, 0);
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

public class IdleBadgeTest
{
	private static final int SECONDS = 60;

	private IdleBadge idle;

	@Before
	public void setUp()
	{
		idle = new IdleBadge();
	}

	@Test
	public void nothingDoneYetIsNotIdle()
	{
		idle.tick(null, false, 0);
		assertNull(idle.idleSkill(IdleBadgeMode.UNTIL_NEXT, SECONDS, 0));
	}

	@Test
	public void workingIsNotIdle()
	{
		idle.tick(Skill.FISHING, false, 0);
		assertNull(idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 0));
	}

	@Test
	public void stoppingFishingLeavesTheBadgeUpAsNotFishing()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		assertEquals(Skill.FISHING, idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 1_000));
	}

	@Test
	public void fishingIdleFishingGoesBackToWorking()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		idle.tick(Skill.FISHING, false, 2_000);
		assertNull(idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 2_000));

		// And a second stop starts a fresh idle period, not the old one.
		idle.tick(null, false, 100_000);
		assertEquals(Skill.FISHING, idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 159_000));
	}

	@Test
	public void timedIdleEndsAfterItsSeconds()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		assertEquals(Skill.FISHING, idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 60_999));
		assertNull(idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 61_000));
	}

	@Test
	public void untilNextOutlastsTheTimeout()
	{
		idle.tick(Skill.MINING, false, 0);
		idle.tick(null, false, 1_000);
		assertEquals(Skill.MINING, idle.idleSkill(IdleBadgeMode.UNTIL_NEXT, SECONDS, 3_600_000));
	}

	@Test
	public void offNeverShowsIdle()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		assertNull(idle.idleSkill(IdleBadgeMode.OFF, SECONDS, 1_000));
	}

	@Test
	public void combatEndsIdle()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		idle.tick(null, true, 2_000);
		assertNull(idle.idleSkill(IdleBadgeMode.UNTIL_NEXT, SECONDS, 2_000));

		// Still nothing once the fight is over: the fishing is not resurrected.
		idle.tick(null, false, 30_000);
		assertNull(idle.idleSkill(IdleBadgeMode.UNTIL_NEXT, SECONDS, 30_000));
	}

	@Test
	public void beingHitWhileStillFishingKeepsTheActivity()
	{
		idle.tick(Skill.FISHING, true, 0);
		idle.tick(null, false, 1_000);
		assertEquals(Skill.FISHING, idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 1_000));
	}

	@Test
	public void anotherActivityReplacesTheIdleSkill()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		idle.tick(Skill.WOODCUTTING, false, 2_000);
		idle.tick(null, false, 3_000);
		assertEquals(Skill.WOODCUTTING, idle.idleSkill(IdleBadgeMode.TIMED, SECONDS, 3_000));
	}

	@Test
	public void clearForgetsEverything()
	{
		idle.tick(Skill.FISHING, false, 0);
		idle.tick(null, false, 1_000);
		idle.clear();
		assertNull(idle.idleSkill(IdleBadgeMode.UNTIL_NEXT, SECONDS, 1_000));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * A fish appearing in the inventory, or its stack growing, is a catch; a
 * fish leaving (dropped, banked, cooked) is not.
 */
public class InventoryCatchesTest
{
	@Test
	public void aNewFishIsACatch()
	{
		InventoryCatches inventory = new InventoryCatches();
		assertEquals(-1, inventory.observe(new int[] {ItemID.NET}, new int[] {1}));
		assertEquals(ItemID.RAW_SHRIMP,
			inventory.observe(new int[] {ItemID.NET, ItemID.RAW_SHRIMP}, new int[] {1, 1}));
	}

	@Test
	public void anotherOfTheSameFishIsACatch()
	{
		InventoryCatches inventory = new InventoryCatches();
		inventory.observe(new int[] {ItemID.RAW_SHRIMP}, new int[] {1});
		assertEquals(ItemID.RAW_SHRIMP,
			inventory.observe(new int[] {ItemID.RAW_SHRIMP, ItemID.RAW_SHRIMP}, new int[] {1, 1}));
	}

	@Test
	public void aGrowingStackIsACatch()
	{
		InventoryCatches inventory = new InventoryCatches();
		inventory.observe(new int[] {ItemID.MINNOW}, new int[] {40});
		assertEquals(ItemID.MINNOW, inventory.observe(new int[] {ItemID.MINNOW}, new int[] {55}));
	}

	@Test
	public void losingAFishIsNotACatch()
	{
		InventoryCatches inventory = new InventoryCatches();
		inventory.observe(new int[] {ItemID.RAW_SHRIMP, ItemID.RAW_SARDINE}, new int[] {1, 1});
		assertEquals(-1, inventory.observe(new int[] {ItemID.RAW_SARDINE}, new int[] {1}));
	}

	@Test
	public void nonFishAreIgnored()
	{
		InventoryCatches inventory = new InventoryCatches();
		inventory.observe(new int[] {}, new int[] {});
		assertEquals(-1, inventory.observe(new int[] {ItemID.CASKET, ItemID.COINS}, new int[] {1, 500}));
	}

	@Test
	public void theFirstSnapshotIsNeverACatch()
	{
		// Enabling the plugin with a full inventory of fish must not claim
		// the last one was just caught.
		InventoryCatches inventory = new InventoryCatches();
		assertEquals(-1, inventory.observe(new int[] {ItemID.RAW_SHARK, ItemID.RAW_SHARK}, new int[] {1, 1}));
	}

	@Test
	public void twoFishAtOnceReportsTheRarerHigherLevelOne()
	{
		// Karambwanji nets can land shrimps and karambwanji in one tick; the
		// higher level fish is the one worth showing.
		InventoryCatches inventory = new InventoryCatches();
		inventory.observe(new int[] {}, new int[] {});
		assertEquals(ItemID.TBWT_RAW_KARAMBWANJI,
			inventory.observe(new int[] {ItemID.RAW_SHRIMP, ItemID.TBWT_RAW_KARAMBWANJI}, new int[] {1, 1}));
	}

	@Test
	public void clearForgetsTheSnapshot()
	{
		InventoryCatches inventory = new InventoryCatches();
		inventory.observe(new int[] {}, new int[] {});
		inventory.clear();
		assertEquals(-1, inventory.observe(new int[] {ItemID.RAW_SHRIMP}, new int[] {1}));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import java.awt.Color;
import org.junit.Test;

public class InventoryFillTest
{
	private static final Color GREEN = new Color(0, 146, 54, 230);
	private static final Color YELLOW = new Color(255, 193, 7, 230);
	private static final Color RED = new Color(199, 26, 26, 230);

	private static final String[] FISH_ACTIONS = {"Eat", null, null, null, "Drop"};
	private static final String[] WIELDABLE = {null, "Wield", null, null, "Drop"};

	@Test
	public void emptyIsGreenHalfIsYellowFullIsRed()
	{
		assertEquals(GREEN, InventoryFill.colour(0.0, GREEN, YELLOW, RED));
		assertEquals(YELLOW, InventoryFill.colour(0.5, GREEN, YELLOW, RED));
		assertEquals(RED, InventoryFill.colour(1.0, GREEN, YELLOW, RED));
	}

	@Test
	public void colourSlidesRatherThanSnapping()
	{
		final Color quarter = InventoryFill.colour(0.25, GREEN, YELLOW, RED);
		// Halfway between green and yellow on every channel.
		assertEquals(128, quarter.getRed());
		assertEquals(170, quarter.getGreen());
		assertEquals(31, quarter.getBlue());
	}

	@Test
	public void colourClampsOutOfRange()
	{
		assertEquals(GREEN, InventoryFill.colour(-1, GREEN, YELLOW, RED));
		assertEquals(RED, InventoryFill.colour(2, GREEN, YELLOW, RED));
	}

	@Test
	public void twentyEightFilledIsFull()
	{
		assertEquals(1.0, InventoryFill.fraction(28, 0), 0);
		assertEquals(0.0, InventoryFill.fraction(0, 28), 0);
		assertEquals(0.5, InventoryFill.fraction(14, 14), 1e-9);
	}

	@Test
	public void labelCountsFreeSlotsOutOfTwentyEight()
	{
		assertEquals("Inv 28/28 free", InventoryFill.label(28));
		assertEquals("Inv 26/28 free", InventoryFill.label(26));
		assertEquals("Inv 0/28 free", InventoryFill.label(0));
	}

	@Test
	public void stackablesHoldASlotSoTheyAreNotFree()
	{
		// Rod, a feather stack and 20 trout: 6 slots free, and the bar reads
		// 20 of the 26 slots the trip can fill.
		assertEquals("Inv 6/28 free", InventoryFill.label(6));
		assertEquals(20.0 / 26, InventoryFill.fraction(20, 6), 1e-9);
		// Rod, feathers and 26 trout: nothing free, full.
		assertEquals("Inv 0/28 free", InventoryFill.label(0));
		assertEquals(1.0, InventoryFill.fraction(26, 0), 0);
	}

	@Test
	public void unknownInventoryHasNoLabel()
	{
		assertEquals(null, InventoryFill.label(-1));
	}

	@Test
	public void fixedSlotsShrinkTheCapacityInsteadOfFilling()
	{
		// Harpoon and feathers held: 26 free slots, so 13 fish is half.
		assertEquals(0.5, InventoryFill.fraction(13, 13), 1e-9);
		// Harpoon and 27 fish: no slot left, full red.
		assertEquals(1.0, InventoryFill.fraction(27, 0), 0);
		// An inventory of nothing but tools has no room either.
		assertEquals(1.0, InventoryFill.fraction(0, 0), 0);
	}

	@Test
	public void stackablesToolsAndEquipmentDoNotFill()
	{
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(true, "Feather", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(true, "Coin pouch", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(true, "Raw shark", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Small fishing net", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Lobster pot", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Fly fishing rod", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Rune pickaxe", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Bronze axe", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Hammer", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Knife", null));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Dragon harpoon", WIELDABLE));
		assertEquals(InventoryFill.Slot.FIXED, InventoryFill.classify(false, "Rune scimitar", WIELDABLE));
	}

	@Test
	public void whatYouGatherFills()
	{
		assertEquals(InventoryFill.Slot.FILLING, InventoryFill.classify(false, "Raw shark", FISH_ACTIONS));
		assertEquals(InventoryFill.Slot.FILLING, InventoryFill.classify(false, "Yew logs", null));
		assertEquals(InventoryFill.Slot.FILLING, InventoryFill.classify(false, "Iron ore", null));
		assertEquals(InventoryFill.Slot.FILLING, InventoryFill.classify(false, "Jug of wine", null));
		// "axe" inside a word is not a tool.
		assertEquals(InventoryFill.Slot.FILLING, InventoryFill.classify(false, "Flax", null));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.image.BufferedImage;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

/**
 * Board's screenshots, 2026-11-06: the catch icons ran into the word "free"
 * in "Inv 12/28 free", "Inv 14/28 free" and "Inv 0/28 free" but not at
 * other counts. The label's space is now measured at the font's widest digit
 * and a gap kept before the icons, which are drawn from the right edge.
 */
public class InventoryLineTest
{
	/** A font where "1" is narrow and "8" wide, as in most proportional fonts. */
	private static final IntUnaryOperator UNEVEN = c -> c == '1' ? 3 : Character.isDigit(c) ? 6 : 5;

	@Test
	public void everyDigitIsGivenTheWidestDigitsRoom()
	{
		// "Inv 12/28 free": 4 digits at 6, 10 other characters at 5.
		assertEquals(4 * 6 + 10 * 5, InventoryLine.reservedWidth("Inv 12/28 free", UNEVEN, 0));
	}

	@Test
	public void neverLessThanTheMeasuredWidth()
	{
		assertEquals(500, InventoryLine.reservedWidth("Inv 12/28 free", UNEVEN, 500));
	}

	@Test
	public void theSameNumberOfDigitsReservesTheSameWidthAtEveryCount()
	{
		final int reserved = InventoryLine.reservedWidth("Inv 11/28 free", UNEVEN, 0);
		for (int free = 10; free <= 28; free++)
		{
			assertEquals(free + "/28", reserved,
				InventoryLine.reservedWidth("Inv " + free + "/28 free", UNEVEN, 0));
		}
	}

	/** With a real font: at every count the label, the gap and the icons fit the reserved width. */
	@Test
	public void withARealFontTheLabelNeverReachesTheIcons()
	{
		final FontMetrics metrics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics()
			.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		for (int free = 0; free <= 28; free++)
		{
			final String label = InventoryFill.label(free);
			final int reserved = InventoryLine.reservedWidth(label, metrics::charWidth, metrics.stringWidth(label));
			assertTrue(label, reserved >= metrics.stringWidth(label));
		}
		assertTrue(InventoryLine.LABEL_GAP >= SkillingBadgeRenderer.PAD_X);
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.io.BufferedReader;
import java.io.StringReader;
import java.util.List;
import net.runelite.client.game.FishingSpot;
import org.junit.Test;

public class KnownFishingSpotsTest
{
	@Test
	public void parsesRowsAndSkipsCommentsBlanksAndBadLines() throws Exception
	{
		final String tsv = "# comment\n"
			+ "\n"
			+ "LOBSTER\t2599\t3419\t0\tmembers\t68\tFishing Guild\n"
			+ "SHRIMP\t3246\t3155\t0\tfree\t0\tLumbridge Swamp\n"
			+ "NOT_A_SPOT\t1\t2\t0\tfree\t0\tNowhere\n"
			+ "SHRIMP\tx\t3155\t0\tfree\t0\tBroken\n"
			+ "SHRIMP\t1\t2\n";

		final List<NextFishingSpot.Spot> spots = KnownFishingSpots.parse(new BufferedReader(new StringReader(tsv)));

		assertEquals(2, spots.size());
		final NextFishingSpot.Spot guild = spots.get(0);
		assertEquals(FishingSpot.LOBSTER, guild.getType());
		assertEquals(2599, guild.getX());
		assertEquals(3419, guild.getY());
		assertTrue(guild.isMembers());
		assertEquals(68, guild.getMinLevel());
		assertEquals("Fishing Guild", guild.getName());
		assertFalse(spots.get(1).isMembers());
	}

	@Test
	public void bundledListLoadsWithEverySupportedType()
	{
		final List<NextFishingSpot.Spot> spots = KnownFishingSpots.load();

		assertNotNull(spots);
		for (FishingSpot type : new FishingSpot[]{FishingSpot.SHRIMP, FishingSpot.SALMON, FishingSpot.LOBSTER,
			FishingSpot.SHARK, FishingSpot.BARB_FISH})
		{
			assertTrue(type + " has a bundled location", spots.stream().anyMatch(s -> s.getType() == type));
		}
	}

	@Test
	public void bundledListKeepsOutTheWildernessAndInstances()
	{
		for (NextFishingSpot.Spot spot : KnownFishingSpots.load())
		{
			final boolean wilderness = spot.getX() >= 2944 && spot.getX() <= 3392 && spot.getY() >= 3520 && spot.getY() <= 4000;
			assertFalse(spot.getName() + " is in the Wilderness", wilderness);
			assertTrue(spot.getName() + " is not on the surface", spot.getY() < 4000);
		}
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class NativeHealthBarHiderTest
{
	private static final int FIRST = NativeHealthBarHider.SPRITE_IDS[0];

	/** Stands in for the client's sprite override map; values compared by identity. */
	private Map<Integer, Object> overrides;
	private NativeHealthBarHider<Object> hider;

	@Before
	public void setUp()
	{
		overrides = new HashMap<>();
		hider = new NativeHealthBarHider<>(overrides, id -> new Object());
	}

	@Test
	public void optionIsOffByDefault()
	{
		// Off by default for the 1.1.0 Hub release (Board, 2026-11-04 night):
		// a new profile keeps the game's bar until the option is ticked.
		final CombatVitalsConfig config = new CombatVitalsConfig()
		{
		};
		assertFalse(config.hideGameHealthBar());
	}

	@Test
	public void aSpriteNotReadyIsRetriedAboutOnceASecondNotEveryFrame()
	{
		final int[] builds = {0};
		final NativeHealthBarHider<Object> notReady = new NativeHealthBarHider<>(overrides, id ->
		{
			builds[0]++;
			return null;
		});

		final int frames = NativeHealthBarHider.RETRY_CALLS * 4;
		for (int i = 0; i < frames; i++)
		{
			notReady.apply();
		}

		// Before: every sprite id on every frame, 22 * 200 = 4400 cache reads.
		assertEquals(4 * NativeHealthBarHider.SPRITE_IDS.length, builds[0]);
	}

	@Test
	public void aSpriteThatBecomesReadyIsInstalledOnTheNextRetry()
	{
		final boolean[] ready = {false};
		final NativeHealthBarHider<Object> later = new NativeHealthBarHider<>(overrides,
			id -> ready[0] ? new Object() : null);

		assertFalse(later.apply());
		ready[0] = true;
		for (int i = 1; i < NativeHealthBarHider.RETRY_CALLS; i++)
		{
			assertFalse("waits out the retry", later.apply());
		}
		assertTrue(later.apply());
		assertEquals(NativeHealthBarHider.SPRITE_IDS.length, overrides.size());
	}

	@Test
	public void switchingBackOnRetriesStraightAway()
	{
		final boolean[] ready = {false};
		final NativeHealthBarHider<Object> later = new NativeHealthBarHider<>(overrides,
			id -> ready[0] ? new Object() : null);

		later.apply();
		later.restore();
		ready[0] = true;

		assertTrue(later.apply());
	}

	@Test
	public void installedSpritesAreNotRebuilt()
	{
		final int[] builds = {0};
		final NativeHealthBarHider<Object> counted = new NativeHealthBarHider<>(overrides, id ->
		{
			builds[0]++;
			return new Object();
		});

		for (int i = 0; i < 100; i++)
		{
			counted.apply();
		}

		assertEquals(NativeHealthBarHider.SPRITE_IDS.length, builds[0]);
	}

	@Test
	public void coversEveryStandardBarFrontAndBack()
	{
		// 30, 40, 50, 60, 70, 80, 90, 100, 120, 140, 160: the same 22 ids
		// Interface Styles' HD health bars override.
		assertEquals(22, NativeHealthBarHider.SPRITE_IDS.length);
		assertEquals(22, Arrays.stream(NativeHealthBarHider.SPRITE_IDS).distinct().count());
	}

	@Test
	public void applyInstallsAndRestoreRemovesEverything()
	{
		assertTrue(hider.apply());
		assertTrue(hider.isActive());
		assertEquals(NativeHealthBarHider.SPRITE_IDS.length, overrides.size());

		assertTrue(hider.restore());
		assertFalse(hider.isActive());
		assertTrue(overrides.isEmpty());
	}

	@Test
	public void applyIsIdempotent()
	{
		assertTrue(hider.apply());
		assertFalse(hider.apply());
	}

	@Test
	public void restoreWithoutApplyDoesNothing()
	{
		final Object foreign = new Object();
		overrides.put(FIRST, foreign);

		assertFalse(hider.restore());
		assertSame(foreign, overrides.get(FIRST));
	}

	@Test
	public void restoreHandsBackWhatItDisplaced()
	{
		// Interface Styles' HD bars were there first.
		final Object hd = new Object();
		overrides.put(FIRST, hd);

		hider.apply();
		assertNotSame(hd, overrides.get(FIRST));

		hider.restore();
		assertSame(hd, overrides.get(FIRST));
		assertEquals(1, overrides.size());
	}

	@Test
	public void reassertsAfterAnotherPluginOverwrites()
	{
		hider.apply();
		final Object mine = overrides.get(FIRST);

		// Interface Styles turned HD bars on while ours was active.
		final Object hd = new Object();
		overrides.put(FIRST, hd);

		assertTrue(hider.apply());
		assertSame(mine, overrides.get(FIRST));

		// Turning ours off leaves the HD bar in place.
		hider.restore();
		assertSame(hd, overrides.get(FIRST));
	}

	@Test
	public void forgetsADisplacedSpriteItsOwnerCleared()
	{
		final Object hd = new Object();
		overrides.put(FIRST, hd);
		hider.apply();

		// Interface Styles turned HD bars off: it removes every id, ours too.
		for (int id : NativeHealthBarHider.SPRITE_IDS)
		{
			overrides.remove(id);
		}

		assertTrue(hider.apply());
		hider.restore();

		// The HD sprite must not come back after its owner dropped it.
		assertNull(overrides.get(FIRST));
		assertTrue(overrides.isEmpty());
	}

	@Test
	public void restoreLeavesAnIdSomeoneElseTookOver()
	{
		hider.apply();
		final Object later = new Object();
		overrides.put(FIRST, later);

		hider.restore();
		assertSame(later, overrides.get(FIRST));
	}

	@Test
	public void skipsSpritesThatCannotBeBuiltYet()
	{
		final NativeHealthBarHider<Object> notReady = new NativeHealthBarHider<>(overrides, id -> null);
		assertFalse(notReady.apply());
		assertFalse(notReady.isActive());
		assertTrue(overrides.isEmpty());
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.game.FishingSpot;
import org.junit.Test;

public class NextFishingSpotTest
{
	private static final Object NPC_A = new Object();
	private static final Object NPC_B = new Object();
	private static final Object NPC_C = new Object();

	private static NextFishingSpot.Need need(FishingSpot type, String method, int level, boolean members, Object exclude)
	{
		return new NextFishingSpot.Need(type, method, level, members, exclude);
	}

	private static NextFishingSpot.Need lobsters()
	{
		return need(FishingSpot.LOBSTER, "Cage", 99, true, null);
	}

	@Test
	public void picksTheNearestLoadedSpot()
	{
		final NextFishingSpot.Spot far = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3010, 3000, 0, NPC_A);
		final NextFishingSpot.Spot near = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3003, 3001, 0, NPC_B);

		assertSame(near, NextFishingSpot.nearest(Arrays.asList(far, near), 3000, 3000, 0, lobsters()));
	}

	@Test
	public void tieGoesToTheLowerXThenLowerYWhateverTheSceneOrder()
	{
		// All three are 4 tiles away (Chebyshev).
		final NextFishingSpot.Spot east = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3004, 3000, 0, NPC_A);
		final NextFishingSpot.Spot westHigh = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 2996, 3002, 0, NPC_B);
		final NextFishingSpot.Spot westLow = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 2996, 2997, 0, NPC_C);

		assertSame(westLow, NextFishingSpot.nearest(Arrays.asList(east, westHigh, westLow), 3000, 3000, 0, lobsters()));
		assertSame(westLow, NextFishingSpot.nearest(Arrays.asList(westLow, westHigh, east), 3000, 3000, 0, lobsters()));
	}

	@Test
	public void onlyTheSameSpotType()
	{
		final NextFishingSpot.Spot nets = NextFishingSpot.Spot.loaded(FishingSpot.SHRIMP, 3001, 3000, 0, NPC_A);
		final NextFishingSpot.Spot sharks = NextFishingSpot.Spot.loaded(FishingSpot.SHARK, 3001, 3001, 0, NPC_B);
		final NextFishingSpot.Spot cages = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3020, 3020, 0, NPC_C);

		assertSame(cages, NextFishingSpot.nearest(Arrays.asList(nets, sharks, cages), 3000, 3000, 0, lobsters()));
		assertNull(NextFishingSpot.nearest(Arrays.asList(nets, sharks), 3000, 3000, 0, lobsters()));
	}

	@Test
	public void levelFilterDropsSpotsTheMethodCannotCatchAtThisLevel()
	{
		final NextFishingSpot.Spot spot = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3001, 3000, 0, NPC_A);

		// Harpoon on a cage/harpoon spot starts at tuna, level 35.
		assertNull(NextFishingSpot.nearest(Collections.singletonList(spot), 3000, 3000, 0,
			need(FishingSpot.LOBSTER, "Harpoon", 34, true, null)));
		assertSame(spot, NextFishingSpot.nearest(Collections.singletonList(spot), 3000, 3000, 0,
			need(FishingSpot.LOBSTER, "Harpoon", 35, true, null)));
	}

	@Test
	public void levelFilterHonoursALocationsOwnRequirement()
	{
		final NextFishingSpot.Spot guild = NextFishingSpot.Spot.known(FishingSpot.LOBSTER, 2599, 3419, 0, true, 68, "Fishing Guild");
		final NextFishingSpot.Spot catherby = NextFishingSpot.Spot.known(FishingSpot.LOBSTER, 2844, 3429, 0, true, 0, "Catherby");
		final List<NextFishingSpot.Spot> known = Arrays.asList(guild, catherby);

		assertSame(catherby, NextFishingSpot.nearest(known, 2600, 3420, 0, need(FishingSpot.LOBSTER, "Cage", 67, true, null)));
		assertSame(guild, NextFishingSpot.nearest(known, 2600, 3420, 0, need(FishingSpot.LOBSTER, "Cage", 68, true, null)));
	}

	@Test
	public void freeWorldsOnlyGetFreeLocations()
	{
		final NextFishingSpot.Spot members = NextFishingSpot.Spot.known(FishingSpot.SHRIMP, 3001, 3001, 0, true, 0, "Members");
		final NextFishingSpot.Spot free = NextFishingSpot.Spot.known(FishingSpot.SHRIMP, 3050, 3050, 0, false, 0, "Free");
		final List<NextFishingSpot.Spot> known = Arrays.asList(members, free);

		assertSame(free, NextFishingSpot.nearest(known, 3000, 3000, 0, need(FishingSpot.SHRIMP, "Net", 1, false, null)));
		assertSame(members, NextFishingSpot.nearest(known, 3000, 3000, 0, need(FishingSpot.SHRIMP, "Net", 1, true, null)));
	}

	@Test
	public void theSpotBeingFishedIsNotTheNextOne()
	{
		final NextFishingSpot.Spot current = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3001, 3000, 0, NPC_A);
		final NextFishingSpot.Spot other = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3009, 3000, 0, NPC_B);

		assertSame(other, NextFishingSpot.nearest(Arrays.asList(current, other), 3000, 3000, 0,
			need(FishingSpot.LOBSTER, "Cage", 99, true, NPC_A)));
	}

	@Test
	public void anotherPlaneLosesToAnyOnThisPlane()
	{
		final NextFishingSpot.Spot upstairs = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3000, 3000, 1, NPC_A);
		final NextFishingSpot.Spot across = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3060, 3000, 0, NPC_B);

		assertSame(across, NextFishingSpot.nearest(Arrays.asList(upstairs, across), 3000, 3000, 0, lobsters()));
	}

	@Test
	public void loadedSpotsWinOverTheBundledList()
	{
		final NextFishingSpot.Spot loaded = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3040, 3000, 0, NPC_A);
		final NextFishingSpot.Spot known = NextFishingSpot.Spot.known(FishingSpot.LOBSTER, 3001, 3000, 0, false, 0, "Close");

		assertSame(loaded, NextFishingSpot.choose(Collections.singletonList(loaded), Collections.singletonList(known),
			3000, 3000, 0, lobsters()));
	}

	@Test
	public void noLoadedSpotFallsBackToTheNearestKnownOne()
	{
		final NextFishingSpot.Spot wrongType = NextFishingSpot.Spot.loaded(FishingSpot.SHRIMP, 3001, 3000, 0, NPC_A);
		final NextFishingSpot.Spot near = NextFishingSpot.Spot.known(FishingSpot.LOBSTER, 3100, 3000, 0, false, 0, "Near");
		final NextFishingSpot.Spot far = NextFishingSpot.Spot.known(FishingSpot.LOBSTER, 3300, 3000, 0, false, 0, "Far");

		assertSame(near, NextFishingSpot.choose(Collections.singletonList(wrongType), Arrays.asList(far, near),
			3000, 3000, 0, lobsters()));
	}

	@Test
	public void unknownSpotTypeFindsNothing()
	{
		final NextFishingSpot.Spot spot = NextFishingSpot.Spot.loaded(FishingSpot.LOBSTER, 3001, 3000, 0, NPC_A);

		assertNull(NextFishingSpot.choose(Collections.singletonList(spot), Collections.emptyList(), 3000, 3000, 0,
			need(null, "Cage", 99, true, null)));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.time.Duration;
import java.time.Instant;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * The scenarios from the brief: chopping a tree shows Woodcutting, mining
 * shows Mining, walking away clears it, and combat still wins. Each drives
 * {@link ObjectSkilling} the way the plugin does and forwards its steps to
 * {@link SkillingState}, so the badge decision is tested end to end.
 */
public class ObjectSkillingTest
{
	private static final Duration TIMEOUT = Duration.ofSeconds(5);
	private static final Instant T0 = Instant.parse("2026-11-03T12:00:00Z");

	/** A 1x1 yew at (3200, 3200). */
	private static final int TREE_X = 3200;
	private static final int TREE_Y = 3200;

	private final ObjectSkilling objects = new ObjectSkilling();
	private final SkillingState skilling = new SkillingState();
	private final CombatState combat = new CombatState();

	/** What the plugin does with each step. */
	private void apply(ObjectSkilling.Step step, Instant now)
	{
		switch (step)
		{
			case ENGAGE:
				skilling.engage(objects.skill());
				break;
			case DISENGAGE:
				skilling.disengage(now);
				break;
			case RELEASE:
				skilling.release();
				break;
			default:
				break;
		}
	}

	private void tick(int tick, int x, int y, boolean animating)
	{
		apply(objects.tick(tick, x, y, 0, animating), T0);
	}

	/** The plugin's badge gate: a skill is engaged and no fight has the target. */
	private Skill badge()
	{
		return combat.showTarget() ? null : skilling.skill();
	}

	private void clickTree(int tick)
	{
		objects.clicked(SkillingActions.forOption("Chop down", "Yew tree"), TREE_X, TREE_Y, 0, 1, 1, tick);
	}

	@Test
	public void choppingATreeShowsWoodcutting()
	{
		clickTree(100);
		tick(101, 3195, 3200, false);
		assertNull("still walking over: nothing yet", badge());

		tick(105, TREE_X - 1, TREE_Y, true);
		assertEquals(Skill.WOODCUTTING, badge());
	}

	@Test
	public void miningARockShowsMining()
	{
		objects.clicked(SkillingActions.forOption("Mine", "Iron rocks"), 3300, 3300, 0, 1, 1, 100);
		tick(102, 3300, 3301, true);

		assertEquals(Skill.MINING, badge());
	}

	@Test
	public void aLargeObjectCountsFromItsWholeFootprint()
	{
		// A 2x2 tree: standing east of its far edge is still at the tree.
		objects.clicked(Skill.WOODCUTTING, TREE_X, TREE_Y, 0, 2, 2, 100);
		tick(102, TREE_X + 2, TREE_Y + 1, true);

		assertEquals(Skill.WOODCUTTING, badge());
	}

	@Test
	public void walkingAwayClearsIt()
	{
		clickTree(100);
		tick(102, TREE_X - 1, TREE_Y, true);
		assertEquals(Skill.WOODCUTTING, badge());

		tick(103, TREE_X - 1 - ObjectSkilling.REACH - 1, TREE_Y, false);
		assertNull("walked off: gone at once, no linger", badge());
		assertFalse(objects.held());
	}

	@Test
	public void walkHereClearsItAtOnce()
	{
		clickTree(100);
		tick(102, TREE_X - 1, TREE_Y, true);

		// The plugin's Walk here handler.
		if (objects.started())
		{
			skilling.release();
		}
		objects.forget();

		assertNull(badge());
	}

	@Test
	public void stoppingLingersForTheTimeoutThenExpires()
	{
		clickTree(100);
		tick(102, TREE_X - 1, TREE_Y, true);
		// The tree falls: the animation stops, the player stays put.
		tick(110, TREE_X - 1, TREE_Y, false);
		assertEquals("lingers", Skill.WOODCUTTING, badge());

		assertFalse(skilling.expire(T0.plus(TIMEOUT), TIMEOUT, objects.working()));
		assertTrue(skilling.expire(T0.plus(TIMEOUT).plusMillis(1), TIMEOUT, objects.working()));
		assertNull(badge());
	}

	@Test
	public void swingingAgainCancelsTheLinger()
	{
		clickTree(100);
		tick(102, TREE_X - 1, TREE_Y, true);
		tick(110, TREE_X - 1, TREE_Y, false);
		tick(111, TREE_X - 1, TREE_Y, true);

		assertFalse(skilling.expire(T0.plusSeconds(60), TIMEOUT, objects.working()));
		assertEquals(Skill.WOODCUTTING, badge());
	}

	@Test
	public void animatingAwayFromTheTreeIsNotChopping()
	{
		// Clicked a tree, then drank a potion on the way: no badge.
		clickTree(100);
		tick(101, TREE_X - 10, TREE_Y, true);

		assertNull(badge());
	}

	@Test
	public void aClickThatNeverStartsIsForgotten()
	{
		clickTree(100);
		tick(100 + ObjectSkilling.START_TICKS + 1, TREE_X - 1, TREE_Y, false);
		assertFalse(objects.held());

		tick(100 + ObjectSkilling.START_TICKS + 2, TREE_X - 1, TREE_Y, true);
		assertNull("an unrelated animation later is not chopping", badge());
	}

	@Test
	public void anUnknownOptionHoldsNothing()
	{
		objects.clicked(SkillingActions.forOption("Bank", "Bank booth"), TREE_X, TREE_Y, 0, 1, 1, 100);
		assertFalse(objects.held());
		tick(101, TREE_X - 1, TREE_Y, true);

		assertNull(badge());
	}

	@Test
	public void anotherPlaneIsNotTheTree()
	{
		clickTree(100);
		apply(objects.tick(102, TREE_X - 1, TREE_Y, 1, true), T0);

		assertNull(badge());
	}

	@Test
	public void combatStillWins()
	{
		clickTree(100);
		tick(102, TREE_X - 1, TREE_Y, true);
		assertEquals(Skill.WOODCUTTING, badge());

		// Attacking something: the plugin engages combat, releases the badge
		// and forgets the tree, as it does for a skilling NPC.
		combat.engage(CombatState.attackable(new String[] {"Attack"}, 2));
		skilling.release();
		objects.forget();

		assertTrue(combat.showTarget());
		assertNull(badge());
	}

	@Test
	public void pickpocketingAnAttackableNpcIsThievingUntilAHitLands()
	{
		final String[] man = {"Talk-to", "Attack", "Pickpocket", null, null};
		final Skill clicked = SkillingActions.forOption("Pickpocket", "Man");

		// The plugin: attackable, but the click was Pickpocket, so not a fight.
		combat.engage(CombatState.attackable(man, 2) && clicked == null);
		skilling.engage(clicked);
		assertEquals(Skill.THIEVING, badge());

		// Hitting the Man proves it a fight, and the health bar takes over.
		combat.hit(true, T0);
		assertNull(badge());
		assertTrue(combat.showTarget());
	}

	@Test
	public void attackingAnAttackableNpcIsStillAFight()
	{
		final String[] man = {"Talk-to", "Attack", "Pickpocket", null, null};
		final Skill clicked = SkillingActions.forOption("Attack", "Man");

		combat.engage(CombatState.attackable(man, 2) && clicked == null);
		assertTrue(combat.showTarget());
		assertNull(badge());
	}
}

package com.vinnyvangogh.combatvitals;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class OverheadChatHolderTest
{
	/** Stands in for an actor: the two fields the client keeps for overhead chat. */
	private static final class FakeActor
	{
		String text;
		int cycles;
		int writes;

		/** Called on every write, as the client posts {@code OverheadTextChanged}; null for none. */
		java.util.function.Consumer<String> onWrite;

		FakeActor(String text, int cycles)
		{
			this.text = text;
			this.cycles = cycles;
		}

		/** The game posting a new message. */
		void say(String message)
		{
			text = message;
			cycles = 150;
		}

		/** The game's countdown running. */
		void tick(int n)
		{
			cycles -= n;
		}

		/** What the game draws over this actor right now, if anything. */
		String gameDraws()
		{
			return OverheadChat.showing(text, cycles) ? text : null;
		}
	}

	private static final OverheadChatHolder.Access<FakeActor> ACCESS = new OverheadChatHolder.Access<FakeActor>()
	{
		@Override
		public String text(FakeActor actor)
		{
			return actor.text;
		}

		@Override
		public int cyclesRemaining(FakeActor actor)
		{
			return actor.cycles;
		}

		@Override
		public void setText(FakeActor actor, String text)
		{
			actor.text = text;
			actor.writes++;
			if (actor.onWrite != null)
			{
				actor.onWrite.accept(text);
			}
		}
	};

	private OverheadChatHolder<FakeActor> holder;
	private FakeActor opponent;

	@Before
	public void setUp()
	{
		holder = new OverheadChatHolder<>(ACCESS);
		opponent = new FakeActor("Hello", 150);
	}

	private static Set<FakeActor> covered(FakeActor actor)
	{
		return Collections.singleton(actor);
	}

	@Test
	public void coveredChatIsTakenOffTheGameButKeptForTheCopy()
	{
		holder.update(covered(opponent));

		assertNull(opponent.gameDraws());
		assertEquals("Hello", holder.heldText(opponent));
		assertTrue(holder.isHolding(opponent));
	}

	@Test
	public void countdownIsLeftToTheGame()
	{
		holder.update(covered(opponent));

		// The message lasts as long as the game would have shown it.
		assertEquals(150, opponent.cycles);
	}

	@Test
	public void uncoveredChatIsNeverTouched()
	{
		holder.update(Collections.emptySet());

		assertEquals("Hello", opponent.gameDraws());
		assertEquals(0, opponent.writes);
	}

	@Test
	public void actorWithNoChatIsNeverTouched()
	{
		final FakeActor silent = new FakeActor(null, 0);
		final FakeActor expired = new FakeActor("Old", 0);

		holder.update(covered(silent));
		holder.update(covered(expired));

		assertEquals(0, silent.writes);
		assertEquals(0, expired.writes);
		assertNull(holder.heldText(expired));
	}

	@Test
	public void readoutMovingClearGivesTheLineBackWithItsTimeLeft()
	{
		holder.update(covered(opponent));
		opponent.tick(40);

		holder.update(Collections.emptySet());

		assertEquals("Hello", opponent.gameDraws());
		assertEquals(110, opponent.cycles);
		assertFalse(holder.isHolding(opponent));
	}

	@Test
	public void releaseAllGivesEveryLineBack()
	{
		final FakeActor self = new FakeActor("Hi back", 150);
		holder.update(covered(opponent));
		holder.update(new HashSet<>(Arrays.asList(opponent, self)));

		holder.releaseAll();

		assertEquals("Hello", opponent.gameDraws());
		assertEquals("Hi back", self.gameDraws());
		assertFalse(holder.isHolding(opponent));
		assertFalse(holder.isHolding(self));
	}

	@Test
	public void expiredHoldIsDroppedNotRestored()
	{
		holder.update(covered(opponent));
		opponent.tick(150);

		assertNull(holder.heldText(opponent));
		holder.update(Collections.emptySet());
		holder.releaseAll();

		// Nothing written back: the game would not be showing it any more.
		assertEquals(OverheadChatHolder.BLANK, opponent.text);
		assertNull(opponent.gameDraws());
	}

	@Test
	public void newMessageWinsOverAHeldOne()
	{
		holder.update(covered(opponent));
		opponent.say("Second");

		// No stale copy: the old hold is forgotten, never drawn over the new one.
		assertNull(holder.heldText(opponent));
		assertEquals("Second", opponent.gameDraws());

		// Releasing must not write the old message over the new one.
		holder.releaseAll();
		assertEquals("Second", opponent.gameDraws());
	}

	@Test
	public void newMessageIsHeldInTurnWhileStillCovered()
	{
		holder.update(covered(opponent));
		opponent.say("Second");

		holder.update(covered(opponent));

		assertNull(opponent.gameDraws());
		assertEquals("Second", holder.heldText(opponent));

		holder.update(Collections.emptySet());
		assertEquals("Second", opponent.gameDraws());
	}

	@Test
	public void steadyCoverWritesOnlyOnce()
	{
		holder.update(covered(opponent));
		holder.update(covered(opponent));
		holder.update(covered(opponent));

		assertEquals(1, opponent.writes);
	}

	@Test
	public void releaseAllWithNothingHeldWritesNothing()
	{
		holder.releaseAll();

		assertEquals(0, opponent.writes);
		assertEquals("Hello", opponent.gameDraws());
	}

	@Test
	public void noCopyWithoutAHold()
	{
		// With the option off nothing is held, so the overlay draws no copy
		// and the game's own line is the only one (Board, 2026-11-04: it
		// showed twice).
		assertNull(holder.heldText(opponent));
		assertEquals("Hello", opponent.gameDraws());
	}

	// --- Held at the source: the game's line is blanked inside the text
	// change itself, before any frame can draw it. -------------------------

	/** An actor whose text setter posts the change back, as the client's does. */
	private final class PostingActor
	{
		final FakeActor actor = new FakeActor(null, 0);
		int posts;

		/** Whether the readout covers this actor; the plugin only holds covered actors. */
		boolean covered = true;

		PostingActor()
		{
			actor.onWrite = this::posted;
		}

		/** The game posting a message: text first, then the countdown. */
		void say(String message)
		{
			actor.text = message;
			posted(message);
			actor.cycles = 150;
		}

		void posted(String text)
		{
			posts++;
			if (covered)
			{
				holder.hold(actor, text);
			}
		}
	}

	@Test
	public void messageUnderTheReadoutIsNeverDrawnByTheGame()
	{
		final PostingActor me = new PostingActor();

		me.say("Sup");

		// Straight after the change, before any frame: the game has a blank.
		assertNull(me.actor.gameDraws());
		assertEquals("Sup", holder.heldText(me.actor));
		assertTrue(holder.isHolding(me.actor));
		// The blank posted back once and was ignored, not held in turn.
		assertEquals(2, me.posts);
		assertEquals(1, me.actor.writes);
	}

	@Test
	public void heldAtTheSourceSurvivesTheNextFrameUpdate()
	{
		final PostingActor me = new PostingActor();

		me.say("Sup");
		holder.update(covered(me.actor));

		assertNull(me.actor.gameDraws());
		assertEquals("Sup", holder.heldText(me.actor));
		assertEquals("countdown untouched", 150, me.actor.cycles);
	}

	@Test
	public void secondMessageReplacesTheFirstWithoutAFrameOfEither()
	{
		final PostingActor me = new PostingActor();

		me.say("Sup");
		me.say("Bye");

		assertNull(me.actor.gameDraws());
		assertEquals("Bye", holder.heldText(me.actor));

		// Given back, it is the newest message that returns. The readout has
		// moved off this actor, so the write-back is not held again.
		me.covered = false;
		holder.update(Collections.emptySet());
		assertEquals("Bye", me.actor.gameDraws());
	}

	@Test
	public void heldMessageExpiresWithTheGamesCountdown()
	{
		holder.hold(opponent, "Hello");
		opponent.tick(150);

		assertNull(holder.heldText(opponent));
		holder.update(covered(opponent));
		assertFalse(holder.isHolding(opponent));
	}

	@Test
	public void blankOrEmptyTextIsNeverHeld()
	{
		final FakeActor quiet = new FakeActor(null, 0);
		holder.hold(quiet, null);
		holder.hold(quiet, "");
		holder.hold(quiet, OverheadChatHolder.BLANK);

		assertFalse(holder.isHolding(quiet));
		assertEquals(0, quiet.writes);
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Rectangle;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class OverheadChatTest
{
	/** The readout's box: x 100..160, y 200..216. */
	private static final Rectangle READOUT = new Rectangle(100, 200, 60, 16);
	private static final int DESCENT = 3;

	@Test
	public void chatWithTimeLeftIsShowing()
	{
		assertTrue(OverheadChat.showing("Hello", 150));
		assertTrue(OverheadChat.showing("Hello", 1));
	}

	@Test
	public void expiredChatIsNotShowing()
	{
		// The client keeps the old text after the countdown runs out.
		assertFalse(OverheadChat.showing("Hello", 0));
		assertFalse(OverheadChat.showing("Hello", -5));
	}

	@Test
	public void emptyOrNullTextIsIgnored()
	{
		assertFalse(OverheadChat.showing(null, 150));
		assertFalse(OverheadChat.showing("", 150));
		assertFalse(OverheadChat.showing("   ", 150));
	}

	@Test
	public void coveredChatIsDrawnJustAboveTheReadout()
	{
		// The game's line sits right on the readout.
		final Rectangle chat = new Rectangle(90, 205, 80, 15);

		final Integer baseline = OverheadChat.baselineAbove(READOUT, chat, DESCENT);

		// The copy's bottom edge (baseline + descent) is GAP above the readout.
		assertEquals(READOUT.y - OverheadChat.GAP - DESCENT, (int) baseline);
	}

	@Test
	public void heldChatClearOfTheReadoutStaysWhereTheGameHadIt()
	{
		// The game's line is hidden while held, so the copy is always drawn:
		// above the readout when it covers the line, else in the line's place.
		final Rectangle clear = new Rectangle(90, 150, 80, 15);
		assertEquals(150 + 15 - DESCENT, OverheadChat.baseline(READOUT, clear, DESCENT));

		final Rectangle covered = new Rectangle(90, 205, 80, 15);
		assertEquals(READOUT.y - OverheadChat.GAP - DESCENT, OverheadChat.baseline(READOUT, covered, DESCENT));
	}

	@Test
	public void partlyCoveredChatIsStillRedrawn()
	{
		// One pixel row of overlap is enough to mangle the line.
		final Rectangle chat = new Rectangle(90, 186, 80, 15);

		assertEquals(READOUT.y - OverheadChat.GAP - DESCENT, (int) OverheadChat.baselineAbove(READOUT, chat, DESCENT));
	}

	@Test
	public void chatClearOfTheReadoutIsLeftToTheGame()
	{
		// Above, below, or off to the side: the game's own line is readable,
		// and a copy would show the same message twice.
		assertNull(OverheadChat.baselineAbove(READOUT, new Rectangle(90, 150, 80, 15), DESCENT));
		assertNull(OverheadChat.baselineAbove(READOUT, new Rectangle(90, 230, 80, 15), DESCENT));
		assertNull(OverheadChat.baselineAbove(READOUT, new Rectangle(300, 205, 80, 15), DESCENT));
	}

	@Test
	public void skillingBadgeLiftsChatClearOfItsWholeBox()
	{
		// The badge's box is taller than a text line (the skill icon) and wider
		// (icon plus gap); the chat copy must clear the whole box, not the text.
		final Rectangle badge = new Rectangle(90, 196, 90, 24);
		final Rectangle chat = new Rectangle(100, 205, 60, 15);

		final Integer baseline = OverheadChat.baselineAbove(badge, chat, DESCENT);

		assertEquals(badge.y - OverheadChat.GAP - DESCENT, (int) baseline);
		// The copy's bottom edge sits above the badge's top: no overlap.
		assertTrue(baseline + DESCENT < badge.y);
	}

	@Test
	public void badgeStackedOnTheBarLiftsChatClearOfBoth()
	{
		// Hit while fishing: your own bar at the anchor, the badge stacked
		// above it. The one chat copy goes above the whole stack, so it
		// overlaps neither box and the message is not drawn twice.
		final Rectangle bar = new Rectangle(100, 200, 60, 16);
		final Rectangle badge = new Rectangle(90, 200 - OverheadStack.liftAbove(bar), 90, 24);
		final Rectangle chat = new Rectangle(100, 205, 60, 15);

		final Integer baseline = OverheadChat.baselineAbove(OverheadStack.union(bar, badge), chat, DESCENT);

		assertEquals(badge.y - OverheadChat.GAP - DESCENT, (int) baseline);
		assertTrue(baseline + DESCENT < badge.y);
		assertTrue(baseline + DESCENT < bar.y);
	}

	@Test
	public void readoutPositionIsNeverChanged()
	{
		final Rectangle readout = new Rectangle(READOUT);

		OverheadChat.baselineAbove(readout, new Rectangle(90, 205, 80, 15), DESCENT);

		assertEquals(READOUT, readout);
	}
}

