package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import java.awt.Rectangle;
import org.junit.Test;

/**
 * The badge and your own health bar both sit over your head. When both are
 * up the badge moves above the bar, and the overhead chat copy (RUNELITE-29)
 * goes above whichever is topmost.
 */
public class OverheadStackTest
{
	@Test
	public void nothingBelowMeansNoLift()
	{
		assertEquals(0, OverheadStack.liftAbove(null));
	}

	@Test
	public void theBadgeClearsTheBarAndTheGap()
	{
		final Rectangle bar = new Rectangle(100, 200, 60, 16);
		assertEquals(16 + OverheadStack.GAP, OverheadStack.liftAbove(bar));
	}

	@Test
	public void twoBoxesStackedDoNotOverlap()
	{
		final Rectangle bar = new Rectangle(100, 200, 60, 16);
		final int lift = OverheadStack.liftAbove(bar);
		final Rectangle badge = new Rectangle(90, 200 - lift, 80, 16);

		assertEquals("badge bottom sits GAP above the bar top", bar.y - OverheadStack.GAP, badge.y + badge.height);
		assertEquals(false, badge.intersects(bar));
	}

	@Test
	public void topmostIsTheUnionForTheChatCopy()
	{
		final Rectangle bar = new Rectangle(100, 200, 60, 16);
		final Rectangle badge = new Rectangle(90, 180, 80, 16);
		final Rectangle union = OverheadStack.union(bar, badge);

		assertEquals(new Rectangle(90, 180, 80, 36), union);
		assertEquals("one box alone is itself", bar, OverheadStack.union(bar, null));
		assertEquals(badge, OverheadStack.union(null, badge));
		assertEquals(null, OverheadStack.union(null, null));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The pillar fill glides to a new value rather than jumping, and never lags a reset. */
public class PillarAnimationTest
{
	@Test
	public void theFirstValueIsShownAtOnce()
	{
		final PillarAnimation a = new PillarAnimation();
		assertEquals(0.4, a.next(0.4, 1_000), 0);
	}

	@Test
	public void aRiseGlidesThereWithinTheDuration()
	{
		final PillarAnimation a = new PillarAnimation();
		a.next(0.2, 0);
		final double early = a.next(0.6, 50);
		assertTrue("moved: " + early, early > 0.2);
		assertTrue("not there yet: " + early, early < 0.6);
		final double later = a.next(0.6, 150);
		assertTrue("closer: " + later, later > early);
		assertEquals(0.6, a.next(0.6, 50 + PillarAnimation.DURATION_MILLIS * 3), 0);
	}

	@Test
	public void aSmallFallGlidesToo()
	{
		final PillarAnimation a = new PillarAnimation();
		a.next(0.6, 0);
		final double v = a.next(0.5, 50);
		assertTrue(v < 0.6 && v > 0.5);
	}

	@Test
	public void aLevelUpOrABankEmptyingSnaps()
	{
		final PillarAnimation a = new PillarAnimation();
		a.next(0.98, 0);
		assertEquals(0.03, a.next(0.03, 16), 0);
	}

	@Test
	public void aLongPauseSnaps()
	{
		final PillarAnimation a = new PillarAnimation();
		a.next(0.1, 0);
		assertEquals(0.9, a.next(0.9, 60_000), 0);
	}

	@Test
	public void resetForgetsTheLastValue()
	{
		final PillarAnimation a = new PillarAnimation();
		a.next(0.1, 0);
		a.reset();
		assertEquals(0.7, a.next(0.7, 10), 0);
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import org.junit.Test;

/**
 * Paints each pillar state headless and checks the pixels: labels on and
 * off, the idle dim, the Status Bars shine and the slot ticks. The images
 * go to build/pillar-renders for the PR and a look by eye.
 */
public class PillarRenderTest
{
	private static final File OUT = new File("build/pillar-renders");
	private static final Rectangle BOX = new Rectangle(4, 4, SidePillars.WIDTH, SidePillars.HEIGHT);
	private static final Color FISHING = SkillColours.of(Skill.FISHING);
	private static final SkillIconManager ICONS = new SkillIconManager();

	private static Pillar xp(double fraction, boolean idle)
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(16)
			+ (int) ((Experience.getXpForLevel(17) - Experience.getXpForLevel(16)) * fraction));
		return Pillar.builder()
			.fraction(p.getFraction())
			.colour(FISHING)
			.icon(ICONS.getSkillImage(Skill.FISHING, true))
			.number(PillarText.xpNumber(p, XpDisplay.PERCENT))
			.bottom(PillarText.xpBottom(p))
			.divisions(4)
			.idle(idle)
			.build();
	}

	private static Pillar inventory(int empty, boolean idle)
	{
		final double fill = InventoryFill.fraction(InventoryFill.SLOTS - empty, empty);
		return Pillar.builder()
			.fraction(fill)
			.colour(InventoryFill.colour(fill, Color.GREEN, Color.YELLOW, Color.RED))
			.icon(PillarIcons.backpack())
			.number(PillarText.inventoryNumber(empty, InventoryCount.FREE))
			.divisions(InventoryFill.SLOTS)
			.idle(idle)
			.build();
	}

	private static Pillar target(int hp, int max)
	{
		final double f = (double) hp / max;
		return Pillar.builder()
			.fraction(f)
			.colour(HealthReadout.colour(f, Color.GREEN, Color.YELLOW, Color.RED))
			.icon(ICONS.getSkillImage(Skill.HITPOINTS, true))
			.number(PillarText.targetNumber(hp, f))
			.divisions(1)
			.build();
	}

	private static BufferedImage render(Pillar pillar, PillarStyle style, PillarLabels labels)
	{
		final BufferedImage image = new BufferedImage(BOX.width + 8, BOX.height + 8, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			PillarPainter.paint(g, BOX, pillar, style, labels, new Color(0, 0, 0, 150));
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	@Test
	public void writesEveryStateForThePr() throws IOException
	{
		assertTrue(OUT.isDirectory() || OUT.mkdirs());
		final Object[][] states = {
			{"xp-82", xp(0.82, false), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER},
			{"xp-idle", xp(0.82, true), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER},
			{"xp-icon-only", xp(0.40, false), PillarStyle.STATUS_BARS, PillarLabels.ICON_ONLY},
			{"xp-no-labels", xp(0.40, false), PillarStyle.STATUS_BARS, PillarLabels.NONE},
			{"xp-flat", xp(0.82, false), PillarStyle.FLAT, PillarLabels.ICON_AND_NUMBER},
			{"inv-18-free", inventory(18, false), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER},
			{"inv-3-free", inventory(3, false), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER},
			{"inv-idle", inventory(18, true), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER},
			{"target-12-of-50", target(12, 50), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER},
		};

		final BufferedImage sheet = new BufferedImage(states.length * 40 + 8, BOX.height + 16,
			BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = sheet.createGraphics();
		g.setColor(new Color(62, 53, 41));
		g.fillRect(0, 0, sheet.getWidth(), sheet.getHeight());
		for (int i = 0; i < states.length; i++)
		{
			final BufferedImage one = render((Pillar) states[i][1], (PillarStyle) states[i][2],
				(PillarLabels) states[i][3]);
			ImageIO.write(one, "png", new File(OUT, states[i][0] + ".png"));
			g.drawImage(one, 8 + i * 40, 4, null);
		}
		g.dispose();
		ImageIO.write(scaled(sheet, 2), "png", new File(OUT, "pillars-sheet.png"));
		assertTrue(new File(OUT, "pillars-sheet.png").isFile());
	}

	@Test
	public void labelsDrawTheIconAndTheNumberAtTheTop()
	{
		final BufferedImage on = render(xp(0, false), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER);
		assertTrue("white number under the icon", bright(on, BOX.y + 22, BOX.y + 40));
		assertTrue("icon at the top", drawn(on, BOX.y + 2, BOX.y + 20));
		assertTrue("level at the foot", bright(on, BOX.y + BOX.height - 14, BOX.y + BOX.height - 2));
	}

	@Test
	public void numbersStayInsideThePillar()
	{
		final Pillar[] widest = {
			xp(0.82, false),
			xp(0.82, false).toBuilder().number("100%").build(),
			xp(0.82, false).toBuilder().number("Max").build(),
			xp(0.82, false).toBuilder().number("999k").build(),
			target(12, 50).toBuilder().number("255").build(),
		};
		for (Pillar pillar : widest)
		{
			final BufferedImage image = render(pillar, PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER);
			for (int y = 0; y < image.getHeight(); y++)
			{
				for (int x = 0; x < image.getWidth(); x++)
				{
					final boolean outside = x < BOX.x || x >= BOX.x + BOX.width;
					assertFalse(pillar.getNumber() + " spills out at " + x + "," + y,
						outside && new Color(image.getRGB(x, y), true).getAlpha() > 0);
				}
			}
		}
	}

	/** Dropping the sign of a percent too wide for the bar made "82%" paint exactly as "82". */
	@Test
	public void aWidePercentKeepsItsSignWhenDrawn()
	{
		final Pillar withSign = xp(0, false).toBuilder().number("82%").build();
		final Pillar withoutSign = xp(0, false).toBuilder().number("82").build();
		assertFalse(same(render(withSign, PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER),
			render(withoutSign, PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER)));
	}

	@Test
	public void onlyALabelTooWideForTheBarIsCondensed()
	{
		assertEquals(1.0, PillarPainter.labelScale(15, 18), 0);
		assertEquals(1.0, PillarPainter.labelScale(18, 18), 0);
		assertEquals(0.75, PillarPainter.labelScale(24, 18), 1e-9);
	}

	@Test
	public void theTargetCarriesTheHeart()
	{
		final BufferedImage on = render(target(12, 50), PillarStyle.STATUS_BARS, PillarLabels.ICON_AND_NUMBER);
		assertTrue("red heart at the top", coloured(on, BOX.y + 2, BOX.y + 20));
		assertTrue("hitpoints under it", bright(on, BOX.y + 22, BOX.y + 40));
	}

	@Test
	public void iconOnlyHasNoNumber()
	{
		final BufferedImage icon = render(xp(0, false), PillarStyle.STATUS_BARS, PillarLabels.ICON_ONLY);
		assertTrue(drawn(icon, BOX.y + 2, BOX.y + 20));
		assertFalse(bright(icon, BOX.y + 24, BOX.y + BOX.height - 2));
	}

	@Test
	public void labelsOffDrawsNothingButTheBar()
	{
		final BufferedImage off = render(xp(0, false), PillarStyle.STATUS_BARS, PillarLabels.NONE);
		assertFalse(bright(off, BOX.y + 2, BOX.y + BOX.height - 2));
		assertFalse(drawn(off, BOX.y + 2, BOX.y + BOX.height - 2));
	}

	@Test
	public void idleDimsThePillar()
	{
		final int y = BOX.y + BOX.height - 20;
		final int x = BOX.x + BOX.width / 2;
		final int active = new Color(render(xp(0.82, false), PillarStyle.STATUS_BARS, PillarLabels.NONE)
			.getRGB(x, y), true).getAlpha();
		final int idle = new Color(render(xp(0.82, true), PillarStyle.STATUS_BARS, PillarLabels.NONE)
			.getRGB(x, y), true).getAlpha();
		assertTrue("idle " + idle + " < active " + active, idle < active * 0.7);
	}

	@Test
	public void statusBarsStyleShinesOnTheLeft()
	{
		final BufferedImage image = render(xp(0.82, false), PillarStyle.STATUS_BARS, PillarLabels.NONE);
		final int y = BOX.y + BOX.height - 30;
		assertTrue(luma(image.getRGB(BOX.x + 3, y)) > luma(image.getRGB(BOX.x + BOX.width - 3, y)));
	}

	@Test
	public void flatStyleIsOneColour()
	{
		final BufferedImage image = render(xp(0.82, false), PillarStyle.FLAT, PillarLabels.NONE);
		final int y = BOX.y + BOX.height - 30;
		assertTrue(image.getRGB(BOX.x + 3, y) == image.getRGB(BOX.x + BOX.width - 3, y));
	}

	@Test
	public void inventoryShowsSlotTicks()
	{
		final BufferedImage image = render(inventory(0, false), PillarStyle.STATUS_BARS, PillarLabels.NONE);
		final int[] ticks = PillarText.ticks(BOX.y + 1, BOX.height - 2, InventoryFill.SLOTS);
		final int x = BOX.x + BOX.width / 2;
		final int tick = luma(image.getRGB(x, ticks[20]));
		final int between = luma(image.getRGB(x, ticks[20] + 4));
		assertTrue("tick " + tick + " darker than slot " + between, tick < between);
	}

	@Test
	public void theBackpackIconIsDrawn()
	{
		final BufferedImage bag = PillarIcons.backpack();
		assertNotNull(bag);
		assertTrue(bag.getWidth() <= SidePillars.WIDTH);
		assertTrue(coloured(bag, 0, bag.getHeight()));
	}

	private static boolean same(BufferedImage a, BufferedImage b)
	{
		for (int y = 0; y < a.getHeight(); y++)
		{
			for (int x = 0; x < a.getWidth(); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y))
				{
					return false;
				}
			}
		}
		return true;
	}

	/** Any near-white pixel in these rows. */
	private static boolean bright(BufferedImage image, int fromY, int toY)
	{
		return any(image, fromY, toY, c -> c.getAlpha() > 100 && c.getRed() > 200 && c.getGreen() > 200
			&& c.getBlue() > 200);
	}

	/**
	 * Any opaque pixel lighter than the black frame: an icon. The small
	 * fishing icon is grey, so colour alone would miss it.
	 */
	private static boolean drawn(BufferedImage image, int fromY, int toY)
	{
		return any(image, fromY, toY, c -> c.getAlpha() > 200
			&& Math.max(c.getRed(), Math.max(c.getGreen(), c.getBlue())) > 60);
	}

	/** Any opaque pixel that is neither grey nor black. */
	private static boolean coloured(BufferedImage image, int fromY, int toY)
	{
		return any(image, fromY, toY, c -> c.getAlpha() > 150
			&& Math.max(c.getRed(), Math.max(c.getGreen(), c.getBlue()))
			- Math.min(c.getRed(), Math.min(c.getGreen(), c.getBlue())) > 60);
	}

	private static boolean any(BufferedImage image, int fromY, int toY, java.util.function.Predicate<Color> test)
	{
		for (int y = Math.max(0, fromY); y < Math.min(image.getHeight(), toY); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (test.test(new Color(image.getRGB(x, y), true)))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static int luma(int argb)
	{
		final Color c = new Color(argb, true);
		return c.getRed() * 3 + c.getGreen() * 6 + c.getBlue();
	}

	private static BufferedImage scaled(BufferedImage image, int factor)
	{
		final BufferedImage out = new BufferedImage(image.getWidth() * factor, image.getHeight() * factor,
			BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(image, 0, 0, out.getWidth(), out.getHeight(), null);
		g.dispose();
		return out;
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import net.runelite.api.Experience;
import org.junit.Test;

/** What each pillar says: the number under its icon, its hover text, its tick marks and its colours. */
public class PillarTextTest
{
	/** 82% of the way from 16 to 17, 65 xp short is not 82%, so pick the XP to make both true. */
	private static XpProgress fishing16()
	{
		final int from = Experience.getXpForLevel(16);
		final int to = Experience.getXpForLevel(17);
		return XpProgress.of(from + (int) Math.ceil((to - from) * 0.82));
	}

	@Test
	public void xpNumberFollowsTheXpDisplaySetting()
	{
		final XpProgress p = fishing16();
		assertEquals("82%", PillarText.xpNumber(p, XpDisplay.PERCENT));
		assertEquals("82%", PillarText.xpNumber(p, XpDisplay.BOTH));
		assertEquals(Integer.toString(p.getXpLeft()), PillarText.xpNumber(p, XpDisplay.XP_LEFT));
	}

	/**
	 * Board, 2026-11-09: every skill's XP pillar reads a percent, "3%" and
	 * "82%" alike. The screenshots of 2026-11-06 showed "3%" beside "82"
	 * because only a wide percentage lost its sign when drawn.
	 */
	@Test
	public void xpPercentKeepsItsSignAtEveryValue()
	{
		for (int level : new int[]{2, 16, 40, 60, 98})
		{
			final int from = Experience.getXpForLevel(level);
			final int to = Experience.getXpForLevel(level + 1);
			for (double share : new double[]{0.03, 0.5, 0.82})
			{
				final String number = PillarText.xpNumber(XpProgress.of(from + (int) ((to - from) * share)),
					XpDisplay.PERCENT);
				assertTrue(number, number.matches("\\d{1,2}%"));
			}
		}
	}

	@Test
	public void xpLeftIsShortenedToFitThePillar()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(60));
		assertEquals(PillarText.compact(p.getXpLeft()), PillarText.xpNumber(p, XpDisplay.XP_LEFT));
		assertTrue(PillarText.xpNumber(p, XpDisplay.XP_LEFT).length() <= 4);
	}

	@Test
	public void compactNumbersAreFourCharactersAtMost()
	{
		assertEquals("65", PillarText.compact(65));
		assertEquals("1.2k", PillarText.compact(1_234));
		assertEquals("10k", PillarText.compact(9_999));
		assertEquals("29k", PillarText.compact(28_546));
		assertEquals("999k", PillarText.compact(999_400));
		assertEquals("1m", PillarText.compact(999_600));
		assertEquals("1.2m", PillarText.compact(1_234_567));
		assertEquals("13m", PillarText.compact(13_034_431));
		assertEquals("200m", PillarText.compact(200_000_000));
		for (long n = 1; n <= 200_000_000; n = n * 3 + 7)
		{
			assertTrue(n + " -> " + PillarText.compact(n), PillarText.compact(n).length() <= 4);
		}
	}

	@Test
	public void xpNumberAt200mIsMax()
	{
		assertEquals("Max", PillarText.xpNumber(XpProgress.of(Experience.MAX_SKILL_XP), XpDisplay.PERCENT));
		assertEquals("Max", PillarText.xpNumber(XpProgress.of(Experience.MAX_SKILL_XP), XpDisplay.XP_LEFT));
	}

	@Test
	public void xpLevelBoundaries()
	{
		assertEquals("16", PillarText.xpBottom(fishing16()));
		assertEquals("99", PillarText.xpBottom(XpProgress.of(Experience.getXpForLevel(99))));
	}

	@Test
	public void inventoryNumberIsFreeOrUsed()
	{
		assertEquals("18", PillarText.inventoryNumber(18, InventoryCount.FREE));
		assertEquals("10", PillarText.inventoryNumber(18, InventoryCount.USED));
		assertEquals("0", PillarText.inventoryNumber(0, InventoryCount.FREE));
		assertNull(PillarText.inventoryNumber(-1, InventoryCount.FREE));
	}

	@Test
	public void targetNumberIsItsHitpointsOrElseThePercent()
	{
		assertEquals("12", PillarText.targetNumber(12, 0.24));
		assertEquals("0", PillarText.targetNumber(0, 0));
		assertEquals("82%", PillarText.targetNumber(-1, 0.82));
	}

	@Test
	public void targetHitpointsExactOrUnknown()
	{
		assertEquals(12, PillarText.targetHp(12, null, 50));
		assertEquals(-1, PillarText.targetHp(-1, null, 50));
		assertEquals(-1, PillarText.targetHp(-1, null, 0));
	}

	@Test
	public void tooltips()
	{
		final XpProgress p = fishing16();
		assertEquals("Fishing XP: 82% to level 17 (" + String.format("%,d", p.getXpLeft()) + " xp left)",
			PillarText.xpTooltip("Fishing", p));
		assertEquals("Inventory: 10 of 28 free", PillarText.inventoryTooltip(10, InventoryCount.FREE));
		assertEquals("Inventory: 18 of 28 used", PillarText.inventoryTooltip(10, InventoryCount.USED));
		assertNull(PillarText.inventoryTooltip(-1, InventoryCount.FREE));
		assertEquals("Target: Rock Crab 12/50", PillarText.targetTooltip("Rock Crab", 12, 50, 0.24));
		assertEquals("Target: Goblin 82%", PillarText.targetTooltip("Goblin", -1, 0, 0.82));
	}

	@Test
	public void xpTooltipPast99()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(99) + 1000);
		assertEquals("Fishing XP: 0% to 200m (" + String.format("%,d", p.getXpLeft()) + " xp left)",
			PillarText.xpTooltip("Fishing", p));
		assertEquals("Fishing XP: 200m", PillarText.xpTooltip("Fishing", XpProgress.of(Experience.MAX_SKILL_XP)));
	}

	@Test
	public void inventoryTicksMarkEveryOneOf28Slots()
	{
		final int[] ticks = PillarText.ticks(10, 252, InventoryFill.SLOTS);
		assertEquals(27, ticks.length);
		assertEquals(10 + 9, ticks[0]);
		assertEquals(10 + 126, ticks[13]);
		assertEquals(10 + 243, ticks[26]);
		for (int i = 1; i < ticks.length; i++)
		{
			final int gap = ticks[i] - ticks[i - 1];
			assertTrue("slot " + i + " gap " + gap, gap == 9);
		}
	}

	@Test
	public void xpTicksMarkEveryQuarter()
	{
		assertArrayEquals(new int[]{63, 126, 189}, PillarText.ticks(0, 252, 4));
		assertArrayEquals(new int[]{68, 136, 204}, PillarText.ticks(0, 272, 4));
	}

	@Test
	public void noTicksForOneDivisionOrNoRoom()
	{
		assertEquals(0, PillarText.ticks(0, 252, 1).length);
		assertEquals(0, PillarText.ticks(0, 0, 4).length);
	}

	@Test
	public void inventoryRampRunsGreenYellowRed()
	{
		final Color green = Color.GREEN;
		final Color yellow = Color.YELLOW;
		final Color red = Color.RED;
		assertEquals(green, InventoryFill.colour(0, green, yellow, red));
		assertEquals(yellow, InventoryFill.colour(0.5, green, yellow, red));
		assertEquals(red, InventoryFill.colour(1, green, yellow, red));
		final Color quarter = InventoryFill.colour(0.25, green, yellow, red);
		assertTrue(quarter.getRed() > 0 && quarter.getRed() < 255 && quarter.getGreen() == 255);
	}

	@Test
	public void labelsModes()
	{
		assertTrue(PillarLabels.ICON_AND_NUMBER.icon() && PillarLabels.ICON_AND_NUMBER.number());
		assertTrue(PillarLabels.ICON_ONLY.icon());
		assertFalse(PillarLabels.ICON_ONLY.number());
		assertFalse(PillarLabels.NONE.icon() || PillarLabels.NONE.number());
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class SessionColumnsTest
{
	/** "[fish] 24 caught in 3m", "10.6k xp/h", "459 fish/h", "lvl 18 in 6m", padding included. */
	private static final int[] EVERY_STAT = {96, 58, 60, 70};

	@Test
	public void columnsAreSizedToTheirOwnCellNotTheWidest()
	{
		final int[][] lines = SessionColumns.lines(EVERY_STAT.length, true, false);

		assertEquals(1, lines.length);
		// The old layout made every column the widest's 96: 384 wide.
		assertEquals(284, SessionColumns.width(EVERY_STAT, lines));
	}

	@Test
	public void fullPutsTheCountOnItsOwnLineAndTheRatesUnderIt()
	{
		final int[][] lines = SessionColumns.lines(EVERY_STAT.length, true, true);

		assertEquals(2, lines.length);
		assertArrayEquals(new int[]{0, 1}, lines[0]);
		assertArrayEquals(new int[]{1, 4}, lines[1]);
		assertEquals("the rates line is the wider", 188, SessionColumns.width(EVERY_STAT, lines));
	}

	/**
	 * Board's screenshots, 2026-11-06: woodcutting and thieving put "xp/h" on
	 * its own line and mining and fishing did not, because the old rule
	 * wrapped by width. The split no longer looks at any width, so it is
	 * the same for every skill.
	 */
	@Test
	public void theSplitIsTheSameWhateverTheWidths()
	{
		for (int cells = 2; cells <= 4; cells++)
		{
			final int[][] lines = SessionColumns.lines(cells, true, true);
			assertEquals(2, lines.length);
			assertArrayEquals(new int[]{0, 1}, lines[0]);
			assertArrayEquals(new int[]{1, cells}, lines[1]);
		}
	}

	@Test
	public void theCountAloneIsOneLine()
	{
		final int[][] lines = SessionColumns.lines(1, true, true);

		assertEquals(1, lines.length);
		assertArrayEquals(new int[]{0, 1}, lines[0]);
	}

	@Test
	public void ratesWithoutTheCountStayOnOneLine()
	{
		final int[][] lines = SessionColumns.lines(3, false, true);

		assertEquals(1, lines.length);
		assertArrayEquals(new int[]{0, 3}, lines[0]);
	}

	@Test
	public void compactNeverWraps()
	{
		final int[][] lines = SessionColumns.lines(EVERY_STAT.length, true, false);

		assertEquals(1, lines.length);
		assertArrayEquals(new int[]{0, 4}, lines[0]);
	}

	@Test
	public void noCellsIsOneEmptyLine()
	{
		final int[][] lines = SessionColumns.lines(0, false, true);

		assertEquals(1, lines.length);
		assertEquals(0, SessionColumns.width(new int[0], lines));
		assertEquals(0, SessionColumns.fit(new int[0], lines[0], 100).length);
	}

	@Test
	public void spareWidthIsSharedEvenlyLeftoverToTheLeft()
	{
		final int[] columns = SessionColumns.fit(new int[]{10, 20, 30}, new int[]{0, 3}, 65);

		assertArrayEquals(new int[]{12, 22, 31}, columns);
		assertEquals(65, columns[0] + columns[1] + columns[2]);
	}

	@Test
	public void aLineAlreadyFullIsNotShrunk()
	{
		assertArrayEquals(new int[]{58, 60}, SessionColumns.fit(EVERY_STAT, new int[]{1, 3}, 50));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import javax.imageio.ImageIO;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * Board's screenshots and test run, 2026-11-06: the Thieving icon vanished on
 * the session row, and no brightness threshold could pick it out from Mining
 * or Fishing. So every skill's icon gets the same light backing.
 */
public class SessionIconTest
{
	/** The session row's darkest look: a near-black bar. */
	private static final Color ROW = new Color(20, 20, 20);

	private static final int X = 5;
	private static final int TOP = 4;
	private static final int WIDTH = 11;

	/** The row with one session icon drawn on it. */
	private static BufferedImage drawn(BufferedImage icon)
	{
		final BufferedImage row = new BufferedImage(30, 20, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = row.createGraphics();
		g.setColor(ROW);
		g.fillRect(0, 0, row.getWidth(), row.getHeight());
		SkillingBadgeRenderer.drawSessionIcon(g, icon, X, TOP, WIDTH);
		g.dispose();
		return row;
	}

	/** The backing's left edge, beside the icon, halfway down. */
	private static int backing(BufferedImage row)
	{
		return row.getRGB(X - 1, TOP + 5);
	}

	@Test
	public void theBackingIsLighterThanTheRow()
	{
		final BufferedImage row = drawn(new BufferedImage(12, 12, BufferedImage.TYPE_INT_ARGB));
		final Color behind = new Color(backing(row));
		assertTrue("backing " + behind + " lighter than the row", behind.getRed() > ROW.getRed() + 60);
		assertEquals("nothing drawn outside the backing", ROW.getRGB(), row.getRGB(X - 3, TOP + 5));
	}

	/** Every skill the badge shows, Thieving's near-black mask included, gets the one same backing. */
	@Test
	public void everyBadgeSkillIconGetsTheSameBacking() throws Exception
	{
		final int expected = backing(drawn(icon(Skill.THIEVING)));
		for (Skill skill : new Skill[]{
			Skill.FISHING, Skill.WOODCUTTING, Skill.MINING, Skill.THIEVING, Skill.RUNECRAFT, Skill.HUNTER,
		})
		{
			assertEquals(skill.getName(), expected, backing(drawn(icon(skill))));
		}
	}

	/** The icon SkillIconManager.getSkillImage(skill, true) loads: the client jar's /skill_icons_small/ resource. */
	private static BufferedImage icon(Skill skill) throws Exception
	{
		try (InputStream in = net.runelite.client.game.SkillIconManager.class
			.getResourceAsStream("/skill_icons_small/" + skill.getName().toLowerCase() + ".png"))
		{
			assertNotNull("no bundled icon for " + skill, in);
			return ImageIO.read(in);
		}
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

/** The session row's cells: count and timer, short rates with the action's noun, time to level. */
public class SessionRowTest
{
	private static final long MINUTE = 60_000;

	@Test
	public void shortNumbers()
	{
		assertEquals("0", SessionRow.shortNumber(0));
		assertEquals("459", SessionRow.shortNumber(459));
		assertEquals("999", SessionRow.shortNumber(999));
		assertEquals("1k", SessionRow.shortNumber(1_000));
		assertEquals("1.2k", SessionRow.shortNumber(1_234));
		assertEquals("10.6k", SessionRow.shortNumber(10_597));
		assertEquals("10k", SessionRow.shortNumber(10_000));
		assertEquals("100k", SessionRow.shortNumber(99_960));
		assertEquals("125k", SessionRow.shortNumber(125_400));
		assertEquals("999k", SessionRow.shortNumber(999_400));
		assertEquals("1m", SessionRow.shortNumber(999_500));
		assertEquals("1m", SessionRow.shortNumber(999_950));
		assertEquals("1.2m", SessionRow.shortNumber(1_234_567));
		assertEquals("200m", SessionRow.shortNumber(200_000_000));
	}

	@Test
	public void countSaysWhatWasDoneAndForHowLong()
	{
		assertEquals("24 caught in 3m", SessionRow.count(Skill.FISHING, 24, 3 * MINUTE + 10_000));
		assertEquals("3 chopped in 45s", SessionRow.count(Skill.WOODCUTTING, 3, 45_000));
		assertEquals("7 mined in 1h 05m", SessionRow.count(Skill.MINING, 7, 65 * MINUTE));
		assertEquals("2 stolen in 0s", SessionRow.count(Skill.THIEVING, 2, 0));
		assertEquals("0 caught", SessionRow.count(Skill.HUNTER, 0, -1));
		assertEquals("5 crafted in 2m", SessionRow.count(Skill.RUNECRAFT, 5, 2 * MINUTE));
		assertEquals("1 done in 1m", SessionRow.count(Skill.COOKING, 1, MINUTE));
	}

	@Test
	public void ratesAreShortAndNameTheAction()
	{
		assertEquals("10.6k xp/h", SessionRow.xpRate(10_597));
		assertNull("nothing until a rate exists, not \"-- xp/h\"", SessionRow.xpRate(-1));
		assertEquals("459 fish/h", SessionRow.actionRate(Skill.FISHING, 459));
		assertEquals("1.2k logs/h", SessionRow.actionRate(Skill.WOODCUTTING, 1_200));
		assertEquals("300 ores/h", SessionRow.actionRate(Skill.MINING, 300));
		assertEquals("900 steals/h", SessionRow.actionRate(Skill.THIEVING, 900));
		assertEquals("40 catches/h", SessionRow.actionRate(Skill.HUNTER, 40));
		assertEquals("60 crafts/h", SessionRow.actionRate(Skill.RUNECRAFT, 60));
		assertNull(SessionRow.actionRate(Skill.FISHING, -1));
	}

	@Test
	public void timeToLevel()
	{
		// 65 xp left at 10,597 xp/h is 22 seconds.
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(17) - 65);
		assertEquals("lvl 17 in 22s", SessionRow.timeToLevel(p, 10_597));

		// 6,000 xp left at 60,000 xp/h is 6 minutes.
		final XpProgress q = XpProgress.of(Experience.getXpForLevel(61) - 6_000);
		assertEquals("lvl 61 in 6m", SessionRow.timeToLevel(q, 60_000));

		final XpProgress far = XpProgress.of(Experience.getXpForLevel(60));
		assertEquals("lvl 61 in 2h 18m",
			SessionRow.timeToLevel(far, (int) (far.getXpLeft() * 60L / 138)));
	}

	@Test
	public void timeToLevelNeedsARateAndALevel()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(17) - 65);
		assertNull("no rate yet", SessionRow.timeToLevel(p, -1));
		assertNull("zero rate", SessionRow.timeToLevel(p, 0));
		assertNull("99 has no next level", SessionRow.timeToLevel(XpProgress.of(Experience.getXpForLevel(99)), 50_000));
		assertNull("200m", SessionRow.timeToLevel(XpProgress.of(Experience.MAX_SKILL_XP), 50_000));
	}

	@Test
	public void durations()
	{
		assertEquals("0s", SessionRow.duration(0));
		assertEquals("59s", SessionRow.duration(59_999));
		assertEquals("1m", SessionRow.duration(MINUTE));
		assertEquals("59m", SessionRow.duration(59 * MINUTE + 59_000));
		assertEquals("1h 00m", SessionRow.duration(60 * MINUTE));
		assertEquals("23h 59m", SessionRow.duration(24 * 60 * MINUTE - 1));
		assertEquals("2d 3h", SessionRow.duration((51 * 60 + 30) * MINUTE));
	}

	@Test
	public void cellsInOrderWithEveryHalf()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(61) - 6_000);
		final List<SessionRow.Cell> cells = SessionRow.cells(Skill.FISHING, 24, 3 * MINUTE, 60_000, 459, p,
			true, true, true);
		assertEquals(4, cells.size());
		assertEquals("24 caught in 3m | 60k xp/h | 459 fish/h | lvl 61 in 6m", joined(cells));
		assertEquals(SessionRow.Kind.COUNT, cells.get(0).getKind());
		assertEquals(SessionRow.Kind.TIME_TO_LEVEL, cells.get(3).getKind());
	}

	@Test
	public void cellsHonourTheSwitches()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(18) - 6_000);
		assertEquals("24 caught in 3m", joined(SessionRow.cells(Skill.FISHING, 24, 3 * MINUTE, 60_000, 459, p,
			true, false, true)));
		assertEquals("60k xp/h | 459 fish/h", joined(SessionRow.cells(Skill.FISHING, 24, 3 * MINUTE, 60_000, 459, p,
			false, true, false)));
		assertTrue(SessionRow.cells(Skill.FISHING, 24, 3 * MINUTE, 60_000, 459, p, false, false, true).isEmpty());
	}

	@Test
	public void unknownRatesLeaveOutWhatIsNotKnown()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(18) - 6_000);
		assertEquals("1 caught in 10s", joined(SessionRow.cells(Skill.FISHING, 1, 10_000, -1, -1, p,
			true, true, true)));
	}

	/** Board's screenshots, 2026-11-06: "-- 1 stolen in 3s". Every skill alike: no rate yet, no rate cell. */
	@Test
	public void noSkillShowsAPlaceholderRate()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(18) - 6_000);
		for (Skill skill : new Skill[]{Skill.FISHING, Skill.WOODCUTTING, Skill.MINING, Skill.THIEVING})
		{
			final List<SessionRow.Cell> cells = SessionRow.cells(skill, 1, 3_000, -1, -1, p, true, true, true);
			assertEquals(skill + " has only its count", 1, cells.size());
			assertEquals(SessionRow.Kind.COUNT, cells.get(0).getKind());
			assertTrue(skill + " never shows \"--\"", !cells.get(0).getText().contains("--"));
		}
	}

	@Test
	public void eachStatHasItsOwnSoftShadeOfTheSkillColour()
	{
		final Color skill = new Color(80, 140, 255);
		Color previous = null;
		for (SessionRow.Kind kind : SessionRow.Kind.values())
		{
			final Color c = SessionRow.tint(skill, kind);
			assertTrue(kind + " lighter than the skill", c.getRed() >= skill.getRed() && c.getGreen() >= skill.getGreen());
			assertTrue(kind + " keeps the skill's hue", c.getBlue() >= c.getRed());
			assertNotEquals(kind + " differs from the one before", previous, c);
			previous = c;
		}
	}

	@Test
	public void compactIsOneShortLineOfTheCountAndXpRate()
	{
		assertEquals("24 caught | 10.6k xp/h",
			joined(SessionRow.compactCells(Skill.FISHING, 24, 10_597, true, true)));
	}

	@Test
	public void compactFollowsEachSwitch()
	{
		assertEquals("24 caught", joined(SessionRow.compactCells(Skill.FISHING, 24, 10_597, true, false)));
		assertTrue("no rate yet, nothing shown", SessionRow.compactCells(Skill.FISHING, 24, -1, false, true).isEmpty());
		assertTrue(SessionRow.compactCells(Skill.FISHING, 24, 10_597, false, false).isEmpty());
	}

	private static String joined(List<SessionRow.Cell> cells)
	{
		return cells.stream().map(SessionRow.Cell::getText).collect(Collectors.joining(" | "));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

public class ShortestPathBridgeTest
{
	/** Stands in for Shortest Path's plugin class, matched by name. */
	private static final class FakeShortestPath
	{
	}

	private final List<Object> posted = new ArrayList<>();

	private ShortestPathBridge bridge(List<Object> plugins, boolean enabled)
	{
		return new ShortestPathBridge(() -> plugins, p -> enabled, FakeShortestPath.class.getName(), posted::add);
	}

	@Test
	public void notInstalled()
	{
		final ShortestPathBridge bridge = bridge(Collections.singletonList(new Object()), true);

		assertEquals(ShortestPathBridge.Availability.NOT_INSTALLED, bridge.availability());
		assertEquals(ShortestPathBridge.RouteOutcome.UNAVAILABLE, bridge.route(new WorldPoint(1, 2, 0)));
		assertFalse(bridge.clear());
		assertTrue(posted.isEmpty());
	}

	@Test
	public void installedButOff()
	{
		final ShortestPathBridge bridge = bridge(Collections.singletonList(new FakeShortestPath()), false);

		assertEquals(ShortestPathBridge.Availability.NOT_ENABLED, bridge.availability());
		assertEquals(ShortestPathBridge.RouteOutcome.UNAVAILABLE, bridge.route(new WorldPoint(1, 2, 0)));
		assertTrue(posted.isEmpty());
	}

	@Test
	public void routeSendsTheVerifiedMessageShape()
	{
		final ShortestPathBridge bridge = bridge(Collections.singletonList(new FakeShortestPath()), true);
		final WorldPoint target = new WorldPoint(2844, 3429, 0);

		assertEquals(ShortestPathBridge.RouteOutcome.SENT, bridge.route(target));

		assertEquals(1, posted.size());
		final PluginMessage message = (PluginMessage) posted.get(0);
		assertEquals("shortestpath", message.getNamespace());
		assertEquals("path", message.getName());
		assertEquals(Set.of(target), message.getData().get("target"));
	}

	@Test
	public void clearSendsTheClearMessage()
	{
		final ShortestPathBridge bridge = bridge(Collections.singletonList(new FakeShortestPath()), true);

		assertTrue(bridge.clear());

		final PluginMessage message = (PluginMessage) posted.get(0);
		assertEquals("shortestpath", message.getNamespace());
		assertEquals("clear", message.getName());
	}

	@Test
	public void aThrowingPostIsReportedNotPropagated()
	{
		final ShortestPathBridge bridge = new ShortestPathBridge(() -> Collections.singletonList(new FakeShortestPath()),
			p -> true, FakeShortestPath.class.getName(), m ->
			{
				throw new AssertionError("not on the client thread");
			});

		assertEquals(ShortestPathBridge.RouteOutcome.CALL_FAILED, bridge.route(new WorldPoint(1, 2, 0)));
		assertFalse(bridge.clear());
	}

	@Test
	public void aFailingPluginListReadsAsNotInstalled()
	{
		final ShortestPathBridge bridge = new ShortestPathBridge(() ->
		{
			throw new IllegalStateException("boom");
		}, p -> true, FakeShortestPath.class.getName(), posted::add);

		assertEquals(ShortestPathBridge.Availability.NOT_INSTALLED, bridge.availability());
	}

	@Test
	public void clientThreadPosterDefersThePost()
	{
		final List<Runnable> queued = new ArrayList<>();
		ShortestPathBridge.clientThreadEventPoster(queued::add, posted::add).accept("event");

		assertTrue(posted.isEmpty());
		queued.get(0).run();
		assertEquals(Collections.singletonList("event"), posted);
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.Rectangle;
import org.junit.Test;

/**
 * The expected numbers are Status Bars' own placement
 * ({@code StatusBarsOverlay#render}, {@code Viewport}), worked by hand.
 */
public class SidePillarsTest
{
	private static final int X = 500;
	private static final int Y = 200;
	private static final int W = 240;

	private static SidePillars.StatusBars statusBars(boolean left, boolean right, int width)
	{
		return new SidePillars.StatusBars(true, left, right, width);
	}

	@Test
	public void fixedWithoutStatusBarsTakesBothPillars()
	{
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
			SidePillars.StatusBars.OFF);
		assertEquals(new Rectangle(X - 20, Y + 4, 20, 252), layout.getLeft());
		assertEquals(new Rectangle(X + W, Y + 4, 20, 252), layout.getRight());
	}

	@Test
	public void resizedBoxMatchesFixed()
	{
		final SidePillars.Layout fixed = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
			SidePillars.StatusBars.OFF);
		final SidePillars.Layout box = SidePillars.layout(SidePillars.Viewport.RESIZED_BOX, X, Y, W,
			SidePillars.StatusBars.OFF);
		assertEquals(fixed.getLeft(), box.getLeft());
		assertEquals(fixed.getRight(), box.getRight());
	}

	@Test
	public void resizedBottomWithoutStatusBarsSitsLeftOfThePanel()
	{
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.RESIZED_BOTTOM, 1000, 500, W,
			SidePillars.StatusBars.OFF);
		assertEquals(new Rectangle(1010 - 61, 500, 20, 272), layout.getLeft());
		assertEquals(new Rectangle(1010 - 35, 500, 20, 272), layout.getRight());
	}

	@Test
	public void fixedWithStatusBarsOnBothStacksLeftOfIt()
	{
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
			statusBars(true, true, 20));
		assertEquals(X - 20 - 22, layout.getRight().x);
		assertEquals(X - 20 - 44, layout.getLeft().x);
		assertEquals(Y + 4, layout.getLeft().y);
	}

	@Test
	public void fixedWithOnlyTheRightStatusBarUsesTheFreeLeftPillar()
	{
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
			statusBars(false, true, 20));
		assertEquals(X - 20, layout.getRight().x);
		assertEquals(X - 20 - 22, layout.getLeft().x);
	}

	@Test
	public void statusBarsWithBothBarsDisabledLeavesThePillarsFree()
	{
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
			statusBars(false, false, 20));
		assertEquals(X - 20, layout.getLeft().x);
		assertEquals(X + W, layout.getRight().x);
	}

	@Test
	public void resizedBottomFollowsStatusBarsWidth()
	{
		// Width 30: Status Bars' left bar moves 2 x 10 further left.
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.RESIZED_BOTTOM, 1000, 500, W,
			statusBars(true, true, 30));
		assertEquals(1010 - 61 - 20 - 22, layout.getRight().x);
		assertEquals(1010 - 61 - 20 - 44, layout.getLeft().x);
		assertEquals(272, layout.getLeft().height);
	}

	@Test
	public void neverOverlapsStatusBarsOrItself()
	{
		final boolean[] flags = {false, true};
		for (SidePillars.Viewport viewport : SidePillars.Viewport.values())
		{
			for (boolean left : flags)
			{
				for (boolean right : flags)
				{
					for (int width : new int[] {3, 20, 40})
					{
						checkNoOverlap(viewport, statusBars(left, right, width));
					}
				}
			}
		}
	}

	private static void checkNoOverlap(SidePillars.Viewport viewport, SidePillars.StatusBars statusBars)
	{
		final String at = viewport + " " + statusBars.left + "/" + statusBars.right + " w" + statusBars.width;
		final SidePillars.Layout ours = SidePillars.layout(viewport, X, Y, W, statusBars);
		final Rectangle[] theirs = SidePillars.statusBarSlots(viewport, X, Y, W, statusBars);
		assertFalse(at, ours.getLeft().intersects(ours.getRight()));
		assertTrue(at, ours.getLeft().x < ours.getRight().x);
		if (statusBars.left)
		{
			assertFalse(at, ours.getLeft().intersects(theirs[0]));
			assertFalse(at, ours.getRight().intersects(theirs[0]));
		}
		if (statusBars.right)
		{
			assertFalse(at, ours.getLeft().intersects(theirs[1]));
			assertFalse(at, ours.getRight().intersects(theirs[1]));
		}
	}

	@Test
	public void neverOverTheSidePanelInTheClassicLayouts()
	{
		for (boolean left : new boolean[] {false, true})
		{
			for (boolean right : new boolean[] {false, true})
			{
				final SidePillars.Layout ours = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
					statusBars(left, right, 20));
				final Rectangle panel = new Rectangle(X, Y, W, 300);
				assertFalse(ours.getLeft().intersects(panel));
				assertFalse(ours.getRight().intersects(panel));
			}
		}
	}

	@Test
	public void sidesPickTheirBar()
	{
		final SidePillars.Layout layout = SidePillars.layout(SidePillars.Viewport.FIXED, X, Y, W,
			SidePillars.StatusBars.OFF);
		assertEquals(layout.getLeft(), layout.get(PillarSide.LEFT));
		assertEquals(layout.getRight(), layout.get(PillarSide.RIGHT));
		assertEquals(PillarSide.RIGHT, PillarSide.LEFT.other());
	}
}

package com.vinnyvangogh.combatvitals;

import java.awt.Color;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

public class SkillColoursTest
{
	/** WCAG 2 minimum for large or bold text, which the badge's bold font is. */
	private static final double MIN_CONTRAST = 3.0;

	@Test
	public void eachBadgeSkillHasItsOwnColour()
	{
		final Skill[] skills = {Skill.FISHING, Skill.WOODCUTTING, Skill.MINING, Skill.THIEVING,
			Skill.HUNTER, Skill.RUNECRAFT};
		for (int i = 0; i < skills.length; i++)
		{
			assertNotEquals(skills[i] + " falls back to the default", SkillColours.DEFAULT, SkillColours.of(skills[i]));
			for (int j = i + 1; j < skills.length; j++)
			{
				assertNotEquals(skills[i] + " and " + skills[j], SkillColours.of(skills[i]), SkillColours.of(skills[j]));
			}
		}
	}

	@Test
	public void fishingIsBlueAndWoodcuttingGreen()
	{
		final Color fishing = SkillColours.of(Skill.FISHING);
		assertTrue(fishing.getBlue() > fishing.getRed() && fishing.getBlue() > fishing.getGreen());
		final Color woodcutting = SkillColours.of(Skill.WOODCUTTING);
		assertTrue(woodcutting.getGreen() > woodcutting.getRed() && woodcutting.getGreen() > woodcutting.getBlue());
	}

	@Test
	public void unknownSkillGetsTheDefault()
	{
		assertEquals(SkillColours.DEFAULT, SkillColours.of(Skill.ATTACK));
		assertEquals(SkillColours.DEFAULT, SkillColours.of(null));
	}

	@Test
	public void everyColourReadsOnLightAndDarkGround()
	{
		// Text-only styles draw the colour straight onto the game world, which
		// can be snow or a cave; the bar style puts white text on the colour.
		for (Skill skill : Skill.values())
		{
			final Color c = SkillColours.of(skill);
			assertTrue(skill + " on white: " + SkillColours.contrast(c, Color.WHITE),
				SkillColours.contrast(c, Color.WHITE) >= MIN_CONTRAST);
			assertTrue(skill + " on black: " + SkillColours.contrast(c, Color.BLACK),
				SkillColours.contrast(c, Color.BLACK) >= MIN_CONTRAST);
		}
	}

	@Test
	public void contrastMatchesTheWcagFormula()
	{
		assertEquals(21.0, SkillColours.contrast(Color.BLACK, Color.WHITE), 1e-9);
		assertEquals(1.0, SkillColours.contrast(Color.GRAY, Color.GRAY), 1e-9);
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * The fishing spot shows the Fishing badge and not the health bar; the
 * goblin shows the health bar and not a badge. Both decisions come from the
 * NPC's menu, so both are testable without a client.
 */
public class SkillingActionsTest
{
	private static final String[] FISHING_SPOT = {"Net", "Bait", null, null, null};
	private static final String[] HARPOON_SPOT = {"Cage", "Harpoon", null, null, null};
	private static final String[] BARBARIAN_SPOT = {"Use-rod", null, null, null, null};
	private static final String[] GOBLIN = {"Attack", null, "Talk-to", null, null};
	private static final String[] BANKER = {"Bank", "Talk-to", "Collect", null, null};
	private static final String[] MAN = {"Talk-to", "Attack", "Pickpocket", null, null};
	private static final String[] IMPLING = {"Catch", null, null, null, null};

	@Test
	public void fishingSpotShowsTheFishingBadgeNotTheHealthBar()
	{
		assertFalse("not a fight", CombatState.attackable(FISHING_SPOT, -1));
		assertEquals(Skill.FISHING, SkillingActions.skill(FISHING_SPOT, "Fishing spot"));
	}

	@Test
	public void everyFishingStyleIsFishing()
	{
		assertEquals(Skill.FISHING, SkillingActions.skill(HARPOON_SPOT, "Fishing spot"));
		assertEquals(Skill.FISHING, SkillingActions.skill(BARBARIAN_SPOT, "Fishing spot"));
		assertEquals(Skill.FISHING, SkillingActions.skill(new String[] {"Big Net", "Harpoon"}, "Fishing spot"));
		assertEquals(Skill.FISHING, SkillingActions.skill(new String[] {"Small Net", "Bait"}, "Fishing spot"));
		assertEquals(Skill.FISHING, SkillingActions.skill(new String[] {"Lure", "Bait"}, "Rod Fishing spot"));
		assertEquals(Skill.FISHING, SkillingActions.skill(new String[] {"Fish", null}, "Fishing spot"));
	}

	@Test
	public void combatTargetStillShowsTheHealthBar()
	{
		assertTrue(CombatState.attackable(GOBLIN, 2));
		assertNull("no badge for a goblin", SkillingActions.skill(GOBLIN, "Goblin"));
	}

	@Test
	public void bankerShowsNeither()
	{
		assertFalse(CombatState.attackable(BANKER, -1));
		assertNull(SkillingActions.skill(BANKER, "Banker"));
	}

	@Test
	public void pickpocketIsThieving()
	{
		assertEquals(Skill.THIEVING, SkillingActions.skill(MAN, "Man"));
	}

	@Test
	public void theClickedOptionDecidesForAnAttackableNpc()
	{
		// A Man can be fought and pickpocketed. The option clicked says which.
		assertEquals(Skill.THIEVING, SkillingActions.forOption("Pickpocket", "Man"));
		assertNull("Attack is a fight, not a skill", SkillingActions.forOption("Attack", "Man"));
		assertNull(SkillingActions.forOption("Talk-to", "Man"));
	}

	@Test
	public void objectOptionsNameTheirSkill()
	{
		assertEquals(Skill.WOODCUTTING, SkillingActions.forOption("Chop down", "Yew tree"));
		assertEquals(Skill.WOODCUTTING, SkillingActions.forOption("Chop", "Redwood tree"));
		assertEquals(Skill.MINING, SkillingActions.forOption("Mine", "Iron rocks"));
		assertEquals(Skill.THIEVING, SkillingActions.forOption("Steal-from", "Silk stall"));
		assertEquals(Skill.RUNECRAFT, SkillingActions.forOption("Craft-rune", "Altar"));
	}

	@Test
	public void unknownObjectOptionsAreNothing()
	{
		assertNull(SkillingActions.forOption("Bank", "Bank booth"));
		assertNull(SkillingActions.forOption("Open", "Door"));
		assertNull(SkillingActions.forOption("Prospect", "Iron rocks"));
		assertNull(SkillingActions.forOption(null, "Yew tree"));
	}

	@Test
	public void catchIsHunterUnlessItIsAShoal()
	{
		assertEquals(Skill.HUNTER, SkillingActions.skill(IMPLING, "Baby impling"));
		assertEquals(Skill.FISHING, SkillingActions.skill(IMPLING, "Fish shoal"));
	}

	@Test
	public void matchingIgnoresCase()
	{
		assertEquals(Skill.FISHING, SkillingActions.skill(new String[] {"NET"}, null));
	}

	@Test
	public void nullsAreNothing()
	{
		assertNull(SkillingActions.skill(null, "Fishing spot"));
		assertNull(SkillingActions.skill(new String[] {null, null}, null));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

public class SkillingSessionTest
{
	private static final long MINUTE = 60_000;

	private SkillingSession session;

	@Before
	public void setUp()
	{
		session = new SkillingSession();
	}

	@Test
	public void theFirstReadingIsABaselineNotAGain()
	{
		session.xp(Skill.FISHING, 1_000_000, 0);
		assertEquals(0, session.actions(Skill.FISHING));
	}

	@Test
	public void everyGainIsOneAction()
	{
		session.xp(Skill.FISHING, 1000, 0);
		session.xp(Skill.FISHING, 1050, 1000);
		session.xp(Skill.FISHING, 1100, 2000);
		assertEquals(2, session.actions(Skill.FISHING));
	}

	@Test
	public void aRepeatOfTheSameXpIsNoAction()
	{
		// StatChanged fires for boosts with the experience unchanged.
		session.xp(Skill.FISHING, 1000, 0);
		session.xp(Skill.FISHING, 1000, 1000);
		assertEquals(0, session.actions(Skill.FISHING));
	}

	@Test
	public void skillsAreCountedApart()
	{
		session.xp(Skill.FISHING, 1000, 0);
		session.xp(Skill.COOKING, 1000, 0);
		session.xp(Skill.COOKING, 1100, 1000);
		assertEquals(0, session.actions(Skill.FISHING));
		assertEquals(1, session.actions(Skill.COOKING));
	}

	@Test
	public void ratesAreUnknownUntilAMinuteHasPassed()
	{
		session.xp(Skill.FISHING, 0, 0);
		session.xp(Skill.FISHING, 50, 0);
		session.xp(Skill.FISHING, 100, 30_000);
		assertEquals(-1, session.xpPerHour(Skill.FISHING, 59_999));
		assertEquals(-1, session.actionsPerHour(Skill.FISHING, 59_999));
	}

	@Test
	public void xpPerHourCountsFromTheFirstGain()
	{
		// First gain at t=0 starts the clock; its own 50 xp were earned before
		// the clock started, so only the 10 gains after it count.
		session.xp(Skill.FISHING, 0, 0);
		session.xp(Skill.FISHING, 50, 0);
		for (int i = 1; i <= 10; i++)
		{
			session.xp(Skill.FISHING, 50 + i * 50, i * 6_000L);
		}

		// 500 xp and 10 actions in one minute.
		assertEquals(30_000, session.xpPerHour(Skill.FISHING, MINUTE));
		assertEquals(600, session.actionsPerHour(Skill.FISHING, MINUTE));
		assertEquals(11, session.actions(Skill.FISHING));
	}

	@Test
	public void ratesFallWhileYouStandStill()
	{
		session.xp(Skill.MINING, 0, 0);
		session.xp(Skill.MINING, 100, 0);
		session.xp(Skill.MINING, 200, MINUTE);
		assertEquals(6_000, session.xpPerHour(Skill.MINING, MINUTE));
		assertEquals(3_000, session.xpPerHour(Skill.MINING, 2 * MINUTE));
	}

	@Test
	public void resetZeroesTheCountersButKeepsTheBaseline()
	{
		session.xp(Skill.FISHING, 1000, 0);
		session.xp(Skill.FISHING, 1100, 1000);
		session.reset();
		assertEquals(0, session.actions(Skill.FISHING));

		// The baseline survives: the next drop is one action, not a jump from 0.
		session.xp(Skill.FISHING, 1150, 2000);
		assertEquals(1, session.actions(Skill.FISHING));
	}

	@Test
	public void clearForgetsTheBaselineToo()
	{
		session.xp(Skill.FISHING, 1000, 0);
		session.clear();
		session.xp(Skill.FISHING, 5000, 1000);
		assertEquals(0, session.actions(Skill.FISHING));
	}

	@Test
	public void anUnseenSkillHasNoRate()
	{
		assertEquals(0, session.actions(Skill.HUNTER));
		assertEquals(-1, session.xpPerHour(Skill.HUNTER, MINUTE));
	}
}

package com.vinnyvangogh.combatvitals;

