	private static final Instant T0 = Instant.parse("2026-11-02T12:00:00Z");

	private static final String[] FISHING_SPOT = {"Net", "Bait", null, null, null};
	private static final String[] GOBLIN = {"Attack", null, "Talk-to", null, null};

