package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/**
 * Board's in-game test, 2026-11-06: a stun or a hit while thieving counted
 * as combat and hid the skilling badge ("Hide during combat").
 */
public class ThievingHitsTest
{
	/** A scene: who each actor is interacting with, and which can fight. */
	private static final class Scene
	{
		final Map<Object, Object> interacting = new IdentityHashMap<>();
		final Set<Object> fighters = Collections.newSetFromMap(new IdentityHashMap<>());

		Object actor(boolean canFight, Object target)
		{
			final Object actor = new Object();
			interacting.put(actor, target);
			if (canFight)
			{
				fighters.add(actor);
			}
			return actor;
		}

		boolean otherAttacker(List<Object> actors, Object self, Object target)
		{
			return ThievingHits.otherAttacker(actors, self, target, fighters::contains, interacting::get);
		}
	}

	private final Object self = new Object();

	@Test
	public void aStunWhilePickpocketingIsNotAFight()
	{
		assertFalse(ThievingHits.isFight(true, true, false));
	}

	@Test
	public void aHitWhileNotThievingIsAFight()
	{
		assertTrue(ThievingHits.isFight(true, false, false));
	}

	@Test
	public void yourOwnHitIsAlwaysAFight()
	{
		assertTrue(ThievingHits.isFight(false, true, false));
	}

	@Test
	public void someoneElseOnYouWhileThievingIsAFight()
	{
		assertTrue(ThievingHits.isFight(true, true, true));
	}

	@Test
	public void theTargetTurningToYouAfterAStunIsNotAnotherAttacker()
	{
		final Scene scene = new Scene();
		final Object man = scene.actor(true, self);

		assertFalse(scene.otherAttacker(Arrays.asList(self, man), self, man));
	}

	@Test
	public void aGuardOnYouAtAStallIsAnotherAttacker()
	{
		final Scene scene = new Scene();
		final Object guard = scene.actor(true, self);

		assertTrue(scene.otherAttacker(Arrays.asList(self, guard), self, null));
	}

	@Test
	public void aPetFollowingYouIsNot()
	{
		final Scene scene = new Scene();
		final Object pet = scene.actor(false, self);

		assertFalse(scene.otherAttacker(Arrays.asList(self, pet), self, null));
	}

	@Test
	public void aCrowdFightingEachOtherIsNotOnYou()
	{
		final Scene scene = new Scene();
		final Object man = scene.actor(true, null);
		final Set<Object> crowd = new HashSet<>();
		Object previous = scene.actor(true, null);
		crowd.add(previous);
		for (int i = 0; i < 20; i++)
		{
			final Object next = scene.actor(true, previous);
			crowd.add(next);
			previous = next;
		}
		final List<Object> actors = new java.util.ArrayList<>(crowd);
		actors.add(self);
		actors.add(man);

		assertFalse(scene.otherAttacker(actors, self, man));

		actors.add(scene.actor(true, self));
		assertTrue("one of them turning on you is", scene.otherAttacker(actors, self, man));
	}
}

package com.vinnyvangogh.combatvitals;

import java.io.Reader;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Properties;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The "what's new" chat lines: once per version, never with the toggle off,
 * and a single welcome line, not the whole list, for a fresh install.
 */
public class UpdateNotesTest
{
	private static final String NEVER_SEEN = "";

	@Test
	public void versionIsThePluginPropertiesVersion() throws Exception
	{
		final Properties properties = new Properties();
		try (Reader reader = Files.newBufferedReader(Paths.get("runelite-plugin.properties")))
		{
			properties.load(reader);
		}
		assertEquals(properties.getProperty("version"), UpdateNotes.VERSION);
	}

	@Test
	public void hubUpgradeFrom100ShowsTheTitleThenTheNotes()
	{
		// 1.0.0 never stored a version, and an update lands while the client
		// restarts, so the plugin starts on the login screen.
		final List<String> lines = UpdateNotes.toShow(NEVER_SEEN, true, false);

		assertEquals(UpdateNotes.TITLE, lines.get(0));
		assertTrue("title plus 4-6 lines, got " + lines.size(), lines.size() >= 5 && lines.size() <= 7);
		assertEquals(UpdateNotes.NOTES, lines.subList(1, lines.size()));
	}

	@Test
	public void aStoredOlderVersionShowsTheNotesWhereverThePluginStarted()
	{
		assertEquals(UpdateNotes.TITLE, UpdateNotes.toShow("1.0.9", true, false).get(0));
		assertEquals(UpdateNotes.TITLE, UpdateNotes.toShow("1.0.9", true, true).get(0));
	}

	@Test
	public void theSeenVersionShowsNothing()
	{
		assertTrue(UpdateNotes.toShow(UpdateNotes.VERSION, true, false).isEmpty());
		assertTrue(UpdateNotes.toShow(UpdateNotes.VERSION, true, true).isEmpty());
	}

	@Test
	public void theToggleOffShowsNothing()
	{
		assertTrue(UpdateNotes.toShow(NEVER_SEEN, false, false).isEmpty());
		assertTrue(UpdateNotes.toShow(NEVER_SEEN, false, true).isEmpty());
		assertTrue(UpdateNotes.toShow("1.0.9", false, false).isEmpty());
	}

	@Test
	public void aFreshInstallGetsOneWelcomeLine()
	{
		// Installed from the Plugin Hub panel while logged in: no stored version.
		final List<String> lines = UpdateNotes.toShow(NEVER_SEEN, true, true);

		assertEquals(1, lines.size());
		assertEquals(UpdateNotes.WELCOME, lines.get(0));
	}

	@Test
	public void showsOnceAcrossLoginsAndHops()
	{
		final List<String> posted = new ArrayList<>();
		String stored = NEVER_SEEN;
		for (int login = 0; login < 4; login++)
		{
			posted.addAll(UpdateNotes.toShow(stored, true, false));
			if (UpdateNotes.needsRecord(stored))
			{
				stored = UpdateNotes.VERSION;
			}
		}

		assertEquals(UpdateNotes.toShow(NEVER_SEEN, true, false), posted);
	}

	@Test
	public void theToggleOffStillRecordsTheVersion()
	{
		// Turned off now, back on later: the old notes must not appear then.
		assertTrue(UpdateNotes.needsRecord(NEVER_SEEN));
		assertTrue(UpdateNotes.needsRecord("1.0.9"));
		assertFalse(UpdateNotes.needsRecord(UpdateNotes.VERSION));
	}

	@Test
	public void notesAreFeaturesShortAndEndWithWhereToTurnThemOn()
	{
		for (String line : UpdateNotes.NOTES)
		{
			assertTrue("too long for a chat line: " + line, line.length() <= 110);
			assertFalse("1.0.0 users never saw a bug, so nothing is a fix: " + line,
				line.toLowerCase(Locale.ROOT).contains("fix"));
		}
		assertTrue(UpdateNotes.NOTES.get(UpdateNotes.NOTES.size() - 1)
			.contains("Configure Combat Vitals > Skilling badge"));
		assertTrue(UpdateNotes.TITLE.contains(UpdateNotes.VERSION));
		assertTrue(UpdateNotes.WELCOME.contains(UpdateNotes.VERSION));
	}
}

package com.vinnyvangogh.combatvitals;

import static org.junit.Assert.assertEquals;
import net.runelite.api.Experience;
import org.junit.Test;

public class XpProgressTest
{
	private static final double EPSILON = 1e-9;

	@Test
	public void freshSkillIsLevelOneWithNothingDone()
	{
		final XpProgress p = XpProgress.of(0);
		assertEquals(1, p.getLevel());
		assertEquals(2, p.getNextLevel());
		assertEquals(0.0, p.getFraction(), EPSILON);
		assertEquals(83, p.getXpLeft());
		assertEquals("Lv 1 -> 2: 0% (83 xp)", p.text());
	}

	@Test
	public void exactlyOnALevelBoundaryStartsTheNextLevelAtZero()
	{
		final int lv13 = Experience.getXpForLevel(13);
		final XpProgress p = XpProgress.of(lv13);
		assertEquals(13, p.getLevel());
		assertEquals(0.0, p.getFraction(), EPSILON);
		assertEquals(Experience.getXpForLevel(14) - lv13, p.getXpLeft());
	}

	@Test
	public void oneXpShortOfALevelIsNeverShownAsAHundredPercent()
	{
		final int lv13 = Experience.getXpForLevel(13);
		final XpProgress p = XpProgress.of(lv13 - 1);
		assertEquals(12, p.getLevel());
		assertEquals(1, p.getXpLeft());
		assertEquals("Lv 12 -> 13: 99% (1 xp)", p.text());
	}

	@Test
	public void midLevelFractionIsTheShareOfThisLevelsXp()
	{
		final int from = Experience.getXpForLevel(12);
		final int to = Experience.getXpForLevel(13);
		final int xp = from + (to - from) / 2;
		final XpProgress p = XpProgress.of(xp);
		assertEquals(12, p.getLevel());
		assertEquals((double) (xp - from) / (to - from), p.getFraction(), EPSILON);
	}

	@Test
	public void largeXpLeftIsGroupedForReading()
	{
		final XpProgress p = XpProgress.of(Experience.getXpForLevel(80));
		assertEquals("Lv 80 -> 81: 0% (" + String.format("%,d", p.getXpLeft()) + " xp)", p.text());
	}

	@Test
	public void ninetyNineCountsTowardTwoHundredMillion()
	{
		final int lv99 = Experience.getXpForLevel(Experience.MAX_REAL_LEVEL);
		final XpProgress p = XpProgress.of(lv99);
		assertEquals(99, p.getLevel());
		assertEquals(-1, p.getNextLevel());
		assertEquals(0.0, p.getFraction(), EPSILON);
		assertEquals(Experience.MAX_SKILL_XP - lv99, p.getXpLeft());
		assertEquals("Lv 99 -> 200m: 0%", p.text());
	}

	@Test
	public void virtualLevelsStillReadAsNinetyNine()
	{
		// 50m xp is virtual level 110+; the badge's real level stops at 99.
		final XpProgress p = XpProgress.of(50_000_000);
		assertEquals(99, p.getLevel());
		assertEquals("Lv 99 -> 200m: 19%", p.text());
	}

	@Test
	public void twoHundredMillionIsFullAndSaysSo()
	{
		final XpProgress p = XpProgress.of(Experience.MAX_SKILL_XP);
		assertEquals(1.0, p.getFraction(), EPSILON);
		assertEquals(0, p.getXpLeft());
		assertEquals("Lv 99: 200m xp", p.text());
	}

	@Test
	public void negativeXpIsTreatedAsNone()
	{
		assertEquals(1, XpProgress.of(-5).getLevel());
		assertEquals(0.0, XpProgress.of(-5).getFraction(), EPSILON);
	}
}
